static const char nx_str_879[11343] = "// std.text: UTF-8 text by code point, written in Nexium.\n//\n// `import std.text` then:\n//\n//     let n = text.char_count(\"h\303\251llo\")            // 5, not 6\n//     for cp in text.chars(\"h\303\251llo\") { ... }        // code points as u32\n//     let w = text.width(\"\346\227\245\346\234\254\350\252\236\")                   // 6 columns on a terminal\n//     let s = text.to_upper(\"stra\303\237e\")               // \"STRASSE\" is not attempted: \"STRA\303\237E\"\n//     let t = text.truncate(\"h\303\251llo w\303\266rld\", 5)       // \"h\303\251llo\", never mid-character\n//     let ok = text.is_valid(\"...\")\n//\n// Strings are bytes; this module reads them as UTF-8, tolerating bad input\n// (an invalid byte decodes as U+FFFD and advances one byte). Case mapping\n// covers ASCII, Latin-1, Latin Extended-A, Greek and Cyrillic, which is what\n// is cheap to do without tables. `width` follows the usual terminal\n// convention: East Asian wide and fullwidth forms take two columns,\n// combining marks and zero-width characters take none.\n\npub const REPLACEMENT: u32 = 0xFFFD\n\n/// A decoded code point and the number of bytes it took.\npub struct Decoded {\n    cp: u32\n    len: usize\n}\n\n/// Decode the code point starting at byte `i`. Invalid input yields\n/// U+FFFD with length 1 so callers always make progress.\npub fn decode_at(s: []u8, i: usize) -> Decoded {\n    if i >= s.len { return Decoded{ .cp = REPLACEMENT, .len = 0 } }\n    let b0 = s[i]\n    if b0 < 0x80 { return Decoded{ .cp = b0 as u32, .len = 1 } }\n    var need: usize = 0\n    var cp: u32 = 0\n    var min: u32 = 0\n    if b0 >= 0xC2 and b0 <= 0xDF {\n        need = 1\n        cp = (b0 & 0x1F) as u32\n        min = 0x80\n    } else if b0 >= 0xE0 and b0 <= 0xEF {\n        need = 2\n        cp = (b0 & 0x0F) as u32\n        min = 0x800\n    } else if b0 >= 0xF0 and b0 <= 0xF4 {\n        need = 3\n        cp = (b0 & 0x07) as u32\n        min = 0x10000\n    } else {\n        return Decoded{ .cp = REPLACEMENT, .len = 1 }\n    }\n    var k: usize = 1\n    while k <= need {\n        if i + k >= s.len { return Decoded{ .cp = REPLACEMENT, .len = 1 } }\n        let b = s[i + k]\n        if b < 0x80 or b > 0xBF { return Decoded{ .cp = REPLACEMENT, .len = 1 } }\n        cp = (cp << 6) | ((b & 0x3F) as u32)\n        k += 1\n    }\n    if cp < min or cp > 0x10FFFF or (cp >= 0xD800 and cp <= 0xDFFF) { return Decoded{ .cp = REPLACEMENT, .len = 1 } }\n    return Decoded{ .cp = cp, .len = need + 1 }\n}\n\n/// Append a code point as UTF-8.\npub fn push(out: *mut String, cp: u32) {\n    if cp < 0x80 {\n        out.push_byte(cp as u8)\n    } else if cp < 0x800 {\n        out.push_byte((0xC0 | (cp >> 6)) as u8)\n        out.push_byte((0x80 | (cp & 0x3F)) as u8)\n    } else if cp < 0x10000 {\n        out.push_byte((0xE0 | (cp >> 12)) as u8)\n        out.push_byte((0x80 | ((cp >> 6) & 0x3F)) as u8)\n        out.push_byte((0x80 | (cp & 0x3F)) as u8)\n    } else {\n        out.push_byte((0xF0 | (cp >> 18)) as u8)\n        out.push_byte((0x80 | ((cp >> 12) & 0x3F)) as u8)\n        out.push_byte((0x80 | ((cp >> 6) & 0x3F)) as u8)\n        out.push_byte((0x80 | (cp & 0x3F)) as u8)\n    }\n}\n\n/// A code point as a String.\npub fn encode(cp: u32) -> String {\n    var out = String.new()\n    push(&mut out, cp)\n    return out\n}\n\n/// Is the text well-formed UTF-8?\npub fn is_valid(s: []u8) -> bool {\n    var i: usize = 0\n    while i < s.len {\n        let d = decode_at(s, i)\n        if d.cp == REPLACEMENT and (d.len == 1 and s[i] != 0xEF) { return false }\n        i += d.len\n    }\n    return true\n}\n\n/// All code points.\npub fn chars(s: []u8) -> List(u32) {\n    var out = List(u32).new()\n    var i: usize = 0\n    while i < s.len {\n        let d = decode_at(s, i)\n        out.append(d.cp)\n        i += d.len\n    }\n    return out\n}\n\n/// The number of code points.\npub fn char_count(s: []u8) -> usize {\n    var n: usize = 0\n    var i: usize = 0\n    while i < s.len {\n        i += decode_at(s, i).len\n        n += 1\n    }\n    return n\n}\n\n/// The byte offset of the `n`th code point (or `s.len` when past the end).\npub fn byte_offset(s: []u8, n: usize) -> usize {\n    var i: usize = 0\n    var k: usize = 0\n    while i < s.len and k < n {\n        i += decode_at(s, i).len\n        k += 1\n    }\n    return i\n}\n\n/// The `n`th code point, or null.\npub fn char_at(s: []u8, n: usize) -> ?u32 {\n    let i = byte_offset(s, n)\n    if i >= s.len { return null }\n    return decode_at(s, i).cp\n}\n\n/// Code points `from` (inclusive) to `to` (exclusive), as a slice of `s`.\npub fn slice(s: []u8, from: usize, to: usize) -> []u8 {\n    let a = byte_offset(s, from)\n    let b = byte_offset(s, to)\n    if b < a { return s[a..a] }\n    return s[a..b]\n}\n\n/// The first `n` code points; never cuts a character in half.\npub fn truncate(s: []u8, n: usize) -> []u8 {\n    return s[0..byte_offset(s, n)]\n}\n\n/// The code points in reverse order.\npub fn reverse(s: []u8) -> String {\n    let cps = chars(s)\n    var out = String.with_capacity(s.len)\n    var i = cps.len\n    while i > 0 {\n        i -= 1\n        push(&mut out, cps[i])\n    }\n    return out\n}\n\n// ------------------------------------------------------------------ width\n\nfn in_range(cp: u32, lo: u32, hi: u32) -> bool {\n    return cp >= lo and cp <= hi\n}\n\n/// Does the code point take no columns (combining marks, zero-width, controls)?\npub fn is_zero_width(cp: u32) -> bool {\n    if cp == 0 or cp == 0x200B or cp == 0x200C or cp == 0x200D or cp == 0xFEFF { return true }\n    if cp < 0x20 or in_range(cp, 0x7F, 0x9F) { return true }\n    return in_range(cp, 0x0300, 0x036F) or in_range(cp, 0x0483, 0x0489) or in_range(cp, 0x0591, 0x05BD)\n        or in_range(cp, 0x0610, 0x061A) or in_range(cp, 0x064B, 0x065F) or in_range(cp, 0x0E31, 0x0E3A)\n        or in_range(cp, 0x1AB0, 0x1AFF) or in_range(cp, 0x1DC0, 0x1DFF) or in_range(cp, 0x20D0, 0x20FF)\n        or in_range(cp, 0xFE00, 0xFE0F) or in_range(cp, 0xFE20, 0xFE2F) or in_range(cp, 0xE0100, 0xE01EF)\n}\n\n/// Does the code point take two columns (East Asian wide and fullwidth)?\npub fn is_wide(cp: u32) -> bool {\n    return in_range(cp, 0x1100, 0x115F) or in_range(cp, 0x2E80, 0x303E) or in_range(cp, 0x3041, 0x33FF)\n        or in_range(cp, 0x3400, 0x4DBF) or in_range(cp, 0x4E00, 0x9FFF) or in_range(cp, 0xA000, 0xA4CF)\n        or in_range(cp, 0xAC00, 0xD7A3) or in_range(cp, 0xF900, 0xFAFF) or in_range(cp, 0xFE30, 0xFE4F)\n        or in_range(cp, 0xFF00, 0xFF60) or in_range(cp, 0xFFE0, 0xFFE6) or in_range(cp, 0x1F300, 0x1F64F)\n        or in_range(cp, 0x1F900, 0x1F9FF) or in_range(cp, 0x20000, 0x2FFFD) or in_range(cp, 0x30000, 0x3FFFD)\n}\n\n/// Columns a code point takes on a terminal: 0, 1 or 2.\npub fn char_width(cp: u32) -> usize {\n    if is_zero_width(cp) { return 0 }\n    if is_wide(cp) { return 2 }\n    return 1\n}\n\n/// Columns the text takes on a terminal.\npub fn width(s: []u8) -> usize {\n    var w: usize = 0\n    var i: usize = 0\n    while i < s.len {\n        let d = decode_at(s, i)\n        w += char_width(d.cp)\n        i += d.len\n    }\n    return w\n}\n\n/// Pad on the right to `columns` terminal columns (by width, not bytes).\npub fn pad_right(s: []u8, columns: usize) -> String {\n    var out = String.from(s)\n    var w = width(s)\n    while w < columns {\n        out.push_byte(' ')\n        w += 1\n    }\n    return out\n}\n\n// ------------------------------------------------------------------ case\n\n/// Upper-case a code point where the mapping is a fixed offset: ASCII,\n/// Latin-1, Latin Extended-A (pairs), Greek, Cyrillic.\npub fn upper_char(cp: u32) -> u32 {\n    if in_range(cp, 'a' as u32, 'z' as u32) { return cp - 32 }\n    if cp < 0x80 { return cp }\n    if in_range(cp, 0xE0, 0xFE) and cp != 0xF7 { return cp - 32 }\n    if cp == 0xFF { return 0x178 }\n    if in_range(cp, 0x100, 0x137) or in_range(cp, 0x14A, 0x177) { return if cp % 2 == 1 { cp - 1 } else { cp } }\n    if in_range(cp, 0x139, 0x148) or in_range(cp, 0x179, 0x17E) { return if cp % 2 == 0 { cp - 1 } else { cp } }\n    if in_range(cp, 0x3B1, 0x3C9) and cp != 0x3C2 { return cp - 32 }\n    if cp == 0x3C2 { return 0x3A3 }\n    if in_range(cp, 0x430, 0x44F) { return cp - 32 }\n    if in_range(cp, 0x450, 0x45F) { return cp - 80 }\n    return cp\n}\n\n/// Lower-case a code point; the inverse of `upper_char`.\npub fn lower_char(cp: u32) -> u32 {\n    if in_range(cp, 'A' as u32, 'Z' as u32) { return cp + 32 }\n    if cp < 0x80 { return cp }\n    if in_range(cp, 0xC0, 0xDE) and cp != 0xD7 { return cp + 32 }\n    if cp == 0x178 { return 0xFF }\n    if in_range(cp, 0x100, 0x137) or in_range(cp, 0x14A, 0x177) { return if cp % 2 == 0 { cp + 1 } else { cp } }\n    if in_range(cp, 0x139, 0x148) or in_range(cp, 0x179, 0x17E) { return if cp % 2 == 1 { cp + 1 } else { cp } }\n    if in_range(cp, 0x391, 0x3A9) { return cp + 32 }\n    if in_range(cp, 0x410, 0x42F) { return cp + 32 }\n    if in_range(cp, 0x400, 0x40F) { return cp + 80 }\n    return cp\n}\n\nfn map_chars(s: []u8, upper: bool) -> String {\n    var out = String.with_capacity(s.len)\n    var i: usize = 0\n    while i < s.len {\n        let d = decode_at(s, i)\n        push(&mut out, if upper { upper_char(d.cp) } else { lower_char(d.cp) })\n        i += d.len\n    }\n    return out\n}\n\npub fn to_upper(s: []u8) -> String {\n    return map_chars(s, true)\n}\n\npub fn to_lower(s: []u8) -> String {\n    return map_chars(s, false)\n}\n\n/// Compare ignoring case, using the same mapping as `to_lower`.\npub fn eq_ignore_case(a: []u8, b: []u8) -> bool {\n    var i: usize = 0\n    var j: usize = 0\n    while i < a.len and j < b.len {\n        let x = decode_at(a, i)\n        let y = decode_at(b, j)\n        if lower_char(x.cp) != lower_char(y.cp) { return false }\n        i += x.len\n        j += y.len\n    }\n    return i == a.len and j == b.len\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"decode and encode\" {\n    expect_eq(char_count(\"h\303\251llo\"), 5)\n    expect_eq(char_count(\"\346\227\245\346\234\254\350\252\236\"), 3)\n    expect_eq(chars(\"a\303\251\346\227\245\360\237\230\200\").len, 4)\n    expect_eq(chars(\"a\303\251\346\227\245\360\237\230\200\")[3], 0x1F600)\n    expect_eq(encode(0xE9), \"\303\251\")\n    expect_eq(encode(0x65E5), \"\346\227\245\")\n    expect_eq(encode(0x1F600), \"\360\237\230\200\")\n    expect(is_valid(\"h\303\251llo \346\227\245\346\234\254\"))\n    expect(!is_valid(b\"\\xff\\xfe\"))\n    expect(!is_valid(b\"\\xe6\\x97\"))\n    let bad = decode_at(b\"\\xff\", 0)\n    expect_eq(bad.cp, REPLACEMENT)\n    expect_eq(bad.len, 1)\n    expect_eq(char_at(\"h\303\251llo\", 1).?, 0xE9)\n    expect(char_at(\"h\303\251\", 2) == null)\n    expect_eq(slice(\"h\303\251llo w\303\266rld\", 6, 11), \"w\303\266rld\")\n    expect_eq(truncate(\"h\303\251llo w\303\266rld\", 5), \"h\303\251llo\")\n    expect_eq(reverse(\"h\303\251llo\"), \"oll\303\251h\")\n    expect_eq(byte_offset(\"h\303\251llo\", 2), 3)\n}\n\ntest \"width\" {\n    expect_eq(width(\"hello\"), 5)\n    expect_eq(width(\"\346\227\245\346\234\254\350\252\236\"), 6)\n    expect_eq(width(\"e\\u{301}\"), 1)\n    expect_eq(width(\"a\\u{200B}b\"), 2)\n    expect_eq(char_width(0x1F600), 2)\n    expect_eq(pad_right(\"\346\227\245\346\234\254\", 6), \"\346\227\245\346\234\254  \")\n}\n\ntest \"case\" {\n    expect_eq(to_upper(\"h\303\251llo w\303\266rld\"), \"H\303\211LLO W\303\226RLD\")\n    expect_eq(to_lower(\"\303\200\303\211\303\216\303\225\303\234\"), \"\303\240\303\251\303\256\303\265\303\274\")\n    expect_eq(to_upper(\"stra\303\237e\"), \"STRA\303\237E\")\n    expect_eq(to_upper(\"\316\261\316\262\316\263\"), \"\316\221\316\222\316\223\")\n    expect_eq(to_lower(\"\316\221\316\222\316\223\316\243\"), \"\316\261\316\262\316\263\317\203\")\n    expect_eq(to_upper(\"\320\277\321\200\320\270\320\262\320\265\321\202\"), \"\320\237\320\240\320\230\320\222\320\225\320\242\")\n    expect_eq(to_lower(\"\320\237\320\240\320\230\320\222\320\225\320\242 \320\201\320\226\"), \"\320\277\321\200\320\270\320\262\320\265\321\202 \321\221\320\266\")\n    expect_eq(to_upper(\"\305\202\303\263d\305\272\"), \"\305\201\303\223D\305\271\")\n    expect_eq(to_lower(\"\305\201\303\223D\305\271\"), \"\305\202\303\263d\305\272\")\n    expect(eq_ignore_case(\"H\303\251llo\", \"h\303\211LLO\"))\n    expect(!eq_ignore_case(\"H\303\251llo\", \"hello\"))\n    expect_eq(upper_char('a' as u32), 'A' as u32)\n    expect_eq(lower_char(0x3A3), 0x3C3)\n}\n";
static const char nx_str_880[8114] = "// std.thread: threads, channels and mutexes, written in Nexium over the\n// `thread.*` and `sync.*` primitives.\n//\n// `import std.thread` then:\n//\n//     fn work(job: *mut Job) -> i64 { ... }\n//     var t = thread.spawn(Job, i64, work, Job{ .from = 0, .to = 1000 })\n//     let total = t.join()                        // the function's result\n//\n//     fn produce(p: *mut Producer) { ... }        // no result: a Worker\n//     var ch = thread.channel(String)             // shared by pointer\n//     var producer = thread.run(Producer, produce, Producer{ .out = &mut ch })\n//     let msg = ch.recv() orelse break            // null once closed and drained\n//     producer.join()\n//\n//     var counter = thread.mutex(i64, 0)\n//     let n = counter.lock()                      // *mut i64 while held\n//     n.* += 1\n//     counter.unlock()\n//\n// A thread function takes a pointer to its argument, which the `Thread`\n// owns until `join` returns the result. Channels and mutexes are values\n// that threads share by pointer; the owner must join every thread using\n// them before letting them go out of scope, and call `free` when done.\n// Panics inside a thread surface from `join`.\n\n/// The argument, function and result of one thread.\npub struct Task(T, R){\n    f: fn(*mut T) -> R\n    arg: T\n    result: List(R)\n}\n\n/// A running or finished thread.\npub struct Thread(T, R){\n    cell: List(Task(T, R))\n    handle: i64\n    joined: bool\n}\n\n/// Run `f(&mut arg)` on a new thread.\npub fn spawn(comptime T: type, comptime R: type, f: fn(*mut T) -> R, own arg: T) -> Thread(T, R) {\n    var cell = List(Task(T, R)).with_capacity(1)\n    cell.append(Task(T, R){ .f = f, .arg = arg, .result = List(R).new() })\n    let entry = |task: *mut Task(T, R)| {\n        let g = task.f\n        let r = g(&mut task.arg)\n        task.result.append(r)\n    }\n    let handle = thread.start(entry, &mut cell[0])\n    return Thread(T, R){ .cell = cell, .handle = handle, .joined = false }\n}\n\nimpl(T, R) Thread(T, R) {\n    /// Wait for the thread and take its result. Joining twice panics.\n    pub fn join(self: *mut Self) -> R {\n        if self.joined { panic(\"thread joined twice\") }\n        thread.join(self.handle)\n        self.joined = true\n        return self.cell[0].result.pop().?\n    }\n\n    /// The argument after the thread finished (for results written in place).\n    pub fn arg(self: *Self) -> *T {\n        if !self.joined { panic(\"the argument is shared with the running thread until join\") }\n        return &self.cell[0].arg\n    }\n}\n\n/// The argument and function of a thread without a result.\npub struct WorkerTask(T){\n    f: fn(*mut T) -> void\n    arg: T\n}\n\n/// A running or finished thread whose function returns nothing.\npub struct Worker(T){\n    cell: List(WorkerTask(T))\n    handle: i64\n    joined: bool\n}\n\n/// Run `f(&mut arg)` on a new thread, for functions without a result.\npub fn run(comptime T: type, f: fn(*mut T) -> void, own arg: T) -> Worker(T) {\n    var cell = List(WorkerTask(T)).with_capacity(1)\n    cell.append(WorkerTask(T){ .f = f, .arg = arg })\n    let entry = |task: *mut WorkerTask(T)| {\n        let g = task.f\n        g(&mut task.arg)\n    }\n    let handle = thread.start(entry, &mut cell[0])\n    return Worker(T){ .cell = cell, .handle = handle, .joined = false }\n}\n\nimpl(T) Worker(T) {\n    /// Wait for the thread. Joining twice panics.\n    pub fn join(self: *mut Self) {\n        if self.joined { panic(\"thread joined twice\") }\n        thread.join(self.handle)\n        self.joined = true\n    }\n\n    /// The argument after the thread finished (for results written in place).\n    pub fn arg(self: *Self) -> *T {\n        if !self.joined { panic(\"the argument is shared with the running thread until join\") }\n        return &self.cell[0].arg\n    }\n}\n\n/// The number of hardware threads.\npub fn count() -> usize {\n    return thread.count()\n}\n\n// ------------------------------------------------------------------ channels\n\n/// An unbounded queue between threads. `recv` blocks while it is empty\n/// and open, and returns null once it is closed and drained.\npub struct Channel(T){\n    items: List(T)\n    lock: i64\n    cond: i64\n    closed: bool\n}\n\npub fn channel(comptime T: type) -> Channel(T) {\n    return Channel(T){ .items = List(T).new(), .lock = sync.mutex_new(), .cond = sync.cond_new(), .closed = false }\n}\n\nimpl(T) Channel(T) {\n    pub fn send(self: *mut Self, own value: T) {\n        sync.lock(self.lock)\n        self.items.append(value)\n        sync.signal(self.cond)\n        sync.unlock(self.lock)\n    }\n\n    /// The next value, waiting for one; null when closed and empty.\n    pub fn recv(self: *mut Self) -> ?T {\n        sync.lock(self.lock)\n        while self.items.len == 0 and !self.closed { sync.wait(self.cond, self.lock) }\n        var out: ?T = null\n        if self.items.len > 0 { out = self.items.remove(0) }\n        sync.unlock(self.lock)\n        return out\n    }\n\n    /// The next value if one is queued, without waiting.\n    pub fn try_recv(self: *mut Self) -> ?T {\n        sync.lock(self.lock)\n        var out: ?T = null\n        if self.items.len > 0 { out = self.items.remove(0) }\n        sync.unlock(self.lock)\n        return out\n    }\n\n    /// No more values will be sent; receivers drain what is left, then see null.\n    pub fn close(self: *mut Self) {\n        sync.lock(self.lock)\n        self.closed = true\n        sync.broadcast(self.cond)\n        sync.unlock(self.lock)\n    }\n\n    pub fn len(self: *mut Self) -> usize {\n        sync.lock(self.lock)\n        let n = self.items.len\n        sync.unlock(self.lock)\n        return n\n    }\n\n    /// Release the lock and condition variable; after every user has stopped.\n    pub fn free(self: *mut Self) {\n        sync.cond_free(self.cond)\n        sync.mutex_free(self.lock)\n    }\n}\n\n// ------------------------------------------------------------------ mutexes\n\n/// A value guarded by a lock.\npub struct Mutex(T){\n    lock: i64\n    value: T\n}\n\npub fn mutex(comptime T: type, own value: T) -> Mutex(T) {\n    return Mutex(T){ .lock = sync.mutex_new(), .value = value }\n}\n\nimpl(T) Mutex(T) {\n    /// Take the lock; the pointer is valid until `unlock`.\n    pub fn lock(self: *mut Self) -> *mut T {\n        sync.lock(self.lock)\n        return &mut self.value\n    }\n\n    pub fn unlock(self: *mut Self) {\n        sync.unlock(self.lock)\n    }\n\n    /// Release the lock; after every user has stopped.\n    pub fn free(self: *mut Self) {\n        sync.mutex_free(self.lock)\n    }\n}\n\n// ------------------------------------------------------------------ tests\n\nstruct Range {\n    from: i64\n    to: i64\n}\n\nfn sum_range(r: *mut Range) -> i64 {\n    var s: i64 = 0\n    var i = r.from\n    while i < r.to {\n        s += i\n        i += 1\n    }\n    return s\n}\n\nstruct Producer {\n    out: *mut Channel(i64)\n    n: i64\n}\n\nfn produce(p: *mut Producer) {\n    var i: i64 = 0\n    while i < p.n {\n        p.out.send(i)\n        i += 1\n    }\n    p.out.close()\n}\n\nstruct Bumper {\n    counter: *mut Mutex(i64)\n    times: i64\n}\n\nfn bump(b: *mut Bumper) {\n    var i: i64 = 0\n    while i < b.times {\n        let n = b.counter.lock()\n        n.* += 1\n        b.counter.unlock()\n        i += 1\n    }\n}\n\ntest \"spawn and join\" {\n    var a = spawn(Range, i64, sum_range, Range{ .from = 0, .to = 1000 })\n    var b = spawn(Range, i64, sum_range, Range{ .from = 1000, .to = 2000 })\n    let total = a.join() + b.join()\n    expect_eq(total, 1999000)\n    expect(count() >= 1)\n}\n\ntest \"channel\" {\n    var ch = channel(i64)\n    var p = run(Producer, produce, Producer{ .out = &mut ch, .n = 100 })\n    var sum: i64 = 0\n    var got: i64 = 0\n    while true {\n        let v = ch.recv() orelse break\n        sum += v\n        got += 1\n    }\n    p.join()\n    expect_eq(got, 100)\n    expect_eq(sum, 4950)\n    expect(ch.try_recv() == null)\n    ch.free()\n}\n\ntest \"mutex\" {\n    var counter = mutex(i64, 0)\n    var ts = List(Worker(Bumper)).new()\n    for _ in 0..4 {\n        ts.append(run(Bumper, bump, Bumper{ .counter = &mut counter, .times = 2500 }))\n    }\n    for i in 0..ts.len { ts[i].join() }\n    let n = counter.lock()\n    expect_eq(n.*, 10000)\n    counter.unlock()\n    counter.free()\n}\n";
static const char nx_str_881[66908] = "// std.time: dates, durations, time zones and timers, written in Nexium.\n//\n// `import std.time` then:\n//\n//     let now = time.now_utc()                    // a DateTime\n//     println(\"{}\", .{now.iso()})                 // 2026-09-19T04:15:14.123Z\n//     println(\"{}\", .{now.format(\"%Y-%m-%d %H:%M\")})\n//     let local = time.now_local()                // with the machine's UTC offset\n//     let ny = try time.zone(\"America/New_York\")  // from the platform's database\n//     println(\"{}\", .{ny.format(time.now(), \"%H:%M %Z\")})    // 00:15 EDT\n//     let d = time.Duration.minutes(90)\n//     println(\"{} {}\", .{d.text(), d.iso()})      // 1h 30m PT1H30M\n//     var sw = time.Stopwatch.start()\n//     ... work ...\n//     println(\"took {}\", .{sw.elapsed().text()})\n//\n// Instants are milliseconds since 1970-01-01T00:00:00Z (`time.now()`), as\n// `i64`; negative values are before the epoch. Calendar arithmetic is the\n// proleptic Gregorian calendar. Time zones come from the platform's\n// database: the zoneinfo files on Linux, macOS and the BSDs (under\n// /usr/share/zoneinfo, or `$TZDIR`), ICU on Windows (10, version 1903 and\n// later). `now_local` and `local` take only the local offset, from the C\n// library; `local_zone` is the machine's zone with its history.\n\nimport std.fs\n\n// ------------------------------------------------------------------ calendar\n\n/// A broken-down instant. `offset_min` is the UTC offset the fields are\n/// expressed in (0 for UTC); `to_ms()` accounts for it.\npub struct DateTime {\n    year: i32\n    month: u8\n    day: u8\n    hour: u8\n    minute: u8\n    second: u8\n    millis: u16\n    offset_min: i32\n}\n\npub fn is_leap(year: i32) -> bool {\n    return (year % 4 == 0 and year % 100 != 0) or year % 400 == 0\n}\n\npub fn days_in_month(year: i32, month: u8) -> u8 {\n    if month == 2 { return if is_leap(year) { 29 } else { 28 } }\n    if month == 4 or month == 6 or month == 9 or month == 11 { return 30 }\n    return 31\n}\n\n/// 52 or 53: a year has 53 ISO weeks when it begins on a Thursday, or on\n/// a Wednesday in a leap year.\npub fn weeks_in_year(year: i32) -> u8 {\n    let wd = floor_mod(days_from_civil(year, 1, 1) + 3, 7)\n    if wd == 3 or (wd == 2 and is_leap(year)) { return 53 }\n    return 52\n}\n\nfn floor_div(a: i64, b: i64) -> i64 {\n    var q = a / b\n    if (a % b != 0) and ((a < 0) != (b < 0)) { q -= 1 }\n    return q\n}\n\nfn floor_mod(a: i64, b: i64) -> i64 {\n    return a - floor_div(a, b) * b\n}\n\nfn is_digit(c: u8) -> bool {\n    return c >= '0' and c <= '9'\n}\n\nfn is_alpha(c: u8) -> bool {\n    return (c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z')\n}\n\n/// Days since 1970-01-01 of a civil date (Howard Hinnant's algorithm).\nfn days_from_civil(y0: i32, m: u8, d: u8) -> i64 {\n    var y = y0 as i64\n    if m <= 2 { y -= 1 }\n    let era = floor_div(y, 400)\n    let yoe = y - era * 400\n    let mp = if m > 2 { (m as i64) - 3 } else { (m as i64) + 9 }\n    let doy = (153 * mp + 2) / 5 + (d as i64) - 1\n    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy\n    return era * 146097 + doe - 719468\n}\n\n/// The civil date of a day count since 1970-01-01.\nfn civil_from_days(z0: i64) -> (i32, u8, u8) {\n    let z = z0 + 719468\n    let era = floor_div(z, 146097)\n    let doe = z - era * 146097\n    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365\n    let y = yoe + era * 400\n    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100)\n    let mp = (5 * doy + 2) / 153\n    let d = doy - (153 * mp + 2) / 5 + 1\n    let m = if mp < 10 { mp + 3 } else { mp - 9 }\n    let year = if m <= 2 { y + 1 } else { y }\n    return (year as i32, m as u8, d as u8)\n}\n\n/// Break an instant down in UTC.\npub fn utc(ms: i64) -> DateTime {\n    return with_offset(ms, 0)\n}\n\n/// Break an instant down in the machine's local time zone.\npub fn local(ms: i64) -> DateTime {\n    return with_offset(ms, time.utc_offset(ms) as i32)\n}\n\n/// Break an instant down at a fixed offset in minutes east of UTC.\npub fn with_offset(ms: i64, offset_min: i32) -> DateTime {\n    let shifted = ms + (offset_min as i64) * 60000\n    let days = floor_div(shifted, 86400000)\n    let rem = floor_mod(shifted, 86400000)\n    let ymd = civil_from_days(days)\n    return DateTime{\n        .year = ymd.0,\n        .month = ymd.1,\n        .day = ymd.2,\n        .hour = (rem / 3600000) as u8,\n        .minute = ((rem / 60000) % 60) as u8,\n        .second = ((rem / 1000) % 60) as u8,\n        .millis = (rem % 1000) as u16,\n        .offset_min = offset_min,\n    }\n}\n\n/// The current instant, in UTC.\npub fn now_utc() -> DateTime {\n    return utc(time.now())\n}\n\n/// The current instant, in local time.\npub fn now_local() -> DateTime {\n    return local(time.now())\n}\n\n/// A date at midnight UTC; `null` when the fields do not name a real day.\npub fn date(year: i32, month: u8, day: u8) -> ?DateTime {\n    if month < 1 or month > 12 or day < 1 or day > days_in_month(year, month) { return null }\n    return DateTime{ .year = year, .month = month, .day = day, .hour = 0, .minute = 0, .second = 0, .millis = 0, .offset_min = 0 }\n}\n\n/// The date of an ISO week date (`day` 1 is Monday); `null` for a week\n/// the year does not have.\npub fn from_week(year: i32, week: i64, day: i64) -> ?DateTime {\n    if week < 1 or week > (weeks_in_year(year) as i64) or day < 1 or day > 7 { return null }\n    let jan4 = days_from_civil(year, 1, 4)\n    let monday = jan4 - floor_mod(jan4 + 3, 7)\n    let ymd = civil_from_days(monday + (week - 1) * 7 + day - 1)\n    return date(ymd.0, ymd.1, ymd.2)\n}\n\n/// The date of an ordinal date, the `n`th day of the year (1-based);\n/// `null` past the year's last day.\npub fn from_ordinal(year: i32, n: i64) -> ?DateTime {\n    let len: i64 = if is_leap(year) { 366 } else { 365 }\n    if n < 1 or n > len { return null }\n    let ymd = civil_from_days(days_from_civil(year, 1, 1) + n - 1)\n    return date(ymd.0, ymd.1, ymd.2)\n}\n\nfn pad(out: *mut String, v: i64, width: usize) {\n    var n = if v < 0 { -v } else { v }\n    var digits: usize = 1\n    var t = n\n    while t >= 10 {\n        t /= 10\n        digits += 1\n    }\n    if v < 0 { out.push_byte('-') }\n    while digits < width {\n        out.push_byte('0')\n        digits += 1\n    }\n    out.append(format(\"{}\", .{n}))\n}\n\n/// An offset as the zoneinfo files abbreviate a zone with no name for it:\n/// `+02`, `+0530`, `-03`; `UTC` for none.\nfn offset_abbrev(secs: i32) -> String {\n    var out = String.new()\n    if secs == 0 {\n        out.append(\"UTC\")\n        return out\n    }\n    let a = if secs < 0 { -(secs as i64) } else { secs as i64 }\n    out.push_byte(if secs < 0 { '-' } else { '+' })\n    pad(&mut out, a / 3600, 2)\n    if a % 3600 != 0 { pad(&mut out, a % 3600 / 60, 2) }\n    return out\n}\n\nconst MONTHS = [\"Jan\", \"Feb\", \"Mar\", \"Apr\", \"May\", \"Jun\", \"Jul\", \"Aug\", \"Sep\", \"Oct\", \"Nov\", \"Dec\"]\nconst DAYS = [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\", \"Sun\"]\nconst MONTH_NAMES = [\"January\", \"February\", \"March\", \"April\", \"May\", \"June\", \"July\", \"August\", \"September\", \"October\", \"November\", \"December\"]\nconst DAY_NAMES = [\"Monday\", \"Tuesday\", \"Wednesday\", \"Thursday\", \"Friday\", \"Saturday\", \"Sunday\"]\n\nimpl DateTime {\n    /// Milliseconds since the epoch (the offset is subtracted back out).\n    pub fn to_ms(self: *Self) -> i64 {\n        let days = days_from_civil(self.year, self.month, self.day)\n        let local_ms = days * 86400000 + (self.hour as i64) * 3600000 + (self.minute as i64) * 60000 + (self.second as i64) * 1000 + (self.millis as i64)\n        return local_ms - (self.offset_min as i64) * 60000\n    }\n\n    /// The same instant expressed in UTC.\n    pub fn to_utc(self: *Self) -> DateTime {\n        return utc(self.to_ms())\n    }\n\n    /// Day of the week, 0 = Monday ... 6 = Sunday.\n    pub fn weekday(self: *Self) -> u8 {\n        let days = days_from_civil(self.year, self.month, self.day)\n        return floor_mod(days + 3, 7) as u8\n    }\n\n    /// Day of the year, 1-based.\n    pub fn day_of_year(self: *Self) -> u16 {\n        var n: u16 = self.day as u16\n        var m: u8 = 1\n        while m < self.month {\n            n += days_in_month(self.year, m) as u16\n            m += 1\n        }\n        return n\n    }\n\n    /// The ISO 8601 week: the week-numbering year and the week, 1 to 53.\n    /// Weeks begin on Monday and week 1 holds the year's first Thursday,\n    /// so January 1 can be in the last week of the year before.\n    pub fn iso_week(self: *Self) -> (i32, u8) {\n        let days = days_from_civil(self.year, self.month, self.day)\n        let thursday = days - floor_mod(days + 3, 7) + 3\n        let y = civil_from_days(thursday).0\n        let week = (thursday - days_from_civil(y, 1, 1)) / 7 + 1\n        return (y, week as u8)\n    }\n\n    /// `YYYY-MM-DD`.\n    pub fn date_text(self: *Self) -> String {\n        var out = String.new()\n        pad(&mut out, self.year as i64, 4)\n        out.push_byte('-')\n        pad(&mut out, self.month as i64, 2)\n        out.push_byte('-')\n        pad(&mut out, self.day as i64, 2)\n        return out\n    }\n\n    /// The ISO 8601 week date, `2026-W38-6` (the day is 1 for Monday).\n    pub fn week_date(self: *Self) -> String {\n        let w = self.iso_week()\n        var out = String.new()\n        pad(&mut out, w.0 as i64, 4)\n        out.append(\"-W\")\n        pad(&mut out, w.1 as i64, 2)\n        out.push_byte('-')\n        pad(&mut out, (self.weekday() as i64) + 1, 1)\n        return out\n    }\n\n    /// The ISO 8601 ordinal date, `2026-262`.\n    pub fn ordinal_date(self: *Self) -> String {\n        var out = String.new()\n        pad(&mut out, self.year as i64, 4)\n        out.push_byte('-')\n        pad(&mut out, self.day_of_year() as i64, 3)\n        return out\n    }\n\n    /// `HH:MM:SS`.\n    pub fn time_text(self: *Self) -> String {\n        var out = String.new()\n        pad(&mut out, self.hour as i64, 2)\n        out.push_byte(':')\n        pad(&mut out, self.minute as i64, 2)\n        out.push_byte(':')\n        pad(&mut out, self.second as i64, 2)\n        return out\n    }\n\n    /// The offset as `Z`, or `+HH:MM` / `-HH:MM`.\n    pub fn offset_text(self: *Self) -> String {\n        var out = String.new()\n        if self.offset_min == 0 {\n            out.push_byte('Z')\n            return out\n        }\n        let o = self.offset_min as i64\n        out.push_byte(if o < 0 { '-' } else { '+' })\n        let a = if o < 0 { -o } else { o }\n        pad(&mut out, a / 60, 2)\n        out.push_byte(':')\n        pad(&mut out, a % 60, 2)\n        return out\n    }\n\n    /// ISO 8601 / RFC 3339: `2026-09-19T04:15:14.123Z`, `...+02:00`.\n    pub fn iso(self: *Self) -> String {\n        var out = self.date_text()\n        out.push_byte('T')\n        out.append(self.time_text())\n        if self.millis != 0 {\n            out.push_byte('.')\n            pad(&mut out, self.millis as i64, 3)\n        }\n        out.append(self.offset_text())\n        return out\n    }\n\n    /// ISO 8601's basic format, with no separators:\n    /// `20260919T041514.123Z`, `...+0200`.\n    pub fn iso_basic(self: *Self) -> String {\n        var out = String.new()\n        pad(&mut out, self.year as i64, 4)\n        pad(&mut out, self.month as i64, 2)\n        pad(&mut out, self.day as i64, 2)\n        out.push_byte('T')\n        pad(&mut out, self.hour as i64, 2)\n        pad(&mut out, self.minute as i64, 2)\n        pad(&mut out, self.second as i64, 2)\n        if self.millis != 0 {\n            out.push_byte('.')\n            pad(&mut out, self.millis as i64, 3)\n        }\n        if self.offset_min == 0 {\n            out.push_byte('Z')\n            return out\n        }\n        let o = self.offset_min as i64\n        out.push_byte(if o < 0 { '-' } else { '+' })\n        let a = if o < 0 { -o } else { o }\n        pad(&mut out, a / 60, 2)\n        pad(&mut out, a % 60, 2)\n        return out\n    }\n\n    /// strftime-style formatting: `%Y %m %d %H %M %S`, `%3` (millis), `%y`\n    /// (two-digit year), `%I %p` (12-hour clock, AM/PM), `%a %A %b %B` (day\n    /// and month names, short and full), `%j` (day of year), `%G %V %u`\n    /// (ISO week year, week and weekday, 1 for Monday), `%s` (seconds since\n    /// the epoch), `%z` (offset, `+02:00`), `%Z` (`UTC`, or the offset as\n    /// the zoneinfo files abbreviate it, `+02`; `Zone.format` gives the\n    /// zone's own, `CEST`) and `%%`. Unknown letters are copied through.\n    pub fn format(self: *Self, spec: []u8) -> String {\n        var out = String.new()\n        var i: usize = 0\n        while i < spec.len {\n            let c = spec[i]\n            if c != '%' or i + 1 >= spec.len {\n                out.push_byte(c)\n                i += 1\n                continue\n            }\n            let f = spec[i + 1]\n            i += 2\n            if f == 'Y' { pad(&mut out, self.year as i64, 4) }\n            else if f == 'm' { pad(&mut out, self.month as i64, 2) }\n            else if f == 'd' { pad(&mut out, self.day as i64, 2) }\n            else if f == 'H' { pad(&mut out, self.hour as i64, 2) }\n            else if f == 'M' { pad(&mut out, self.minute as i64, 2) }\n            else if f == 'S' { pad(&mut out, self.second as i64, 2) }\n            else if f == '3' { pad(&mut out, self.millis as i64, 3) }\n            else if f == 'y' { pad(&mut out, floor_mod(self.year as i64, 100), 2) }\n            else if f == 'I' {\n                let h = (self.hour % 12) as i64\n                pad(&mut out, if h == 0 { 12 } else { h }, 2)\n            }\n            else if f == 'p' { out.append(if self.hour < 12 { \"AM\" } else { \"PM\" }) }\n            else if f == 'j' { pad(&mut out, self.day_of_year() as i64, 3) }\n            else if f == 'G' { pad(&mut out, self.iso_week().0 as i64, 4) }\n            else if f == 'V' { pad(&mut out, self.iso_week().1 as i64, 2) }\n            else if f == 'u' { pad(&mut out, (self.weekday() as i64) + 1, 1) }\n            else if f == 's' { out.append(format(\"{}\", .{floor_div(self.to_ms(), 1000)})) }\n            else if f == 'z' { out.append(self.offset_text()) }\n            else if f == 'Z' { out.append(offset_abbrev(self.offset_min * 60)) }\n            else if f == 'a' { out.append(DAYS[self.weekday() as usize]) }\n            else if f == 'A' { out.append(DAY_NAMES[self.weekday() as usize]) }\n            else if f == 'b' { out.append(MONTHS[(self.month - 1) as usize]) }\n            else if f == 'B' { out.append(MONTH_NAMES[(self.month - 1) as usize]) }\n            else if f == '%' { out.push_byte('%') }\n            else {\n                out.push_byte('%')\n                out.push_byte(f)\n            }\n        }\n        return out\n    }\n\n    /// The instant `d` later, at the same offset.\n    pub fn plus(self: *Self, d: Duration) -> DateTime {\n        return with_offset(self.to_ms() + d.ms, self.offset_min)\n    }\n\n    /// The instant `d` earlier, at the same offset.\n    pub fn minus(self: *Self, d: Duration) -> DateTime {\n        return with_offset(self.to_ms() - d.ms, self.offset_min)\n    }\n\n    /// The time from this instant to `other`, negative when `other` is\n    /// earlier.\n    pub fn until(self: *Self, other: *DateTime) -> Duration {\n        return Duration{ .ms = other.to_ms() - self.to_ms() }\n    }\n\n    /// `n` calendar days later (earlier when negative), at the same clock\n    /// time and offset. In a zone whose offset changes in between,\n    /// `z.at(z.instant(&later))` keeps the clock time.\n    pub fn add_days(self: *Self, n: i64) -> DateTime {\n        let ymd = civil_from_days(days_from_civil(self.year, self.month, self.day) + n)\n        return self.on(ymd.0, ymd.1, ymd.2)\n    }\n\n    /// `n` months later; a day the month lacks becomes its last, so\n    /// January 31 plus a month is February 28 or 29.\n    pub fn add_months(self: *Self, n: i64) -> DateTime {\n        let m0 = (self.year as i64) * 12 + (self.month as i64) - 1 + n\n        let y = floor_div(m0, 12) as i32\n        let m = (floor_mod(m0, 12) + 1) as u8\n        let last = days_in_month(y, m)\n        return self.on(y, m, if self.day > last { last } else { self.day })\n    }\n\n    /// `n` years later; February 29 becomes February 28 in a common year.\n    pub fn add_years(self: *Self, n: i64) -> DateTime {\n        return self.add_months(n * 12)\n    }\n\n    fn on(self: *Self, year: i32, month: u8, day: u8) -> DateTime {\n        return DateTime{ .year = year, .month = month, .day = day, .hour = self.hour, .minute = self.minute, .second = self.second, .millis = self.millis, .offset_min = self.offset_min }\n    }\n}\n\nfn digits(s: []u8, start: usize, n: usize) -> ?i64 {\n    if start + n > s.len { return null }\n    var v: i64 = 0\n    for i in start..start + n {\n        let c = s[i]\n        if c < '0' or c > '9' { return null }\n        v = v * 10 + ((c - '0') as i64)\n    }\n    return v\n}\n\n/// Parse ISO 8601 / RFC 3339 text. The date is `2026-09-19` or\n/// `20260919`, a week date `2026-W38-6` or `2026W386`, or an ordinal date\n/// `2026-262` or `2026262`. A time may follow after `T` (or a space):\n/// `04:15:14.123` or `041514.123`, to the hour, the minute or the second,\n/// with `.` or `,` before a fraction of a second (read to the\n/// millisecond). An offset may end it: `Z`, `+02:00`, `+0200` or `+02`.\n/// Missing parts are zero; `null` when the text is not a date.\npub fn parse_iso(s: []u8) -> ?DateTime {\n    var p = IsoScan{ .s = s, .i = 0 }\n    var dt = p.read_date() orelse return null\n    if p.i < s.len and (s[p.i] == 'T' or s[p.i] == 't' or s[p.i] == ' ') {\n        p.i += 1\n        if !p.read_clock(&mut dt) { return null }\n    }\n    if !p.read_offset(&mut dt) { return null }\n    if p.i != s.len { return null }\n    return dt\n}\n\n/// A cursor over ISO 8601 text.\nstruct IsoScan {\n    s: []u8\n    i: usize\n}\n\nimpl IsoScan {\n    fn at(self: *Self, c: u8) -> bool {\n        return self.i < self.s.len and self.s[self.i] == c\n    }\n\n    /// `n` digits as a number, or null (the cursor stays).\n    fn num(self: *mut Self, n: usize) -> ?i64 {\n        let v = digits(self.s, self.i, n) orelse return null\n        self.i += n\n        return v\n    }\n\n    /// How many digits begin at the cursor.\n    fn run(self: *Self) -> usize {\n        var n: usize = 0\n        while self.i + n < self.s.len and is_digit(self.s[self.i + n]) { n += 1 }\n        return n\n    }\n\n    fn read_date(self: *mut Self) -> ?DateTime {\n        let n = self.run()\n        let year = (self.num(4) orelse return null) as i32\n        if n == 8 {\n            let m = self.num(2) orelse return null\n            let d = self.num(2) orelse return null\n            return date(year, m as u8, d as u8)\n        }\n        if n == 7 { return from_ordinal(year, self.num(3) orelse return null) }\n        if n != 4 { return null }\n        let extended = self.at('-')\n        if extended { self.i += 1 }\n        if self.at('W') {\n            self.i += 1\n            let w = self.num(2) orelse return null\n            var d: i64 = 1\n            if extended and self.at('-') {\n                self.i += 1\n                d = self.num(1) orelse return null\n            } else if !extended and self.run() > 0 {\n                d = self.num(1) orelse return null\n            }\n            return from_week(year, w, d)\n        }\n        if !extended { return null }\n        let r = self.run()\n        if r == 3 { return from_ordinal(year, self.num(3) orelse return null) }\n        if r != 2 { return null }\n        let m = self.num(2) orelse return null\n        if !self.at('-') { return null }\n        self.i += 1\n        let d = self.num(2) orelse return null\n        if self.run() != 0 { return null }\n        return date(year, m as u8, d as u8)\n    }\n\n    /// `hh[:mm[:ss[.fff]]]` or `hh[mm[ss[.fff]]]` into `dt`.\n    fn read_clock(self: *mut Self, dt: *mut DateTime) -> bool {\n        let hour = self.num(2) orelse return false\n        var minute: i64 = 0\n        var second: i64 = 0\n        let extended = self.at(':')\n        if extended or self.run() >= 2 {\n            if extended { self.i += 1 }\n            minute = self.num(2) orelse return false\n            let more = if extended { self.at(':') } else { self.run() >= 2 }\n            if more {\n                if extended { self.i += 1 }\n                second = self.num(2) orelse return false\n                if self.at('.') or self.at(',') {\n                    self.i += 1\n                    let n = self.run()\n                    if n == 0 { return false }\n                    var ms: i64 = 0\n                    var k: usize = 0\n                    while k < 3 {\n                        ms *= 10\n                        if k < n { ms += (self.s[self.i + k] - '0') as i64 }\n                        k += 1\n                    }\n                    self.i += n\n                    dt.millis = ms as u16\n                }\n            }\n        }\n        if hour > 23 or minute > 59 or second > 60 { return false }\n        dt.hour = hour as u8\n        dt.minute = minute as u8\n        dt.second = second as u8\n        return true\n    }\n\n    /// `Z`, `+hh:mm`, `+hhmm` or `+hh` into `dt`; no offset is fine too.\n    fn read_offset(self: *mut Self, dt: *mut DateTime) -> bool {\n        if self.at('Z') or self.at('z') {\n            self.i += 1\n            return true\n        }\n        if !(self.at('+') or self.at('-')) { return true }\n        let minus = self.at('-')\n        self.i += 1\n        let h = self.num(2) orelse return false\n        var m: i64 = 0\n        if self.at(':') {\n            self.i += 1\n            m = self.num(2) orelse return false\n        } else if self.run() == 2 {\n            m = self.num(2) orelse return false\n        }\n        if h > 23 or m > 59 { return false }\n        let off = (h * 60 + m) as i32\n        dt.offset_min = if minus { -off } else { off }\n        return true\n    }\n}\n\n// ------------------------------------------------------------------ durations\n\n/// A span of time in milliseconds; negative means \"before\". Durations\n/// compare with `==` and `<`.\npub struct Duration derive(Eq, Ord) {\n    ms: i64\n}\n\nimpl Duration {\n    pub fn millis(n: i64) -> Duration { return Duration{ .ms = n } }\n    pub fn seconds(n: i64) -> Duration { return Duration{ .ms = n * 1000 } }\n    pub fn minutes(n: i64) -> Duration { return Duration{ .ms = n * 60000 } }\n    pub fn hours(n: i64) -> Duration { return Duration{ .ms = n * 3600000 } }\n    pub fn days(n: i64) -> Duration { return Duration{ .ms = n * 86400000 } }\n\n    /// The span from `a` to `b` (instants in ms).\n    pub fn between(a: i64, b: i64) -> Duration { return Duration{ .ms = b - a } }\n\n    /// The span from an instant to now.\n    pub fn since(ms: i64) -> Duration { return Duration{ .ms = time.now() - ms } }\n\n    pub fn total_seconds(self: *Self) -> f64 { return (self.ms as f64) / 1000.0 }\n    pub fn total_minutes(self: *Self) -> f64 { return (self.ms as f64) / 60000.0 }\n    pub fn total_hours(self: *Self) -> f64 { return (self.ms as f64) / 3600000.0 }\n\n    /// Whole units, rounded toward zero.\n    pub fn whole_seconds(self: *Self) -> i64 { return self.ms / 1000 }\n    pub fn whole_minutes(self: *Self) -> i64 { return self.ms / 60000 }\n    pub fn whole_hours(self: *Self) -> i64 { return self.ms / 3600000 }\n    pub fn whole_days(self: *Self) -> i64 { return self.ms / 86400000 }\n\n    pub fn plus(self: *Self, other: Duration) -> Duration { return Duration{ .ms = self.ms + other.ms } }\n    pub fn minus(self: *Self, other: Duration) -> Duration { return Duration{ .ms = self.ms - other.ms } }\n\n    /// `n` times as long.\n    pub fn times(self: *Self, n: i64) -> Duration { return Duration{ .ms = self.ms * n } }\n\n    /// An `n`th of it, rounded toward zero.\n    pub fn div(self: *Self, n: i64) -> Duration { return Duration{ .ms = self.ms / n } }\n\n    /// How many times `other` goes into it: `hours(3).ratio(minutes(90))`\n    /// is 2.0.\n    pub fn ratio(self: *Self, other: Duration) -> f64 { return (self.ms as f64) / (other.ms as f64) }\n\n    pub fn neg(self: *Self) -> Duration { return Duration{ .ms = -self.ms } }\n    pub fn abs(self: *Self) -> Duration { return Duration{ .ms = if self.ms < 0 { -self.ms } else { self.ms } } }\n    pub fn is_zero(self: *Self) -> bool { return self.ms == 0 }\n    pub fn is_negative(self: *Self) -> bool { return self.ms < 0 }\n\n    /// Cut to a whole number of `unit`s, toward zero:\n    /// `millis(1999).truncate(seconds(1))` is one second.\n    pub fn truncate(self: *Self, unit: Duration) -> Duration {\n        let u = if unit.ms < 0 { -unit.ms } else { unit.ms }\n        return Duration{ .ms = self.ms - self.ms % u }\n    }\n\n    /// The nearest whole number of `unit`s; a half goes away from zero.\n    pub fn round(self: *Self, unit: Duration) -> Duration {\n        let u = if unit.ms < 0 { -unit.ms } else { unit.ms }\n        let r = self.ms % u\n        var q = self.ms - r\n        if r * 2 >= u { q += u } else if r * 2 <= -u { q -= u }\n        return Duration{ .ms = q }\n    }\n\n    /// Human text: `250ms`, `3.5s`, `2m 05s`, `1h 02m`, `3d 04h`.\n    pub fn text(self: *Self) -> String {\n        var out = String.new()\n        var ms = self.ms\n        if ms < 0 {\n            out.push_byte('-')\n            ms = -ms\n        }\n        if ms < 1000 {\n            out.append(format(\"{}ms\", .{ms}))\n            return out\n        }\n        if ms < 60000 {\n            let tenths = (ms + 50) / 100\n            out.append(format(\"{}.{}s\", .{tenths / 10, tenths % 10}))\n            return out\n        }\n        let secs = ms / 1000\n        if secs < 3600 {\n            out.append(format(\"{}m \", .{secs / 60}))\n            pad(&mut out, secs % 60, 2)\n            out.push_byte('s')\n            return out\n        }\n        let mins = secs / 60\n        if mins < 1440 {\n            out.append(format(\"{}h \", .{mins / 60}))\n            pad(&mut out, mins % 60, 2)\n            out.push_byte('m')\n            return out\n        }\n        let hours = mins / 60\n        out.append(format(\"{}d \", .{hours / 24}))\n        pad(&mut out, hours % 24, 2)\n        out.push_byte('h')\n        return out\n    }\n\n    /// ISO 8601: `PT1H30M`, `PT0.25S`, `PT76H`, `-PT1.5S`, `PT0S`. Hours\n    /// are the largest unit, since a day in a zone is not always 24 of\n    /// them.\n    pub fn iso(self: *Self) -> String {\n        var out = String.new()\n        // the magnitude as u64, so the smallest i64 has one too\n        var a: u64 = 0\n        if self.ms < 0 {\n            out.push_byte('-')\n            a = ((-(self.ms + 1)) as u64) + 1\n        } else {\n            a = self.ms as u64\n        }\n        out.append(\"PT\")\n        let h = a / 3600000\n        let m = a / 60000 % 60\n        let s = a / 1000 % 60\n        let f = a % 1000\n        if h > 0 { out.append(format(\"{}H\", .{h})) }\n        if m > 0 { out.append(format(\"{}M\", .{m})) }\n        if s > 0 or f > 0 or (h == 0 and m == 0) {\n            out.append(format(\"{}\", .{s}))\n            if f > 0 {\n                // up to three digits, without the zeros at the end\n                var frac = f\n                var width: usize = 3\n                while frac % 10 == 0 {\n                    frac /= 10\n                    width -= 1\n                }\n                out.push_byte('.')\n                pad(&mut out, frac as i64, width)\n            }\n            out.push_byte('S')\n        }\n        return out\n    }\n\n    /// Parse ISO 8601 duration text: `PT1H30M`, `PT0.25S`, `P2DT3H`, `P1W`,\n    /// `-PT5M`. A day is 24 hours here and a week 7 days; years and months\n    /// (`P1Y`, `P2M`), whose length depends on the calendar, are `null`, as\n    /// is anything that is not a duration. The last number may have a\n    /// fraction (`PT1.5H`), read to the millisecond.\n    pub fn parse_iso(s: []u8) -> ?Duration {\n        var i: usize = 0\n        var neg = false\n        if i < s.len and (s[i] == '-' or s[i] == '+') {\n            neg = s[i] == '-'\n            i += 1\n        }\n        if i >= s.len or s[i] != 'P' { return null }\n        i += 1\n        var total: i64 = 0\n        var in_time = false\n        var any = false\n        var ended = false\n        // each unit must be smaller than the one before\n        var last: i64 = 9223372036854775807\n        while i < s.len {\n            if s[i] == 'T' {\n                if in_time or i + 1 >= s.len { return null }\n                in_time = true\n                i += 1\n                continue\n            }\n            if ended { return null }\n            let start = i\n            while i < s.len and is_digit(s[i]) { i += 1 }\n            if i == start { return null }\n            let whole = s[start..i].parse_int(i64) catch { return null }\n            var num: i64 = 0\n            var den: i64 = 1\n            if i < s.len and (s[i] == '.' or s[i] == ',') {\n                i += 1\n                let fstart = i\n                while i < s.len and is_digit(s[i]) {\n                    if den < 1000000000 {\n                        num = num * 10 + ((s[i] - '0') as i64)\n                        den *= 10\n                    }\n                    i += 1\n                }\n                if i == fstart { return null }\n                ended = true\n            }\n            if i >= s.len { return null }\n            let unit = duration_unit(s[i], in_time)\n            if unit == 0 or unit >= last { return null }\n            last = unit\n            i += 1\n            if whole > 9223372036854775807 / unit { return null }\n            total += whole * unit + num * unit / den\n            any = true\n        }\n        if !any { return null }\n        return Duration{ .ms = if neg { -total } else { total } }\n    }\n}\n\n/// A duration letter's length in ms; 0 for one that is not allowed where\n/// it is (`M` is minutes after `T`, and months, which are not, before).\nfn duration_unit(c: u8, in_time: bool) -> i64 {\n    if in_time {\n        if c == 'H' { return 3600000 }\n        if c == 'M' { return 60000 }\n        if c == 'S' { return 1000 }\n        return 0\n    }\n    if c == 'W' { return 604800000 }\n    if c == 'D' { return 86400000 }\n    return 0\n}\n\n/// `instant + duration`.\npub fn add(ms: i64, d: Duration) -> i64 {\n    return ms + d.ms\n}\n\n// ------------------------------------------------------------------ zones\n\nconst MIN_MS: i64 = -9223372036854775808\n\n/// One stretch of a zone's history with one offset.\npub struct Period derive(Clone) {\n    /// when it began, in ms since the epoch; the first period's is the\n    /// smallest i64\n    start: i64\n    /// seconds east of UTC\n    offset: i32\n    dst: bool\n    abbrev: String\n}\n\n/// A day of the year in a POSIX TZ rule: `Jn` (kind 0: 1 to 365, February\n/// 29 never counted), `n` (kind 1: 0 to 365), or `Mm.w.d` (kind 2:\n/// weekday `d`, 0 for Sunday, of week `w` of month `m`; week 5 is the\n/// last).\npub struct RuleDay derive(Clone) {\n    kind: u8\n    day: i32\n    month: u8\n    week: u8\n}\n\n/// A POSIX TZ rule, as the zoneinfo files end with and `$TZ` may hold:\n/// a standard offset, and maybe a daylight one with the days and times\n/// it begins and ends each year. Offsets are seconds east of UTC; times\n/// are seconds after local midnight, in standard time for the start and\n/// daylight time for the end.\npub struct Rule derive(Clone) {\n    std_abbrev: String\n    std_offset: i32\n    has_dst: bool\n    dst_abbrev: String\n    dst_offset: i32\n    start: RuleDay\n    start_time: i32\n    end: RuleDay\n    end_time: i32\n}\n\n/// A time zone: the periods of its history, and the rule it follows after\n/// the last of them.\npub struct Zone derive(Clone) {\n    name: String\n    periods: List(Period)\n    has_rule: bool\n    rule: Rule\n}\n\n/// Where an instant falls in a zone: one of its periods, or past them,\n/// in its rule's standard or daylight half.\nstruct Place {\n    period: usize\n    from_rule: bool\n    rule_dst: bool\n}\n\nfn no_rule() -> Rule {\n    return Rule{\n        .std_abbrev = String.new(), .std_offset = 0, .has_dst = false,\n        .dst_abbrev = String.new(), .dst_offset = 0,\n        .start = RuleDay{ .kind = 0, .day = 1, .month = 1, .week = 1 }, .start_time = 0,\n        .end = RuleDay{ .kind = 0, .day = 1, .month = 1, .week = 1 }, .end_time = 0,\n    }\n}\n\n/// UTC as a zone.\npub fn utc_zone() -> Zone {\n    return fixed_zone(\"UTC\", 0)\n}\n\n/// A zone always `secs` seconds east of UTC.\nfn fixed_zone(name: []u8, secs: i32) -> Zone {\n    var periods = List(Period).new()\n    periods.append(Period{ .start = MIN_MS, .offset = secs, .dst = false, .abbrev = offset_abbrev(secs) })\n    return Zone{ .name = String.from(name), .periods = periods, .has_rule = false, .rule = no_rule() }\n}\n\n/// A zone that follows a POSIX rule at every instant.\nfn rule_zone(name: []u8, own r: Rule) -> Zone {\n    var periods = List(Period).new()\n    periods.append(Period{ .start = MIN_MS, .offset = r.std_offset, .dst = false, .abbrev = r.std_abbrev.clone() })\n    return Zone{ .name = String.from(name), .periods = periods, .has_rule = true, .rule = r }\n}\n\n/// A time zone by name: an IANA name from the platform's database\n/// (`Europe/Berlin`, `America/New_York`, `Asia/Kolkata`), `UTC`, a fixed\n/// offset (`+05:30`, `-0800`), or a POSIX rule (`EST5EDT,M3.2.0,M11.1.0`).\n/// `error.NotFound` when the database has no such zone, or there is no\n/// database (the playground); `error.InvalidInput` for text that cannot\n/// name a zone, or a database file that is not one.\npub fn zone(name: []u8) -> !Zone {\n    if name == \"UTC\" or name == \"Z\" { return utc_zone() }\n    if name.len > 0 and (name[0] == '+' or name[0] == '-') {\n        var p = IsoScan{ .s = name, .i = 0 }\n        var dt = utc(0)\n        if !p.read_offset(&mut dt) or p.i != name.len { return error.InvalidInput }\n        return fixed_zone(name, dt.offset_min * 60)\n    }\n    let known = zone_name_ok(name)\n    if known {\n        for dir in zoneinfo_dirs() {\n            let data = fs.read(format(\"{}/{}\", .{dir, name})[..]) catch { continue }\n            return from_tzif(name, data[..])\n        }\n        if let text = zone_text(name) { return from_rules_text(text[..]) }\n    }\n    if let r = parse_rule(name) { return rule_zone(name, r) }\n    if known { return error.NotFound }\n    return error.InvalidInput\n}\n\n/// The platform's text for a zone (`time.zone_rules`: ICU on Windows);\n/// null where it has none.\nfn zone_text(name: []u8) -> ?String {\n    let text = time.zone_rules(name) catch { return null }\n    return text\n}\n\n/// A zone's name is ASCII letters, digits and `_-+`, in parts split by\n/// `/`, none of them empty: no path leaves the zoneinfo directory.\nfn zone_name_ok(name: []u8) -> bool {\n    if name.len == 0 or name.len > 128 { return false }\n    var part: usize = 0\n    for c in name {\n        if c == '/' {\n            if part == 0 { return false }\n            part = 0\n            continue\n        }\n        if !(is_alpha(c) or is_digit(c) or c == '_' or c == '-' or c == '+') { return false }\n        part += 1\n    }\n    return part > 0\n}\n\n/// Where the zoneinfo files may be: `$TZDIR`, then where Linux, macOS and\n/// the BSDs keep them (NixOS in /etc/zoneinfo).\nfn zoneinfo_dirs() -> List(String) {\n    var dirs = List(String).new()\n    if let d = os.env(\"TZDIR\") {\n        if d.len > 0 { dirs.append(String.from(d)) }\n    }\n    if @target().0 != \"windows\" {\n        for d in [\"/usr/share/zoneinfo\", \"/usr/lib/zoneinfo\", \"/usr/share/lib/zoneinfo\", \"/etc/zoneinfo\"] { dirs.append(String.from(d)) }\n    }\n    return dirs\n}\n\n/// The machine's time zone: `$TZ` when it is set (a zone's name, the path\n/// of a TZif file, or a POSIX rule such as `EST5EDT,M3.2.0,M11.1.0`; set\n/// but empty is UTC), else the system's: /etc/localtime on Linux, macOS\n/// and the BSDs (named by /etc/timezone where there is one, else `Local`),\n/// the zone Windows is set to through ICU. When none is found, a zone\n/// with the C library's offset now, named `Local`.\npub fn local_zone() -> Zone {\n    if let tz = os.env(\"TZ\") { return zone_from_tz(tz) }\n    if @target().0 == \"windows\" {\n        let text = zone_text(\"\") orelse return fallback_local()\n        let z = from_rules_text(text[..]) catch { return fallback_local() }\n        return z\n    }\n    let data = fs.read(\"/etc/localtime\") catch { return fallback_local() }\n    let named = fs.read(\"/etc/timezone\") catch { String.new() }\n    let guess = named[..].trim()\n    let name = if zone_name_ok(guess) { guess } else { \"Local\" }\n    let z = from_tzif(name, data[..]) catch { return fallback_local() }\n    return z\n}\n\n/// The zone `$TZ` names: `:name` or `name`, a TZif file's path, or a rule.\nfn zone_from_tz(tz0: []u8) -> Zone {\n    var tz = tz0\n    if tz.len > 0 and tz[0] == ':' { tz = tz[1..] }\n    if tz.len == 0 { return utc_zone() }\n    if tz[0] == '/' {\n        let data = fs.read(tz) catch { return utc_zone() }\n        // a path into a zoneinfo directory names its zone\n        var name = tz\n        if let k = tz.find(\"zoneinfo/\") { name = tz[k + 9..] }\n        let z = from_tzif(name, data[..]) catch { return utc_zone() }\n        return z\n    }\n    let z = zone(tz) catch { return utc_zone() }\n    return z\n}\n\n/// A zone with the C library's offset now, when nothing says more.\nfn fallback_local() -> Zone {\n    return fixed_zone(\"Local\", (time.utc_offset(time.now()) * 60) as i32)\n}\n\nfn be32u(b: []u8, at: usize) -> u64 {\n    return ((b[at] as u64) << 24) | ((b[at + 1] as u64) << 16) | ((b[at + 2] as u64) << 8) | (b[at + 3] as u64)\n}\n\nfn be32(b: []u8, at: usize) -> i64 {\n    return @bitCast(i32, be32u(b, at) as u32) as i64\n}\n\nfn be64(b: []u8, at: usize) -> i64 {\n    var v: u64 = 0\n    var k: usize = 0\n    while k < 8 {\n        v = (v << 8) | (b[at + k] as u64)\n        k += 1\n    }\n    return @bitCast(i64, v)\n}\n\n/// The length of the data after a TZif header at `at`, with times of\n/// `tsize` bytes; null when the header does not fit.\nfn tzif_block(b: []u8, at: usize, tsize: usize) -> ?usize {\n    if at + 44 > b.len { return null }\n    let isutcnt = be32u(b, at + 20) as usize\n    let isstdcnt = be32u(b, at + 24) as usize\n    let leapcnt = be32u(b, at + 28) as usize\n    let timecnt = be32u(b, at + 32) as usize\n    let typecnt = be32u(b, at + 36) as usize\n    let charcnt = be32u(b, at + 40) as usize\n    return timecnt * tsize + timecnt + typecnt * 6 + charcnt + leapcnt * (tsize + 4) + isstdcnt + isutcnt\n}\n\n/// Seconds to milliseconds, held at the ends of the i64 range: a TZif\n/// file may list a first change at -2^59 s, \"the big bang\".\nfn secs_to_ms(s: i64) -> i64 {\n    if s <= -9223372036854775 { return MIN_MS }\n    if s >= 9223372036854775 { return 9223372036854775807 }\n    return s * 1000\n}\n\n/// Local time type `t` of a TZif block, from `start` on.\nfn tzif_period(b: []u8, types_at: usize, chars_at: usize, charcnt: usize, t: usize, start: i64) -> !Period {\n    let p = types_at + t * 6\n    let ai = b[p + 5] as usize\n    if ai >= charcnt { return error.InvalidInput }\n    var e = ai\n    while e < charcnt and b[chars_at + e] != 0 { e += 1 }\n    return Period{ .start = start, .offset = be32(b, p) as i32, .dst = b[p + 4] != 0, .abbrev = String.from(b[chars_at + ai..chars_at + e]) }\n}\n\n/// A zone from the bytes of a TZif file (RFC 8536), the form the zoneinfo\n/// database is kept in; `error.InvalidInput` when they are not one.\npub fn from_tzif(name: []u8, b: []u8) -> !Zone {\n    if b.len < 44 or b[0..4] != \"TZif\" { return error.InvalidInput }\n    var at: usize = 0\n    var wide = false\n    // version 2 and later repeat the data with 64-bit times after the\n    // 32-bit block, and end with a POSIX rule\n    if b[4] >= '2' {\n        at = 44 + (tzif_block(b, 0, 4) orelse return error.InvalidInput)\n        if at + 44 > b.len or b[at..at + 4] != \"TZif\" { return error.InvalidInput }\n        wide = true\n    }\n    let tsize: usize = if wide { 8 } else { 4 }\n    let data_len = tzif_block(b, at, tsize) orelse return error.InvalidInput\n    let timecnt = be32u(b, at + 32) as usize\n    let typecnt = be32u(b, at + 36) as usize\n    let charcnt = be32u(b, at + 40) as usize\n    if typecnt == 0 or at + 44 + data_len > b.len { return error.InvalidInput }\n    let times_at = at + 44\n    let index_at = times_at + timecnt * tsize\n    let types_at = index_at + timecnt\n    let chars_at = types_at + typecnt * 6\n    var periods = List(Period).new()\n    // before the first change, the first type\n    periods.append(try tzif_period(b, types_at, chars_at, charcnt, 0, MIN_MS))\n    var i: usize = 0\n    while i < timecnt {\n        let secs = if wide { be64(b, times_at + i * 8) } else { be32(b, times_at + i * 4) }\n        let t = b[index_at + i] as usize\n        if t >= typecnt { return error.InvalidInput }\n        periods.append(try tzif_period(b, types_at, chars_at, charcnt, t, secs_to_ms(secs)))\n        i += 1\n    }\n    var z = Zone{ .name = String.from(name), .periods = periods, .has_rule = false, .rule = no_rule() }\n    // the footer, `\\n<rule>\\n`, for instants past the last change\n    let foot = at + 44 + data_len\n    if wide and foot < b.len and b[foot] == '\\n' {\n        var end = foot + 1\n        while end < b.len and b[end] != '\\n' { end += 1 }\n        if end > foot + 1 {\n            if let r = parse_rule(b[foot + 1..end]) {\n                z.rule = r\n                z.has_rule = true\n            }\n        }\n    }\n    return z\n}\n\n/// A zone from `time.zone_rules`' text: its name, then a period a line,\n/// `start offset dst abbrev`, the first period's start `-`.\nfn from_rules_text(text: []u8) -> !Zone {\n    let lines = text.split(\"\\n\")\n    if lines.len < 2 { return error.InvalidInput }\n    var periods = List(Period).new()\n    for line, n in lines {\n        if n == 0 or line.len == 0 { continue }\n        let f = line.split(\" \")\n        if f.len != 4 { return error.InvalidInput }\n        var start = MIN_MS\n        if f[0] != \"-\" { start = f[0].parse_int(i64) catch { return error.InvalidInput } }\n        let offset = f[1].parse_int(i32) catch { return error.InvalidInput }\n        periods.append(Period{ .start = start, .offset = offset, .dst = f[2] == \"1\", .abbrev = String.from(f[3]) })\n    }\n    if periods.len == 0 { return error.InvalidInput }\n    return Zone{ .name = String.from(lines[0]), .periods = periods, .has_rule = false, .rule = no_rule() }\n}\n\nimpl Zone {\n    fn place(self: *Self, ms: i64) -> Place {\n        let n = self.periods.len\n        if self.has_rule and ms >= self.periods[n - 1].start {\n            return Place{ .period = n - 1, .from_rule = true, .rule_dst = self.rule.in_dst(ms) }\n        }\n        var lo: usize = 0\n        var hi = n\n        while hi - lo > 1 {\n            let mid = (lo + hi) / 2\n            if self.periods[mid].start <= ms { lo = mid } else { hi = mid }\n        }\n        return Place{ .period = lo, .from_rule = false, .rule_dst = false }\n    }\n\n    /// Seconds east of UTC at an instant. A few offsets, the local mean\n    /// time places kept before they took a standard one (mostly before\n    /// 1900), are not whole minutes.\n    pub fn offset_seconds_at(self: *Self, ms: i64) -> i32 {\n        let p = self.place(ms)\n        if !p.from_rule { return self.periods[p.period].offset }\n        return if p.rule_dst { self.rule.dst_offset } else { self.rule.std_offset }\n    }\n\n    /// Minutes east of UTC at an instant, to the nearest minute: the\n    /// offset of the `DateTime` that `at` gives.\n    pub fn offset_at(self: *Self, ms: i64) -> i32 {\n        let s = self.offset_seconds_at(ms)\n        return (if s < 0 { s - 30 } else { s + 30 }) / 60\n    }\n\n    /// Whether daylight saving time is in force at an instant.\n    pub fn is_dst_at(self: *Self, ms: i64) -> bool {\n        let p = self.place(ms)\n        if !p.from_rule { return self.periods[p.period].dst }\n        return p.rule_dst\n    }\n\n    /// The zone's abbreviation at an instant: `CEST`, `PST`, or an offset\n    /// such as `+0530` where the database has no name.\n    pub fn abbrev_at(self: *Self, ms: i64) -> String {\n        let p = self.place(ms)\n        if !p.from_rule { return self.periods[p.period].abbrev.clone() }\n        return if p.rule_dst { self.rule.dst_abbrev.clone() } else { self.rule.std_abbrev.clone() }\n    }\n\n    /// An instant broken down in this zone.\n    pub fn at(self: *Self, ms: i64) -> DateTime {\n        return with_offset(ms, self.offset_at(ms))\n    }\n\n    /// The current instant in this zone.\n    pub fn now(self: *Self) -> DateTime {\n        return self.at(time.now())\n    }\n\n    /// The instant a wall-clock time names in this zone; the offset in\n    /// `dt` is ignored. A time that happens twice, when clocks are turned\n    /// back, is the first; one that is skipped, when they are turned\n    /// forward, is read with the offset before the change, so 02:30 on the\n    /// night clocks jump from 02:00 to 03:00 is 03:30.\n    pub fn instant(self: *Self, dt: *DateTime) -> i64 {\n        let wall = days_from_civil(dt.year, dt.month, dt.day) * 86400000 + (dt.hour as i64) * 3600000 + (dt.minute as i64) * 60000 + (dt.second as i64) * 1000 + (dt.millis as i64)\n        let before = (self.offset_at(wall - 86400000) as i64) * 60000\n        let after = (self.offset_at(wall + 86400000) as i64) * 60000\n        let early = wall - before\n        let late = wall - after\n        let early_ok = (self.offset_at(early) as i64) * 60000 == before\n        let late_ok = (self.offset_at(late) as i64) * 60000 == after\n        if early_ok and late_ok { return if early < late { early } else { late } }\n        if late_ok { return late }\n        return early\n    }\n\n    /// strftime-style text of an instant in this zone: `DateTime.format`'s\n    /// letters, with `%Z` the zone's abbreviation (`CEST`).\n    pub fn format(self: *Self, ms: i64, spec: []u8) -> String {\n        let abbrev = self.abbrev_at(ms)\n        var s = String.new()\n        var i: usize = 0\n        while i < spec.len {\n            if spec[i] == '%' and i + 1 < spec.len {\n                if spec[i + 1] == 'Z' {\n                    for c in abbrev[..] {\n                        s.push_byte(c)\n                        if c == '%' { s.push_byte('%') }\n                    }\n                } else {\n                    s.push_byte('%')\n                    s.push_byte(spec[i + 1])\n                }\n                i += 2\n                continue\n            }\n            s.push_byte(spec[i])\n            i += 1\n        }\n        let dt = self.at(ms)\n        return dt.format(s[..])\n    }\n}\n\nimpl Rule {\n    /// Whether daylight time is in force at an instant.\n    fn in_dst(self: *Self, ms: i64) -> bool {\n        if !self.has_dst { return false }\n        let secs = floor_div(ms, 1000)\n        // the year, in local standard time\n        let y = civil_from_days(floor_div(secs + (self.std_offset as i64), 86400)).0\n        let begins = self.change(y, true)\n        let ends = self.change(y, false)\n        if begins < ends { return secs >= begins and secs < ends }\n        // the southern hemisphere: daylight time spans the new year\n        return secs < ends or secs >= begins\n    }\n\n    /// When daylight time begins (or ends) in year `y`, in seconds since\n    /// the epoch.\n    fn change(self: *Self, y: i32, begins: bool) -> i64 {\n        if begins { return self.start.days_in(y) * 86400 + (self.start_time as i64) - (self.std_offset as i64) }\n        return self.end.days_in(y) * 86400 + (self.end_time as i64) - (self.dst_offset as i64)\n    }\n}\n\nimpl RuleDay {\n    /// This day in year `y`, as days since 1970-01-01.\n    fn days_in(self: *Self, y: i32) -> i64 {\n        let jan1 = days_from_civil(y, 1, 1)\n        if self.kind == 0 {\n            var n = (self.day as i64) - 1\n            if is_leap(y) and self.day >= 60 { n += 1 }\n            return jan1 + n\n        }\n        if self.kind == 1 { return jan1 + (self.day as i64) }\n        let first = days_from_civil(y, self.month, 1)\n        // weekdays counted from Sunday, as the rule counts them; 1970-01-01\n        // was a Thursday\n        let wd = floor_mod(first + 4, 7)\n        var d = first + floor_mod((self.day as i64) - wd, 7) + ((self.week as i64) - 1) * 7\n        let last = first + (days_in_month(y, self.month) as i64) - 1\n        while d > last { d -= 7 }\n        return d\n    }\n}\n\n/// Parse a POSIX TZ rule: `EST5EDT,M3.2.0,M11.1.0`, `<+0530>-5:30`,\n/// `AEST-10AEDT,M10.1.0,M4.1.0/3`. Its offsets are written west of UTC,\n/// the other way round from everywhere else; a rule with a daylight name\n/// and no dates follows the United States' dates. `null` when the text is\n/// not a rule.\npub fn parse_rule(s: []u8) -> ?Rule {\n    var p = RuleScan{ .s = s, .i = 0 }\n    var r = no_rule()\n    r.std_abbrev = p.name() orelse return null\n    r.std_offset = -(p.clock() orelse return null)\n    if p.i == s.len { return r }\n    r.dst_abbrev = p.name() orelse return null\n    r.has_dst = true\n    r.dst_offset = r.std_offset + 3600\n    if p.i < s.len and s[p.i] != ',' { r.dst_offset = -(p.clock() orelse return null) }\n    r.start_time = 7200\n    r.end_time = 7200\n    if p.i == s.len {\n        r.start = RuleDay{ .kind = 2, .day = 0, .month = 3, .week = 2 }\n        r.end = RuleDay{ .kind = 2, .day = 0, .month = 11, .week = 1 }\n        return r\n    }\n    if !p.eat(',') { return null }\n    r.start = p.day() orelse return null\n    if p.eat('/') { r.start_time = p.clock() orelse return null }\n    if !p.eat(',') { return null }\n    r.end = p.day() orelse return null\n    if p.eat('/') { r.end_time = p.clock() orelse return null }\n    if p.i != s.len { return null }\n    return r\n}\n\n/// A cursor over a POSIX TZ rule.\nstruct RuleScan {\n    s: []u8\n    i: usize\n}\n\nimpl RuleScan {\n    fn eat(self: *mut Self, c: u8) -> bool {\n        if self.i < self.s.len and self.s[self.i] == c {\n            self.i += 1\n            return true\n        }\n        return false\n    }\n\n    /// An abbreviation: three or more letters, or `<...>`, which may hold\n    /// signs and digits too.\n    fn name(self: *mut Self) -> ?String {\n        if self.eat('<') {\n            let start = self.i\n            while self.i < self.s.len and self.s[self.i] != '>' { self.i += 1 }\n            if self.i >= self.s.len or self.i - start < 3 { return null }\n            let n = String.from(self.s[start..self.i])\n            self.i += 1\n            return n\n        }\n        let start = self.i\n        while self.i < self.s.len and is_alpha(self.s[self.i]) { self.i += 1 }\n        if self.i - start < 3 { return null }\n        return String.from(self.s[start..self.i])\n    }\n\n    /// `[+-]h[h][:mm[:ss]]` as seconds; hours up to 167, as RFC 8536\n    /// allows.\n    fn clock(self: *mut Self) -> ?i32 {\n        var sign: i32 = 1\n        if self.eat('-') { sign = -1 } else { _ = self.eat('+') }\n        let h = self.int(3) orelse return null\n        if h > 167 { return null }\n        var secs = h * 3600\n        if self.eat(':') {\n            let m = self.int(2) orelse return null\n            if m > 59 { return null }\n            secs += m * 60\n            if self.eat(':') {\n                let sec = self.int(2) orelse return null\n                if sec > 59 { return null }\n                secs += sec\n            }\n        }\n        return sign * secs\n    }\n\n    /// One to `most` digits.\n    fn int(self: *mut Self, most: usize) -> ?i32 {\n        let start = self.i\n        var v: i32 = 0\n        while self.i < self.s.len and self.i - start < most and is_digit(self.s[self.i]) {\n            v = v * 10 + ((self.s[self.i] - '0') as i32)\n            self.i += 1\n        }\n        if self.i == start { return null }\n        return v\n    }\n\n    /// `Jn`, `n` or `Mm.w.d`.\n    fn day(self: *mut Self) -> ?RuleDay {\n        if self.eat('J') {\n            let n = self.int(3) orelse return null\n            if n < 1 or n > 365 { return null }\n            return RuleDay{ .kind = 0, .day = n, .month = 0, .week = 0 }\n        }\n        if self.eat('M') {\n            let m = self.int(2) orelse return null\n            if !self.eat('.') { return null }\n            let w = self.int(1) orelse return null\n            if !self.eat('.') { return null }\n            let d = self.int(1) orelse return null\n            if m < 1 or m > 12 or w < 1 or w > 5 or d > 6 { return null }\n            return RuleDay{ .kind = 2, .day = d, .month = m as u8, .week = w as u8 }\n        }\n        let n = self.int(3) orelse return null\n        if n > 365 { return null }\n        return RuleDay{ .kind = 1, .day = n, .month = 0, .week = 0 }\n    }\n}\n\n// ------------------------------------------------------------------ timers\n\n/// Measures elapsed time on the monotonic clock.\npub struct Stopwatch {\n    start_ns: u64\n}\n\nimpl Stopwatch {\n    pub fn start() -> Stopwatch {\n        return Stopwatch{ .start_ns = time.monotonic() }\n    }\n\n    /// Elapsed time in milliseconds, fractional.\n    pub fn elapsed_ms(self: *Self) -> f64 {\n        return ((time.monotonic() - self.start_ns) as f64) / 1000000.0\n    }\n\n    /// Elapsed time as a Duration (whole milliseconds).\n    pub fn elapsed(self: *Self) -> Duration {\n        return Duration{ .ms = ((time.monotonic() - self.start_ns) / 1000000) as i64 }\n    }\n\n    /// Restart and return what had elapsed.\n    pub fn lap(self: *mut Self) -> Duration {\n        let d = self.elapsed()\n        self.start_ns = time.monotonic()\n        return d\n    }\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"epoch and round trips\" {\n    let e = utc(0)\n    expect_eq(e.year, 1970)\n    expect_eq(e.month, 1)\n    expect_eq(e.day, 1)\n    expect_eq(e.weekday(), 3)\n    expect_eq(e.iso(), \"1970-01-01T00:00:00Z\")\n    let t = utc(1789791314123)\n    expect_eq(t.iso(), \"2026-09-19T04:15:14.123Z\")\n    expect_eq(t.weekday(), 5)\n    expect_eq(t.day_of_year(), 262)\n    expect_eq(t.to_ms(), 1789791314123)\n    let b = utc(-1)\n    expect_eq(b.iso(), \"1969-12-31T23:59:59.999Z\")\n    expect_eq(b.to_ms(), -1)\n    let leap = utc(1709208000000)\n    expect_eq(leap.date_text(), \"2024-02-29\")\n    expect_eq(leap.to_ms(), 1709208000000)\n    let old = utc(-11676096000000)\n    expect_eq(old.date_text(), \"1600-01-01\")\n    expect_eq(old.to_ms(), -11676096000000)\n    expect(is_leap(2000))\n    expect(!is_leap(1900))\n    expect_eq(days_in_month(2024, 2), 29)\n}\n\ntest \"offsets and formatting\" {\n    let t = with_offset(1789791314123, 120)\n    expect_eq(t.hour, 6)\n    expect_eq(t.iso(), \"2026-09-19T06:15:14.123+02:00\")\n    expect_eq(t.to_ms(), 1789791314123)\n    expect_eq(t.to_utc().hour, 4)\n    let m = with_offset(1789791314123, -330)\n    expect_eq(m.offset_text(), \"-05:30\")\n    expect_eq(t.format(\"%Y-%m-%d %H:%M:%S.%3 %a %b %j %z 100%%\"), \"2026-09-19 06:15:14.123 Sat Sep 262 +02:00 100%\")\n    expect_eq(t.time_text(), \"06:15:14\")\n    expect_eq(t.format(\"%A %B %y %I%p %G-W%V-%u %s %Z\"), \"Saturday September 26 06AM 2026-W38-6 1789791314 +02\")\n    expect_eq(m.format(\"%Z\"), \"-0530\")\n    expect_eq(utc(0).format(\"%Z %I %p\"), \"UTC 12 AM\")\n    expect_eq(t.iso_basic(), \"20260919T061514.123+0200\")\n    expect_eq(utc(0).iso_basic(), \"19700101T000000Z\")\n}\n\ntest \"ISO weeks and ordinal dates\" {\n    let t = utc(1789791314123)\n    expect_eq(t.week_date(), \"2026-W38-6\")\n    expect_eq(t.ordinal_date(), \"2026-262\")\n    // January 3, 2021, a Sunday, is in 2020's 53rd week\n    expect_eq(date(2021, 1, 3).?.week_date(), \"2020-W53-7\")\n    expect_eq(date(2026, 12, 31).?.week_date(), \"2026-W53-4\")\n    expect_eq(date(2027, 1, 1).?.week_date(), \"2026-W53-5\")\n    expect_eq(date(2024, 12, 30).?.week_date(), \"2025-W01-1\")\n    expect_eq(weeks_in_year(2020), 53)\n    expect_eq(weeks_in_year(2026), 53)\n    expect_eq(weeks_in_year(2025), 52)\n    expect_eq(from_week(2020, 53, 7).?.date_text(), \"2021-01-03\")\n    expect(from_week(2025, 53, 1) == null)\n    expect(from_week(2026, 1, 8) == null)\n    expect_eq(from_ordinal(2024, 366).?.date_text(), \"2024-12-31\")\n    expect(from_ordinal(2025, 366) == null)\n}\n\ntest \"parsing\" {\n    let a = parse_iso(\"2026-09-19T04:15:14.123Z\").?\n    expect_eq(a.to_ms(), 1789791314123)\n    let b = parse_iso(\"2026-09-19 06:15:14+02:00\").?\n    expect_eq(b.to_ms(), 1789791314123 - 123)\n    let c = parse_iso(\"2024-02-29\").?\n    expect_eq(c.date_text(), \"2024-02-29\")\n    expect(parse_iso(\"2023-02-29\") == null)\n    expect(parse_iso(\"2024-13-01\") == null)\n    expect(parse_iso(\"nope\") == null)\n    expect(parse_iso(\"2024-02-29T25:00\") == null)\n    let d = parse_iso(\"2024-02-29T12:30\").?\n    expect_eq(d.time_text(), \"12:30:00\")\n    // the other forms name the same instant\n    let forms = [\"20260919T041514.123Z\", \"2026-W38-6T04:15:14.123Z\", \"2026W386T041514,123Z\", \"2026-262T04:15:14.1234567Z\", \"2026262T041514.123+0000\", \"2026-09-19T06:15:14.123+02\", \"2026-09-19t04:15:14.123z\"]\n    for f in forms {\n        let p = parse_iso(f).?\n        expect_eq(p.to_ms(), 1789791314123)\n    }\n    expect_eq(parse_iso(\"2026-09-19T04\").?.time_text(), \"04:00:00\")\n    expect_eq(parse_iso(\"20260919T0415\").?.time_text(), \"04:15:00\")\n    expect_eq(parse_iso(\"2026-W38\").?.date_text(), \"2026-09-14\")\n    let bad = [\"2026-W54-1\", \"2026-W38-8\", \"2025-366\", \"2026-09\", \"202609\", \"2026-09-19T04:15:14.Z\", \"2026-09-19T04:1\", \"2026-09-19T04:15+25:00\", \"2026-09-19T04:15:14Zjunk\", \"2026-0919\", \"2026-09-190\"]\n    for f in bad { expect(parse_iso(f) == null) }\n    // what the ISO printers write, the parser reads back\n    let e = with_offset(-1234567891011, -570)\n    expect_eq(parse_iso(e.iso()[..]).?.to_ms(), -1234567891011)\n    expect_eq(parse_iso(e.iso_basic()[..]).?.to_ms(), -1234567891011)\n}\n\ntest \"durations\" {\n    expect_eq(Duration.millis(250).text(), \"250ms\")\n    expect_eq(Duration.millis(3500).text(), \"3.5s\")\n    expect_eq(Duration.seconds(125).text(), \"2m 05s\")\n    expect_eq(Duration.minutes(62).text(), \"1h 02m\")\n    expect_eq(Duration.hours(76).text(), \"3d 04h\")\n    expect_eq(Duration.millis(-1500).text(), \"-1.5s\")\n    expect_eq(Duration.between(1000, 4000).ms, 3000)\n    expect_eq(Duration.minutes(1).plus(Duration.seconds(30)).ms, 90000)\n    expect_eq(add(1000, Duration.seconds(2)), 3000)\n    var sw = Stopwatch.start()\n    let d = sw.lap()\n    expect(d.ms >= 0)\n    expect(sw.elapsed_ms() >= 0.0)\n}\n\ntest \"duration arithmetic\" {\n    let h = Duration.hours(3)\n    expect(Duration.minutes(90) < h)\n    expect(h == Duration.minutes(180))\n    expect(Duration.seconds(-1) < Duration.millis(0))\n    expect_eq(h.times(2).ms, 21600000)\n    expect_eq(h.div(4).ms, 2700000)\n    expect_eq(h.ratio(Duration.minutes(90)), 2.0)\n    expect_eq(h.neg().ms, -10800000)\n    expect_eq(h.neg().abs().ms, 10800000)\n    expect(h.neg().is_negative() and Duration.millis(0).is_zero())\n    expect_eq(Duration.millis(1999).truncate(Duration.seconds(1)).ms, 1000)\n    expect_eq(Duration.millis(-1999).truncate(Duration.seconds(1)).ms, -1000)\n    expect_eq(Duration.millis(1500).round(Duration.seconds(1)).ms, 2000)\n    expect_eq(Duration.millis(1499).round(Duration.seconds(1)).ms, 1000)\n    expect_eq(Duration.millis(-1500).round(Duration.seconds(1)).ms, -2000)\n    expect_eq(Duration.minutes(-150).whole_hours(), -2)\n    expect_eq(Duration.days(3).whole_days(), 3)\n    let t = parse_iso(\"2024-01-31T10:00:00+01:00\").?\n    expect_eq(t.add_months(1).iso(), \"2024-02-29T10:00:00+01:00\")\n    expect_eq(t.add_months(13).date_text(), \"2025-02-28\")\n    expect_eq(t.add_months(-2).date_text(), \"2023-11-30\")\n    expect_eq(t.add_days(30).date_text(), \"2024-03-01\")\n    expect_eq(t.add_days(-31).date_text(), \"2023-12-31\")\n    expect_eq(parse_iso(\"2024-02-29\").?.add_years(1).date_text(), \"2025-02-28\")\n    expect_eq(t.plus(Duration.hours(15)).iso(), \"2024-02-01T01:00:00+01:00\")\n    expect_eq(t.minus(Duration.days(31)).date_text(), \"2023-12-31\")\n    let later = t.add_days(1)\n    expect_eq(t.until(&later).ms, 86400000)\n}\n\ntest \"ISO 8601 durations\" {\n    expect_eq(Duration.minutes(90).iso(), \"PT1H30M\")\n    expect_eq(Duration.millis(250).iso(), \"PT0.25S\")\n    expect_eq(Duration.millis(5).iso(), \"PT0.005S\")\n    expect_eq(Duration.hours(76).iso(), \"PT76H\")\n    expect_eq(Duration.millis(-1500).iso(), \"-PT1.5S\")\n    expect_eq(Duration.millis(0).iso(), \"PT0S\")\n    expect_eq(Duration.millis(3723004).iso(), \"PT1H2M3.004S\")\n    expect_eq(Duration.millis(-9223372036854775807 - 1).iso(), \"-PT2562047788015H12M55.808S\")\n    expect_eq(Duration.parse_iso(\"PT1H30M\").?.ms, 5400000)\n    expect_eq(Duration.parse_iso(\"P2DT3H\").?.ms, 183600000)\n    expect_eq(Duration.parse_iso(\"P1W\").?.ms, 604800000)\n    expect_eq(Duration.parse_iso(\"PT1.5H\").?.ms, 5400000)\n    expect_eq(Duration.parse_iso(\"PT0,25S\").?.ms, 250)\n    expect_eq(Duration.parse_iso(\"-PT5M\").?.ms, -300000)\n    expect_eq(Duration.parse_iso(\"PT0.0001S\").?.ms, 0)\n    let bad = [\"P1Y\", \"P2M\", \"PT\", \"P\", \"P1DT\", \"PT1S1H\", \"PT1.5H30M\", \"PT1HX\", \"1H\", \"PT-5M\", \"PT99999999999999999999S\", \"P1D1W\"]\n    for s in bad { expect(Duration.parse_iso(s) == null) }\n    let odd = [0, 1, 999, 1000, 59999, 3600000, 90061001, -42]\n    for n in odd { expect_eq(Duration.parse_iso(Duration.millis(n).iso()[..]).?.ms, n) }\n}\n\ntest \"POSIX rules\" {\n    let ny = parse_rule(\"EST5EDT,M3.2.0,M11.1.0\").?\n    expect_eq(ny.std_offset, -18000)\n    expect_eq(ny.dst_offset, -14400)\n    // 2026: daylight time from March 8, 07:00 UTC, to November 1, 06:00\n    expect(!ny.in_dst(1772953199999))\n    expect(ny.in_dst(1772953200000))\n    expect(ny.in_dst(1793512799999))\n    expect(!ny.in_dst(1793512800000))\n    // Sydney, whose summer spans the new year: April 5 03:00 AEDT to\n    // October 4 02:00 AEST\n    let syd = parse_rule(\"AEST-10AEDT,M10.1.0,M4.1.0/3\").?\n    expect(syd.in_dst(1768435200000))\n    expect(!syd.in_dst(1775318400000))\n    expect(syd.in_dst(1775318399999))\n    expect(!syd.in_dst(1791043199999))\n    expect(syd.in_dst(1791043200000))\n    let india = parse_rule(\"<+0530>-5:30\").?\n    expect(!india.has_dst)\n    expect_eq(india.std_offset, 19800)\n    expect_eq(india.std_abbrev, \"+0530\")\n    // no dates: the United States' rule; J and zero-based days\n    expect(parse_rule(\"PST8PDT\").?.in_dst(1782864000000))\n    let j = parse_rule(\"XST3XDT,J60/0,J300/0\").?\n    expect_eq(j.start.days_in(2024), days_from_civil(2024, 3, 1))\n    expect_eq(parse_rule(\"XST3XDT,59,300\").?.start.days_in(2024), days_from_civil(2024, 2, 29))\n    // permanent daylight time, as RFC 8536 writes it\n    let always = parse_rule(\"EST5EDT,0/0,J365/25\").?\n    expect(always.in_dst(1768435200000) and always.in_dst(1782864000000))\n    let bad = [\"EST\", \"E5\", \"EST5EDT,M13.1.0,M11.1.0\", \"EST5EDT,M3.2.0\", \"EST5EDT,M3.2.7,M11.1.0\", \"EST5EDT,M3.2.0,M11.1.0,\", \"<AB-5\"]\n    for s in bad { expect(parse_rule(s) == null) }\n}\n\n/// Big-endian bytes of `v`, `n` of them.\nfn put_be(out: *mut String, v: i64, n: usize) {\n    var k = n\n    while k > 0 {\n        k -= 1\n        out.push_byte(@truncate(u8, v >> ((k * 8) as i64)))\n    }\n}\n\n/// A TZif version 2 file of New York's shape: local mean time, then EST\n/// from 1883, EDT and EST in 2026, and the rule after.\nfn sample_tzif() -> String {\n    var b = String.new()\n    b.append(\"TZif2\")\n    var k: usize = 0\n    while k < 15 {\n        b.push_byte(0)\n        k += 1\n    }\n    for c in [0, 0, 0, 0, 1, 4] { put_be(&mut b, c, 4) }\n    put_be(&mut b, -17762, 4)\n    b.push_byte(0)\n    b.push_byte(0)\n    b.append(\"LMT\")\n    b.push_byte(0)\n    b.append(\"TZif2\")\n    k = 0\n    while k < 15 {\n        b.push_byte(0)\n        k += 1\n    }\n    for c in [0, 0, 0, 3, 3, 12] { put_be(&mut b, c, 4) }\n    for t in [-2717650800, 1772953200, 1793512800] { put_be(&mut b, t, 8) }\n    for i in [2, 1, 2] { put_be(&mut b, i, 1) }\n    // the types: offset, daylight, where the abbreviation begins\n    for ty in [(-17762, 0, 0), (-14400, 1, 4), (-18000, 0, 8)] {\n        put_be(&mut b, ty.0, 4)\n        put_be(&mut b, ty.1, 1)\n        put_be(&mut b, ty.2, 1)\n    }\n    b.append(\"LMT\")\n    b.push_byte(0)\n    b.append(\"EDT\")\n    b.push_byte(0)\n    b.append(\"EST\")\n    b.push_byte(0)\n    b.append(\"\\nEST5EDT,M3.2.0,M11.1.0\\n\")\n    return b\n}\n\ntest \"TZif files\" {\n    let data = sample_tzif()\n    let z = try from_tzif(\"Test/New_York\", data[..])\n    expect_eq(z.periods.len, 4)\n    expect(z.has_rule)\n    // 1874: local mean time, -4:56:02, which rounds to -4:56\n    expect_eq(z.offset_seconds_at(-3000000000000), -17762)\n    expect_eq(z.offset_at(-3000000000000), -296)\n    expect_eq(z.abbrev_at(-3000000000000), \"LMT\")\n    expect_eq(z.at(-3000000000000).to_ms(), -3000000000000)\n    expect_eq(z.abbrev_at(1768435200000), \"EST\")\n    expect(!z.is_dst_at(1768435200000))\n    expect_eq(z.abbrev_at(1772953200000), \"EDT\")\n    expect(z.is_dst_at(1782864000000))\n    expect_eq(z.offset_at(1793512800000), -300)\n    // past the listed changes, the rule\n    expect_eq(z.abbrev_at(1814400000000), \"EDT\")\n    expect_eq(z.offset_at(1799971200000), -300)\n    expect_eq(z.format(1782864000000, \"%Y-%m-%d %H:%M %Z %z\"), \"2026-06-30 20:00 EDT -04:00\")\n    expect(tzif_fails(\"TZif2 but short\"))\n    expect(tzif_fails(\"not a zone at all, not a zone at all, not one\"))\n}\n\nfn tzif_fails(b: []u8) -> bool {\n    _ = from_tzif(\"x\", b) catch { return true }\n    return false\n}\n\n/// The error `zone` gives for a name; null when it finds the zone.\nfn zone_err(name: []u8) -> ?error {\n    _ = zone(name) catch |e| { return e }\n    return null\n}\n\ntest \"wall clocks in a zone\" {\n    let z = try zone(\"EST5EDT,M3.2.0,M11.1.0\")\n    expect_eq(z.name, \"EST5EDT,M3.2.0,M11.1.0\")\n    let noon = parse_iso(\"2026-07-04T12:00\").?\n    expect_eq(utc(z.instant(&noon)).iso(), \"2026-07-04T16:00:00Z\")\n    // 02:30 on March 8 does not happen; it is read as 03:30 EDT\n    let skipped = parse_iso(\"2026-03-08T02:30\").?\n    expect_eq(z.at(z.instant(&skipped)).iso(), \"2026-03-08T03:30:00-04:00\")\n    // 01:30 on November 1 happens twice; the first is EDT\n    let twice = parse_iso(\"2026-11-01T01:30\").?\n    expect_eq(z.at(z.instant(&twice)).iso(), \"2026-11-01T01:30:00-04:00\")\n    let after = parse_iso(\"2026-11-01T03:00\").?\n    expect_eq(z.at(z.instant(&after)).iso(), \"2026-11-01T03:00:00-05:00\")\n    // a day later on the clock across the change is 25 hours\n    let evening = parse_iso(\"2026-10-31T18:00\").?\n    let next = evening.add_days(1)\n    expect_eq(Duration.between(z.instant(&evening), z.instant(&next)).whole_hours(), 25)\n    let fixed = try zone(\"+05:30\")\n    expect_eq(fixed.at(0).iso(), \"1970-01-01T05:30:00+05:30\")\n    expect_eq(fixed.abbrev_at(0), \"+0530\")\n    expect_eq((try zone(\"UTC\")).offset_at(1789791314123), 0)\n    expect(zone_err(\"../../etc/passwd\").? == error.InvalidInput)\n    expect(zone_err(\"Nowhere/At_All\").? == error.NotFound)\n    expect(zone_err(\"\").? == error.InvalidInput)\n    expect(zone_err(\"+5\").? == error.InvalidInput)\n}\n\ntest \"the platform's zones\" {\n    // where there is a database: every desktop platform, not the playground\n    let ny = zone(\"America/New_York\") catch { return }\n    expect_eq(ny.offset_at(1768435200000), -300)\n    expect_eq(ny.offset_at(1782864000000), -240)\n    expect_eq(ny.abbrev_at(1782864000000), \"EDT\")\n    expect_eq(ny.offset_at(-2208988800000), -300)\n    let berlin = try zone(\"Europe/Berlin\")\n    expect_eq(berlin.offset_at(1768435200000), 60)\n    expect_eq(berlin.offset_at(1782864000000), 120)\n    let kolkata = try zone(\"Asia/Kolkata\")\n    expect_eq(kolkata.offset_at(1789791314123), 330)\n    let sydney = try zone(\"Australia/Sydney\")\n    expect_eq(sydney.offset_at(1768435200000), 660)\n    expect_eq(sydney.offset_at(1782864000000), 600)\n    // July 2100: from the files' rule, or ICU's list, which runs to 2200\n    expect_eq(ny.offset_at(4118126400000), -240)\n    let here = local_zone()\n    let now = time.now()\n    expect_eq(here.offset_at(now) as i64, time.utc_offset(now))\n}\n";
static const char nx_str_882[5] = "sort";
static const char nx_str_883[8592] = "// std.sort: sorting by a comparison of your own, stable sorting, and\n// searching sorted slices, written in Nexium over the slice's `swap`.\n//\n// `import std.sort` then:\n//\n//     sort.by(Point, points[..], |a: *Point, b: *Point| -> bool { return a.x < b.x })\n//     sort.stable_by(Task, tasks[..], by_priority)     // equal elements keep their order\n//     sort.by_key(Point, i64, points[..], |p: *Point| -> i64 { return p.y })\n//     let at = sort.binary_search(i64, xs[..], 42)      // a position of 42, or null\n//\n// `by` is a heapsort: in place, O(n log n) comparisons whatever the input,\n// and not stable. The stable sorts merge-sort the positions and then move\n// each element into place along the cycles of the permutation, so no\n// element is ever copied and any element type sorts. `xs.sort()` sorts by\n// `<` without a comparison.\n\n/// Sorts `xs` so that `less(b, a)` holds for no `a` before `b`: ascending by\n/// `less`. The order of equal elements is not kept.\npub fn by(comptime T: type, xs: []mut T, less: fn(*T, *T) -> bool) {\n    let n = xs.len\n    if n < 2 { return }\n    var start = n / 2\n    while start > 0 {\n        start -= 1\n        sift_down(T, xs, start, n, less)\n    }\n    var end = n\n    while end > 1 {\n        end -= 1\n        xs.swap(0, end)\n        sift_down(T, xs, 0, end, less)\n    }\n}\n\n// the heap property from `root` down, within `xs[..end]`\nfn sift_down(comptime T: type, xs: []mut T, root0: usize, end: usize, less: fn(*T, *T) -> bool) {\n    var root = root0\n    while true {\n        var child = 2 * root + 1\n        if child >= end { return }\n        if child + 1 < end and less(&xs[child], &xs[child + 1]) { child += 1 }\n        if !less(&xs[root], &xs[child]) { return }\n        xs.swap(root, child)\n        root = child\n    }\n}\n\n/// Sorts `xs` ascending by `less`, keeping equal elements in the order they\n/// had.\npub fn stable_by(comptime T: type, xs: []mut T, less: fn(*T, *T) -> bool) {\n    let n = xs.len\n    if n < 2 { return }\n    var order = positions(n)\n    var tmp = positions(n)\n    var width: usize = 1\n    while width < n {\n        var lo: usize = 0\n        while lo < n {\n            let mid = if lo + width < n { lo + width } else { n }\n            let hi = if lo + 2 * width < n { lo + 2 * width } else { n }\n            var i = lo\n            var j = mid\n            var k = lo\n            while i < mid and j < hi {\n                // the right one goes first only when strictly less: stable\n                if less(&xs[order[j]], &xs[order[i]]) {\n                    tmp[k] = order[j]\n                    j += 1\n                } else {\n                    tmp[k] = order[i]\n                    i += 1\n                }\n                k += 1\n            }\n            while i < mid {\n                tmp[k] = order[i]\n                i += 1\n                k += 1\n            }\n            while j < hi {\n                tmp[k] = order[j]\n                j += 1\n                k += 1\n            }\n            lo = hi\n        }\n        for p, q in tmp { order[q] = p }\n        width *= 2\n    }\n    permute(T, xs, &order)\n}\n\n/// Sorts `xs` ascending by `key` of each element, keeping elements with\n/// equal keys in the order they had; `key` is called once per element.\npub fn by_key(comptime T: type, comptime K: type where K: Ord, xs: []mut T, key: fn(*T) -> K) {\n    let n = xs.len\n    if n < 2 { return }\n    var keys = List(K).with_capacity(n)\n    for i in 0..n { keys.append(key(&xs[i])) }\n    var order = positions(n)\n    var tmp = positions(n)\n    var width: usize = 1\n    while width < n {\n        var lo: usize = 0\n        while lo < n {\n            let mid = if lo + width < n { lo + width } else { n }\n            let hi = if lo + 2 * width < n { lo + 2 * width } else { n }\n            var i = lo\n            var j = mid\n            var k = lo\n            while i < mid and j < hi {\n                if keys[order[j]] < keys[order[i]] {\n                    tmp[k] = order[j]\n                    j += 1\n                } else {\n                    tmp[k] = order[i]\n                    i += 1\n                }\n                k += 1\n            }\n            while i < mid {\n                tmp[k] = order[i]\n                i += 1\n                k += 1\n            }\n            while j < hi {\n                tmp[k] = order[j]\n                j += 1\n                k += 1\n            }\n            lo = hi\n        }\n        for p, q in tmp { order[q] = p }\n        width *= 2\n    }\n    permute(T, xs, &order)\n}\n\nfn positions(n: usize) -> List(usize) {\n    var out = List(usize).with_capacity(n)\n    for i in 0..n { out.append(i) }\n    return out\n}\n\n// moves the elements so that position k holds what was at order[k]: each\n// cycle of the permutation by swaps along it\nfn permute(comptime T: type, xs: []mut T, order: *List(usize)) {\n    let n = xs.len\n    var done = List(bool).with_capacity(n)\n    for i in 0..n { done.append(false) }\n    for start in 0..n {\n        if done[start] { continue }\n        var k = start\n        while true {\n            done[k] = true\n            let from = order[k]\n            if from == start { break }\n            xs.swap(k, from)\n            k = from\n        }\n    }\n}\n\n/// Whether `xs` is ascending by `<`.\npub fn is_sorted(comptime T: type where T: Ord, xs: []T) -> bool {\n    var i: usize = 1\n    while i < xs.len {\n        if xs[i] < xs[i - 1] { return false }\n        i += 1\n    }\n    return true\n}\n\n/// Whether `xs` is ascending by `less`.\npub fn is_sorted_by(comptime T: type, xs: []T, less: fn(*T, *T) -> bool) -> bool {\n    var i: usize = 1\n    while i < xs.len {\n        if less(&xs[i], &xs[i - 1]) { return false }\n        i += 1\n    }\n    return true\n}\n\n/// In an ascending `xs`, the first position whose element is not less than\n/// `x`: where `x` would go before any equal to it.\npub fn lower_bound(comptime T: type where T: Ord, xs: []T, x: T) -> usize {\n    var lo: usize = 0\n    var hi = xs.len\n    while lo < hi {\n        let mid = lo + (hi - lo) / 2\n        if xs[mid] < x { lo = mid + 1 } else { hi = mid }\n    }\n    return lo\n}\n\n/// In an ascending `xs`, the first position whose element is greater than\n/// `x`: where `x` would go after any equal to it.\npub fn upper_bound(comptime T: type where T: Ord, xs: []T, x: T) -> usize {\n    var lo: usize = 0\n    var hi = xs.len\n    while lo < hi {\n        let mid = lo + (hi - lo) / 2\n        if x < xs[mid] { hi = mid } else { lo = mid + 1 }\n    }\n    return lo\n}\n\n/// In an ascending `xs`, a position holding `x`, or null.\npub fn binary_search(comptime T: type where T: Ord, xs: []T, x: T) -> ?usize {\n    let at = lower_bound(T, xs, x)\n    if at < xs.len and !(x < xs[at]) { return at }\n    return null\n}\n\n// ------------------------------------------------------------------ tests\n\nstruct Task {\n    name: String\n    priority: i64\n}\n\nfn later(a: *i64, b: *i64) -> bool {\n    return a.* > b.*\n}\n\nfn by_priority(a: *Task, b: *Task) -> bool {\n    return a.priority < b.priority\n}\n\nfn priority_of(t: *Task) -> i64 {\n    return t.priority\n}\n\nfn task(name: []u8, priority: i64) -> Task {\n    return Task{ .name = String.from(name), .priority = priority }\n}\n\ntest \"by sorts with the comparison given\" {\n    var xs = [5, 1, 4, 1, 5, 9, 2, 6]\n    by(i64, xs[..], later)\n    expect(xs[0] == 9 and xs[1] == 6 and xs[7] == 1)\n    expect(is_sorted_by(i64, xs[..], later))\n    var one = [7]\n    by(i64, one[..], later)\n    expect(one[0] == 7)\n}\n\ntest \"stable_by keeps equal elements in order, and moves owned ones\" {\n    var ts = List(Task).new()\n    ts.append(task(\"b\", 2))\n    ts.append(task(\"a\", 1))\n    ts.append(task(\"c\", 2))\n    ts.append(task(\"d\", 1))\n    ts.append(task(\"e\", 0))\n    stable_by(Task, ts[..], by_priority)\n    expect(ts[0].name == \"e\" and ts[1].name == \"a\" and ts[2].name == \"d\" and ts[3].name == \"b\" and ts[4].name == \"c\")\n}\n\ntest \"by_key calls the key once per element\" {\n    var ts = List(Task).new()\n    ts.append(task(\"x\", 3))\n    ts.append(task(\"y\", 1))\n    ts.append(task(\"z\", 3))\n    ts.append(task(\"w\", 2))\n    by_key(Task, i64, ts[..], priority_of)\n    expect(ts[0].name == \"y\" and ts[1].name == \"w\" and ts[2].name == \"x\" and ts[3].name == \"z\")\n}\n\ntest \"searching an ascending slice\" {\n    let xs = [1, 3, 3, 3, 7, 9]\n    expect(is_sorted(i64, xs[..]))\n    expect(lower_bound(i64, xs[..], 3) == 1)\n    expect(upper_bound(i64, xs[..], 3) == 4)\n    expect(lower_bound(i64, xs[..], 8) == 5)\n    expect(lower_bound(i64, xs[..], 10) == 6)\n    expect((binary_search(i64, xs[..], 7) orelse 99) == 4)\n    expect(binary_search(i64, xs[..], 4) == null)\n    expect(!is_sorted(i64, [2, 1][..]))\n}\n";
