static const char nx_str_885[3484] = "// std.heap: a priority queue, written in Nexium: a binary heap over a List,\n// ordered by a comparison of your own.\n//\n// `import std.heap` then:\n//\n//     var q = heap.by(Job, |a: *Job, b: *Job| -> bool { return a.due < b.due })\n//     q.push(job)\n//     while true {\n//         let next = q.pop() orelse break       // the least by the comparison first\n//         run(next)\n//     }\n//\n// `push` and `pop` are O(log n), `peek` O(1). A heap that pops the greatest\n// first is one whose comparison says `a > b`.\n\n/// A priority queue: `pop` gives the least element by `less` still in it.\npub struct Heap(T){\n    items: List(T)\n    less: fn(*T, *T) -> bool\n}\n\n/// An empty heap ordered by `less`.\npub fn by(comptime T: type, less: fn(*T, *T) -> bool) -> Heap(T) {\n    return Heap(T){ .items = List(T).new(), .less = less }\n}\n\nimpl(T) Heap(T) {\n    /// Adds `x`.\n    pub fn push(self: *mut Self, own x: T) {\n        let less = self.less\n        self.items.append(x)\n        var i = self.items.len - 1\n        while i > 0 {\n            let parent = (i - 1) / 2\n            if !less(&self.items[i], &self.items[parent]) { break }\n            self.items.swap(i, parent)\n            i = parent\n        }\n    }\n\n    /// Takes out the least element, or null when the heap is empty.\n    pub fn pop(self: *mut Self) -> ?T {\n        let n = self.items.len\n        if n == 0 { return null }\n        self.items.swap(0, n - 1)\n        let top = self.items.pop()\n        let less = self.less\n        let end = n - 1\n        var root: usize = 0\n        while true {\n            var child = 2 * root + 1\n            if child >= end { break }\n            if child + 1 < end and less(&self.items[child + 1], &self.items[child]) { child += 1 }\n            if !less(&self.items[child], &self.items[root]) { break }\n            self.items.swap(root, child)\n            root = child\n        }\n        return top\n    }\n\n    /// The least element, left in place; null when the heap is empty.\n    pub fn peek(self: *Self) -> ?*T {\n        if self.items.len == 0 { return null }\n        return &self.items[0]\n    }\n\n    pub fn len(self: *Self) -> usize {\n        return self.items.len\n    }\n\n    pub fn is_empty(self: *Self) -> bool {\n        return self.items.len == 0\n    }\n\n    pub fn clear(self: *mut Self) {\n        self.items.clear()\n    }\n}\n\n// ------------------------------------------------------------------ tests\n\nstruct Job {\n    name: String\n    due: i64\n}\n\nfn sooner(a: *Job, b: *Job) -> bool {\n    return a.due < b.due\n}\n\nfn larger(a: *i64, b: *i64) -> bool {\n    return a.* > b.*\n}\n\nfn job(name: []u8, due: i64) -> Job {\n    return Job{ .name = String.from(name), .due = due }\n}\n\ntest \"pop gives the least first, owned values and all\" {\n    var q = by(Job, sooner)\n    q.push(job(\"c\", 30))\n    q.push(job(\"a\", 10))\n    q.push(job(\"d\", 40))\n    q.push(job(\"b\", 20))\n    expect(q.len() == 4)\n    if let p = q.peek() { expect(p.name == \"a\") }\n    var order = String.new()\n    while true {\n        let next = q.pop() orelse break\n        order.append(next.name[..])\n    }\n    expect(order == \"abcd\")\n    expect(q.is_empty())\n    expect(q.pop() == null)\n}\n\ntest \"the greatest first, with the comparison turned around\" {\n    var q = by(i64, larger)\n    for x in [5, 1, 9, 3, 7, 9] { q.push(x) }\n    var out = List(i64).new()\n    while true {\n        let x = q.pop() orelse break\n        out.append(x)\n    }\n    expect(out.len == 6 and out[0] == 9 and out[1] == 9 and out[2] == 7 and out[5] == 1)\n}\n";
static const char nx_str_886[4] = "set";
static const char nx_str_887[3772] = "// std.set: a set of values, written in Nexium over `Map(T, bool)`: its\n// elements are the types a Map takes as keys (integers, bool, char, `[]u8`,\n// `String`).\n//\n// `import std.set` then:\n//\n//     var seen = set.of(i64)\n//     if seen.add(id) { println(\"new: {}\", .{id}) }\n//     let common = set.intersection(i64, &a, &b)\n//\n// `add`, `contains` and `remove` take a value like a Map's key: a copy, or\n// for a `String` set an owned string (`name.clone()` keeps yours).\n\n/// A set: each value at most once, in the order each was first added.\npub struct Set(T){\n    m: Map(T, bool)\n}\n\n/// An empty set.\npub fn of(comptime T: type) -> Set(T) {\n    return Set(T){ .m = Map(T, bool).new() }\n}\n\nimpl(T) Set(T) {\n    /// Adds `x`; true when it was not already there.\n    pub fn add(self: *mut Self, own x: T) -> bool {\n        if self.m.contains(x) { return false }\n        self.m.put(x, true)\n        return true\n    }\n\n    pub fn contains(self: *Self, x: T) -> bool {\n        return self.m.contains(x)\n    }\n\n    /// Takes `x` out; true when it was there.\n    pub fn remove(self: *mut Self, x: T) -> bool {\n        return self.m.remove(x)\n    }\n\n    pub fn len(self: *Self) -> usize {\n        return self.m.len\n    }\n\n    pub fn is_empty(self: *Self) -> bool {\n        return self.m.len == 0\n    }\n\n    pub fn clear(self: *mut Self) {\n        self.m.clear()\n    }\n\n    /// The elements, in the order each was first added.\n    pub fn items(self: *Self) -> List(T) {\n        return self.m.keys()\n    }\n}\n\n/// The values in `a` or `b`.\npub fn union(comptime T: type, a: *Set(T), b: *Set(T)) -> Set(T) {\n    var out = of(T)\n    var ks = a.m.keys()\n    while true {\n        let k = ks.pop() orelse break\n        _ = out.add(k)\n    }\n    var ks2 = b.m.keys()\n    while true {\n        let k = ks2.pop() orelse break\n        _ = out.add(k)\n    }\n    return out\n}\n\n/// The values in both `a` and `b`.\npub fn intersection(comptime T: type, a: *Set(T), b: *Set(T)) -> Set(T) {\n    var out = of(T)\n    var ks = a.m.keys()\n    while true {\n        let k = ks.pop() orelse break\n        if b.m.contains(k) { _ = out.add(k) }\n    }\n    return out\n}\n\n/// The values in `a` that are not in `b`.\npub fn difference(comptime T: type, a: *Set(T), b: *Set(T)) -> Set(T) {\n    var out = of(T)\n    var ks = a.m.keys()\n    while true {\n        let k = ks.pop() orelse break\n        if !b.m.contains(k) { _ = out.add(k) }\n    }\n    return out\n}\n\n/// Whether every value of `a` is in `b`.\npub fn is_subset(comptime T: type, a: *Set(T), b: *Set(T)) -> bool {\n    var ks = a.m.keys()\n    while true {\n        let k = ks.pop() orelse break\n        if !b.m.contains(k) { return false }\n    }\n    return true\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"each value once\" {\n    var s = of(i64)\n    expect(s.add(3))\n    expect(s.add(5))\n    expect(!s.add(3))\n    expect(s.len() == 2 and s.contains(5) and !s.contains(4))\n    expect(s.remove(3) and !s.remove(3))\n    expect(s.len() == 1)\n    s.clear()\n    expect(s.is_empty())\n}\n\ntest \"strings, owned by the set\" {\n    var s = of(String)\n    let name = String.from(\"ada\")\n    expect(s.add(name.clone()))\n    expect(!s.add(String.from(\"ada\")))\n    expect(s.contains(name.clone()) and name == \"ada\")\n    expect(s.items().len == 1)\n}\n\ntest \"union, intersection, difference, subset\" {\n    var a = of(i64)\n    var b = of(i64)\n    for x in [1, 2, 3, 4] { _ = a.add(x) }\n    for x in [3, 4, 5] { _ = b.add(x) }\n    let u = union(i64, &a, &b)\n    let i = intersection(i64, &a, &b)\n    let d = difference(i64, &a, &b)\n    expect(u.len() == 5 and i.len() == 2 and d.len() == 2)\n    expect(i.contains(3) and i.contains(4) and d.contains(1) and !d.contains(3))\n    expect(is_subset(i64, &i, &a) and !is_subset(i64, &a, &b))\n}\n";
static const char nx_str_888[6] = "deque";
static const char nx_str_889[3985] = "// std.deque: a double-ended queue, written in Nexium: two Lists back to\n// back, the first kept reversed, so both ends push and pop in O(1)\n// amortized (when one side runs out, half of the other moves over).\n//\n// `import std.deque` then:\n//\n//     var q = deque.of(Job)\n//     q.push_back(job)\n//     q.push_front(urgent)\n//     let next = q.pop_front() orelse return\n//     if let last = q.last() { ... }                 // a view, left in place\n\n/// A double-ended queue.\npub struct Deque(T){\n    // the elements before `tail`, reversed: its last is the deque's first\n    head: List(T)\n    tail: List(T)\n}\n\n/// An empty deque.\npub fn of(comptime T: type) -> Deque(T) {\n    return Deque(T){ .head = List(T).new(), .tail = List(T).new() }\n}\n\n// `src[0..h)` onto the empty `dst`, reversed, for h half of src (rounded\n// up); the rest of src stays in order\nfn move_half(comptime T: type, src: *mut List(T), dst: *mut List(T)) {\n    let n = src.len\n    if n == 0 { return }\n    let h = (n + 1) / 2\n    src[..].reverse()\n    for i in 0..h {\n        let x = src.pop() orelse break\n        dst.append(x)\n    }\n    dst[..].reverse()\n    src[..].reverse()\n}\n\nimpl(T) Deque(T) {\n    pub fn push_back(self: *mut Self, own x: T) {\n        self.tail.append(x)\n    }\n\n    pub fn push_front(self: *mut Self, own x: T) {\n        self.head.append(x)\n    }\n\n    /// Takes out the first element, or null when empty.\n    pub fn pop_front(self: *mut Self) -> ?T {\n        if self.head.len == 0 { move_half(T, &mut self.tail, &mut self.head) }\n        return self.head.pop()\n    }\n\n    /// Takes out the last element, or null when empty.\n    pub fn pop_back(self: *mut Self) -> ?T {\n        if self.tail.len == 0 { move_half(T, &mut self.head, &mut self.tail) }\n        return self.tail.pop()\n    }\n\n    pub fn len(self: *Self) -> usize {\n        return self.head.len + self.tail.len\n    }\n\n    pub fn is_empty(self: *Self) -> bool {\n        return self.head.len + self.tail.len == 0\n    }\n\n    /// The element `i` places from the front, left in place; null past the end.\n    pub fn get(self: *Self, i: usize) -> ?*T {\n        let h = self.head.len\n        if i < h { return &self.head[h - 1 - i] }\n        if i - h < self.tail.len { return &self.tail[i - h] }\n        return null\n    }\n\n    pub fn first(self: *Self) -> ?*T {\n        return self.get(0)\n    }\n\n    pub fn last(self: *Self) -> ?*T {\n        let n = self.head.len + self.tail.len\n        if n == 0 { return null }\n        return self.get(n - 1)\n    }\n\n    pub fn clear(self: *mut Self) {\n        self.head.clear()\n        self.tail.clear()\n    }\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"a queue: in at the back, out at the front\" {\n    var q = of(i64)\n    for x in [1, 2, 3, 4, 5] { q.push_back(x) }\n    expect(q.len() == 5)\n    expect((q.pop_front() orelse 0) == 1)\n    expect((q.pop_front() orelse 0) == 2)\n    q.push_back(6)\n    var rest = List(i64).new()\n    while true {\n        let x = q.pop_front() orelse break\n        rest.append(x)\n    }\n    expect(rest.len == 4 and rest[0] == 3 and rest[3] == 6)\n    expect(q.is_empty() and q.pop_back() == null)\n}\n\ntest \"both ends, and a view by position\" {\n    var q = of(i64)\n    q.push_back(2)\n    q.push_front(1)\n    q.push_back(3)\n    q.push_front(0)\n    if let x = q.get(0) { expect(x.* == 0) }\n    if let x = q.get(3) { expect(x.* == 3) }\n    expect(q.get(4) == null)\n    expect((q.pop_back() orelse 9) == 3)\n    expect((q.pop_back() orelse 9) == 2)\n    expect((q.pop_back() orelse 9) == 1)\n    expect((q.pop_back() orelse 9) == 0)\n}\n\ntest \"owned values move in and out\" {\n    var q = of(String)\n    q.push_back(String.from(\"b\"))\n    q.push_front(String.from(\"a\"))\n    q.push_back(String.from(\"c\"))\n    if let f = q.first() { expect(f.* == \"a\") }\n    if let l = q.last() { expect(l.* == \"c\") }\n    var all = String.new()\n    while true {\n        let s = q.pop_back() orelse break\n        all.append(s[..])\n    }\n    expect(all == \"cba\")\n}\n";
