static const char nx_str_891[9178] = "// std.hash: hash functions, written in Nexium: FNV-1a (64-bit), SipHash-2-4\n// (keyed: a table whose keys an adversary picks), and SHA-256 (checksums and\n// content addresses).\n//\n// `import std.hash` then:\n//\n//     let h = hash.fnv1a64(name)                    // fast, not keyed\n//     let k = hash.siphash(key16, name)             // keyed with 16 bytes\n//     let sum = hash.sha256_hex(file_text)          // 64 hex digits\n//\n//     var s = hash.Sha256.new()                     // or piece by piece\n//     s.update(part1)\n//     s.update(part2)\n//     let digest = s.finish()                       // 32 bytes\n//\n// `std.bytes` keeps the 32-bit `fnv1a` and `crc32`.\n\nimport std.bytes\n\n/// FNV-1a over 64 bits.\npub fn fnv1a64(data: []u8) -> u64 {\n    var h: u64 = 14695981039346656037\n    for b in data { h = (h ^ (b as u64)) *% 1099511628211 }\n    return h\n}\n\nfn rotl64(x: u64, n: u64) -> u64 {\n    return (x << n) | (x >> (64 - n))\n}\n\nfn le64(data: []u8, at: usize) -> u64 {\n    var v: u64 = 0\n    var i: usize = 8\n    while i > 0 {\n        i -= 1\n        v = (v << 8) | (data[at + i] as u64)\n    }\n    return v\n}\n\n/// SipHash-2-4 of `data` under a 16-byte key (panics on another length):\n/// what a hash table keyed by untrusted input should use.\npub fn siphash(key: []u8, data: []u8) -> u64 {\n    if key.len != 16 { panic(\"siphash takes a 16-byte key\") }\n    let k0 = le64(key, 0)\n    let k1 = le64(key, 8)\n    var v0: u64 = k0 ^ 0x736f6d6570736575\n    var v1: u64 = k1 ^ 0x646f72616e646f6d\n    var v2: u64 = k0 ^ 0x6c7967656e657261\n    var v3: u64 = k1 ^ 0x7465646279746573\n    let full = data.len - data.len % 8\n    var at: usize = 0\n    while at < full {\n        let m = le64(data, at)\n        v3 ^= m\n        for r in 0..2 {\n            v0 = v0 +% v1\n            v1 = rotl64(v1, 13) ^ v0\n            v0 = rotl64(v0, 32)\n            v2 = v2 +% v3\n            v3 = rotl64(v3, 16) ^ v2\n            v0 = v0 +% v3\n            v3 = rotl64(v3, 21) ^ v0\n            v2 = v2 +% v1\n            v1 = rotl64(v1, 17) ^ v2\n            v2 = rotl64(v2, 32)\n        }\n        v0 ^= m\n        at += 8\n    }\n    // the last block: the rest of the bytes, and the length's low byte on top\n    var last: u64 = ((data.len & 255) as u64) << 56\n    var i = data.len\n    while i > full {\n        i -= 1\n        last |= (data[i] as u64) << (((i - full) * 8) as u64)\n    }\n    v3 ^= last\n    for r in 0..2 {\n        v0 = v0 +% v1\n        v1 = rotl64(v1, 13) ^ v0\n        v0 = rotl64(v0, 32)\n        v2 = v2 +% v3\n        v3 = rotl64(v3, 16) ^ v2\n        v0 = v0 +% v3\n        v3 = rotl64(v3, 21) ^ v0\n        v2 = v2 +% v1\n        v1 = rotl64(v1, 17) ^ v2\n        v2 = rotl64(v2, 32)\n    }\n    v0 ^= last\n    v2 ^= 255\n    for r in 0..4 {\n        v0 = v0 +% v1\n        v1 = rotl64(v1, 13) ^ v0\n        v0 = rotl64(v0, 32)\n        v2 = v2 +% v3\n        v3 = rotl64(v3, 16) ^ v2\n        v0 = v0 +% v3\n        v3 = rotl64(v3, 21) ^ v0\n        v2 = v2 +% v1\n        v1 = rotl64(v1, 17) ^ v2\n        v2 = rotl64(v2, 32)\n    }\n    return v0 ^ v1 ^ v2 ^ v3\n}\n\n// ------------------------------------------------------------------ SHA-256\n\nconst K256: [64]u32 = [\n    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,\n    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,\n    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,\n    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,\n    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,\n    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,\n    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,\n    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,\n]\n\nfn rotr32(x: u32, n: u32) -> u32 {\n    return (x >> n) | (x << (32 - n))\n}\n\n/// SHA-256 piece by piece: `update` as the bytes arrive, `finish` once.\npub struct Sha256 {\n    h: [8]u32\n    // the bytes of a block not yet full\n    pending: String\n    total: u64\n}\n\nimpl Sha256 {\n    pub fn new() -> Sha256 {\n        return Sha256{ .h = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19], .pending = String.new(), .total = 0 }\n    }\n\n    pub fn update(self: *mut Self, data: []u8) {\n        self.total += data.len as u64\n        var at: usize = 0\n        // a block begun by an earlier update\n        if self.pending.len > 0 {\n            while self.pending.len < 64 and at < data.len {\n                self.pending.push_byte(data[at])\n                at += 1\n            }\n            if self.pending.len < 64 { return }\n            let block = self.pending.clone()\n            self.compress(block[..])\n            self.pending.clear()\n        }\n        while at + 64 <= data.len {\n            self.compress(data[at..at + 64])\n            at += 64\n        }\n        while at < data.len {\n            self.pending.push_byte(data[at])\n            at += 1\n        }\n    }\n\n    /// The 32-byte digest of everything given to `update`.\n    pub fn finish(self: *mut Self) -> String {\n        let bits = self.total *% 8\n        var tail = self.pending.clone()\n        tail.push_byte(0x80)\n        while tail.len % 64 != 56 { tail.push_byte(0) }\n        var i: u64 = 8\n        while i > 0 {\n            i -= 1\n            tail.push_byte(((bits >> (i * 8)) & 255) as u8)\n        }\n        var at: usize = 0\n        while at < tail.len {\n            self.compress(tail[at..at + 64])\n            at += 64\n        }\n        var out = String.with_capacity(32)\n        for w in self.h {\n            out.push_byte(((w >> 24) & 255) as u8)\n            out.push_byte(((w >> 16) & 255) as u8)\n            out.push_byte(((w >> 8) & 255) as u8)\n            out.push_byte((w & 255) as u8)\n        }\n        return out\n    }\n\n    fn compress(self: *mut Self, block: []u8) {\n        var w: [64]u32 = undefined\n        for i in 0..16 {\n            w[i] = ((block[i * 4] as u32) << 24) | ((block[i * 4 + 1] as u32) << 16) | ((block[i * 4 + 2] as u32) << 8) | (block[i * 4 + 3] as u32)\n        }\n        for i in 16..64 {\n            let s0 = rotr32(w[i - 15], 7) ^ rotr32(w[i - 15], 18) ^ (w[i - 15] >> 3)\n            let s1 = rotr32(w[i - 2], 17) ^ rotr32(w[i - 2], 19) ^ (w[i - 2] >> 10)\n            w[i] = w[i - 16] +% s0 +% w[i - 7] +% s1\n        }\n        var a = self.h[0]\n        var b = self.h[1]\n        var c = self.h[2]\n        var d = self.h[3]\n        var e = self.h[4]\n        var f = self.h[5]\n        var g = self.h[6]\n        var h = self.h[7]\n        for i in 0..64 {\n            let big1 = rotr32(e, 6) ^ rotr32(e, 11) ^ rotr32(e, 25)\n            let choose = (e & f) ^ (~e & g)\n            let t1 = h +% big1 +% choose +% K256[i] +% w[i]\n            let big0 = rotr32(a, 2) ^ rotr32(a, 13) ^ rotr32(a, 22)\n            let majority = (a & b) ^ (a & c) ^ (b & c)\n            let t2 = big0 +% majority\n            h = g\n            g = f\n            f = e\n            e = d +% t1\n            d = c\n            c = b\n            b = a\n            a = t1 +% t2\n        }\n        self.h[0] = self.h[0] +% a\n        self.h[1] = self.h[1] +% b\n        self.h[2] = self.h[2] +% c\n        self.h[3] = self.h[3] +% d\n        self.h[4] = self.h[4] +% e\n        self.h[5] = self.h[5] +% f\n        self.h[6] = self.h[6] +% g\n        self.h[7] = self.h[7] +% h\n    }\n}\n\n/// The SHA-256 digest of `data`: 32 bytes.\npub fn sha256(data: []u8) -> String {\n    var s = Sha256.new()\n    s.update(data)\n    return s.finish()\n}\n\n/// The SHA-256 digest of `data` as 64 lower-case hex digits.\npub fn sha256_hex(data: []u8) -> String {\n    let d = sha256(data)\n    return bytes.hex(d[..])\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"FNV-1a over 64 bits\" {\n    expect(fnv1a64(\"\") == 14695981039346656037)\n    expect(fnv1a64(\"a\") == 0xaf63dc4c8601ec8c)\n    expect(fnv1a64(\"foobar\") == 0x85944171f73967e8)\n}\n\ntest \"SipHash-2-4, the reference vectors\" {\n    var key = String.new()\n    for i in 0..16 { key.push_byte(i as u8) }\n    var msg = String.new()\n    expect(siphash(key[..], msg[..]) == 0x726fdb47dd0e0e31)\n    for i in 0..15 { msg.push_byte(i as u8) }\n    expect(siphash(key[..], msg[..]) == 0xa129ca6149be45e5)\n}\n\ntest \"SHA-256, the FIPS vectors\" {\n    expect(sha256_hex(\"\") == \"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\")\n    expect(sha256_hex(\"abc\") == \"ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad\")\n    expect(sha256_hex(\"abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq\") == \"248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1\")\n}\n\ntest \"SHA-256 in pieces is SHA-256 at once\" {\n    var whole = String.new()\n    for i in 0..1000 { whole.push_byte((i % 251) as u8) }\n    var s = Sha256.new()\n    s.update(whole[0..3])\n    s.update(whole[3..70])\n    s.update(whole[70..64 * 9])\n    s.update(whole[64 * 9..])\n    let pieces = s.finish()\n    expect(pieces == sha256(whole[..]))\n    expect(pieces.len == 32)\n}\n";
static const char nx_str_892[13262] = "// std.path: paths as text, written in Nexium: joining, splitting, comparing\n// and normalizing them, without touching the file system (std.fs does that).\n//\n// `import std.path` then:\n//\n//     let cfg = path.join(path.parent(argv0), \"app.toml\")\n//     let ext = path.extension(\"notes.tar.gz\")           // \"gz\"\n//     let n = path.normalize(\"a/./b/../c\")               // \"a/c\"\n//     let r = path.relative(\"src/app\", \"src/lib/x.nx\")   // \"../lib/x.nx\"\n//     for part in path.components(\"/usr/local/bin\") { }  // \"/\", \"usr\", \"local\", \"bin\"\n//\n// Paths are byte strings. `/` and `\\` both separate components on every\n// platform, and a result uses `/` unless its input used `\\`. A path is\n// absolute when it starts at a root: `/`, `\\`, a drive (`C:\\`, `C:/`) or a\n// share (`\\\\server`). std.fs keeps its path functions, which call these.\n\n// ------------------------------------------------------------------ parts\n\nfn is_sep(c: u8) -> bool {\n    return c == '/' or c == '\\\\'\n}\n\n// the separator a path uses: `\\` when it contains one, else `/`\nfn sep_of(p: []u8) -> u8 {\n    for c in p { if c == '\\\\' { return '\\\\' } }\n    return '/'\n}\n\nfn lower(c: u8) -> u8 {\n    return if c >= 'A' and c <= 'Z' { c + 32 } else { c }\n}\n\n// the length of the root a path starts with: a drive and its separator, a\n// share's two separators, or one separator; 0 for a relative path\nfn root_len(p: []u8) -> usize {\n    if p.len >= 3 and p[1] == ':' and is_sep(p[2]) { return 3 }\n    if p.len >= 2 and is_sep(p[0]) and is_sep(p[1]) { return 2 }\n    if p.len >= 1 and is_sep(p[0]) { return 1 }\n    return 0\n}\n\n// two roots are the same when their separators and drive letters are, in\n// either spelling\nfn same_root(x: []u8, y: []u8) -> bool {\n    if x.len != y.len { return false }\n    for i in 0..x.len {\n        if !(is_sep(x[i]) and is_sep(y[i])) and lower(x[i]) != lower(y[i]) { return false }\n    }\n    return true\n}\n\n// where each component after the root starts and ends\nstruct Span {\n    start: usize\n    end: usize\n}\n\nfn spans(p: []u8) -> List(Span) {\n    var out = List(Span).new()\n    var i = root_len(p)\n    while i < p.len {\n        while i < p.len and is_sep(p[i]) { i += 1 }\n        let start = i\n        while i < p.len and !is_sep(p[i]) { i += 1 }\n        if i > start { out.append(Span{ .start = start, .end = i }) }\n    }\n    return out\n}\n\n/// The root a path starts with (`/`, `C:\\`, `\\\\`), or `` for a relative path.\npub fn root(p: []u8) -> []u8 {\n    return p[0..root_len(p)]\n}\n\n/// Does the path start at a root (`/x`, `C:\\x`, `C:/x`, `\\\\server`)?\npub fn is_absolute(p: []u8) -> bool {\n    return root_len(p) > 0\n}\n\n/// Is the path relative to some directory: not `is_absolute`?\npub fn is_relative(p: []u8) -> bool {\n    return root_len(p) == 0\n}\n\n/// The root, if any, then each component, separators left out:\n/// `/usr/local/` -> `/`, `usr`, `local`; `a/./b` -> `a`, `.`, `b`.\npub fn components(p: []u8) -> List([]u8) {\n    var out = List([]u8).new()\n    let r = root_len(p)\n    if r > 0 { out.append(p[0..r]) }\n    for s in spans(p) { out.append(p[s.start..s.end]) }\n    return out\n}\n\n// ------------------------------------------------------------------ joining\n\n/// `dir/name`; a separator is added only when needed, and an absolute `name`\n/// replaces `dir`.\npub fn join(dir: []u8, name: []u8) -> String {\n    if dir.len == 0 or is_absolute(name) { return String.from(name) }\n    var out = String.from(dir)\n    if name.len == 0 { return out }\n    if !is_sep(dir[dir.len - 1]) { out.push_byte(sep_of(dir)) }\n    out.append(name)\n    return out\n}\n\n/// Every part joined in turn, as `join` joins two: `join_all(parts[..])`.\npub fn join_all(parts: [][]u8) -> String {\n    var out = String.new()\n    for part in parts {\n        let next = join(out, part)\n        out = next\n    }\n    return out\n}\n\n// ------------------------------------------------------------------ splitting\n\n/// Everything before the last separator: `a/b/c.txt` -> `a/b`, `c.txt` -> ``,\n/// `/c.txt` -> `/`.\npub fn parent(p: []u8) -> []u8 {\n    var end = p.len\n    while end > 0 and is_sep(p[end - 1]) { end -= 1 }\n    var i = end\n    while i > 0 and !is_sep(p[i - 1]) { i -= 1 }\n    if i == 0 { return p[0..0] }\n    var j = i\n    while j > 1 and is_sep(p[j - 1]) { j -= 1 }\n    if j == 1 and is_sep(p[0]) { return p[0..1] }\n    if j >= 2 and p[j - 1] == ':' { return p[0..j + 1] }\n    return p[0..j]\n}\n\n/// The last component: `a/b/c.txt` -> `c.txt`.\npub fn base_name(p: []u8) -> []u8 {\n    var end = p.len\n    while end > 0 and is_sep(p[end - 1]) { end -= 1 }\n    var i = end\n    while i > 0 and !is_sep(p[i - 1]) { i -= 1 }\n    return p[i..end]\n}\n\n/// The extension without the dot: `a/b.tar.gz` -> `gz`, `Makefile` -> ``.\npub fn extension(p: []u8) -> []u8 {\n    let name = base_name(p)\n    var i = name.len\n    while i > 0 {\n        i -= 1\n        if name[i] == '.' {\n            if i == 0 { return name[0..0] }\n            return name[i + 1..name.len]\n        }\n    }\n    return name[0..0]\n}\n\n/// The base name without its extension: `a/b.tar.gz` -> `b.tar`.\npub fn stem(p: []u8) -> []u8 {\n    let name = base_name(p)\n    var i = name.len\n    while i > 0 {\n        i -= 1\n        if name[i] == '.' {\n            if i == 0 { return name }\n            return name[0..i]\n        }\n    }\n    return name\n}\n\n/// The path with its extension replaced (or added): `a/b.txt`, `md` -> `a/b.md`.\npub fn with_extension(p: []u8, ext: []u8) -> String {\n    let e = extension(p)\n    var out = String.from(if e.len > 0 { p[0..p.len - e.len - 1] } else { p })\n    if ext.len > 0 {\n        out.push_byte('.')\n        out.append(ext)\n    }\n    return out\n}\n\n// ------------------------------------------------------------------ comparing\n\n/// Collapse `.` and `..` components and repeated separators:\n/// `a/./b/../c//d` -> `a/c/d`. A leading `..` is kept; `..` at a root is\n/// dropped; an empty result is `.`.\npub fn normalize(p: []u8) -> String {\n    let sep = sep_of(p)\n    let r = root_len(p)\n    var parts = List([]u8).new()\n    for s in spans(p) {\n        let part = p[s.start..s.end]\n        if part == \".\" {\n            continue\n        }\n        if part == \"..\" {\n            if parts.len > 0 and parts[parts.len - 1] != \"..\" {\n                _ = parts.pop()\n            } else if r == 0 {\n                parts.append(part)\n            }\n            continue\n        }\n        parts.append(part)\n    }\n    var out = String.new()\n    for c in p[0..r] { out.push_byte(if is_sep(c) { sep } else { c }) }\n    for part, k in parts {\n        if k > 0 { out.push_byte(sep) }\n        out.append(part)\n    }\n    if out.len == 0 { out.push_byte('.') }\n    return out\n}\n\n/// What follows `prefix` in `p`, compared component by component (so `a/bc`\n/// does not start with `a/b`): `a/b/c/d`, `a/b` -> `c/d`; null when `p` does\n/// not start with `prefix`. Neither is normalized first.\npub fn strip_prefix(p: []u8, prefix: []u8) -> ?[]u8 {\n    if !same_root(p[0..root_len(p)], prefix[0..root_len(prefix)]) { return null }\n    let a = spans(p)\n    let b = spans(prefix)\n    if b.len > a.len { return null }\n    for i in 0..b.len {\n        if p[a[i].start..a[i].end] != prefix[b[i].start..b[i].end] { return null }\n    }\n    if b.len == a.len { return p[p.len..p.len] }\n    return p[a[b.len].start..p.len]\n}\n\n/// Does `p` start with `prefix`, component by component?\npub fn starts_with(p: []u8, prefix: []u8) -> bool {\n    return strip_prefix(p, prefix) != null\n}\n\n/// The path that leads from the directory `from` to `to`, both normalized:\n/// `src/app`, `src/lib/x.nx` -> `../lib/x.nx`, and `.` for the same place.\n/// Null when no such path can be written: one is absolute and the other not,\n/// their roots differ, or `from` climbs out through a `..`.\npub fn relative(from: []u8, to: []u8) -> ?String {\n    let f = normalize(from)\n    let t = normalize(to)\n    if !same_root(f[0..root_len(f)], t[0..root_len(t)]) { return null }\n    var a = List([]u8).new()\n    for s in spans(f) {\n        if f[s.start..s.end] != \".\" { a.append(f[s.start..s.end]) }\n    }\n    var b = List([]u8).new()\n    for s in spans(t) {\n        if t[s.start..s.end] != \".\" { b.append(t[s.start..s.end]) }\n    }\n    var i: usize = 0\n    while i < a.len and i < b.len and a[i] == b[i] { i += 1 }\n    let sep: u8 = if sep_of(from) == '\\\\' or sep_of(to) == '\\\\' { '\\\\' } else { '/' }\n    var out = String.new()\n    for k in i..a.len {\n        if a[k] == \"..\" { return null }\n        if out.len > 0 { out.push_byte(sep) }\n        out.append(\"..\")\n    }\n    for k in i..b.len {\n        if out.len > 0 { out.push_byte(sep) }\n        out.append(b[k])\n    }\n    if out.len == 0 { out.push_byte('.') }\n    return out\n}\n\n// ------------------------------------------------------------------ spelling\n\n/// Every `\\` as `/`.\npub fn to_slash(p: []u8) -> String {\n    var out = String.with_capacity(p.len)\n    for c in p { out.push_byte(if c == '\\\\' { '/' } else { c }) }\n    return out\n}\n\n/// The separators the platform spells paths with: `\\` on Windows, `/`\n/// elsewhere.\npub fn to_native(p: []u8) -> String {\n    if comptime @target().0 == \"windows\" {\n        var out = String.with_capacity(p.len)\n        for c in p { out.push_byte(if c == '/' { '\\\\' } else { c }) }\n        return out\n    } else {\n        return to_slash(p)\n    }\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"roots and components\" {\n    expect_eq(root(\"/usr/bin\"), \"/\")\n    expect_eq(root(\"C:\\\\x\"), \"C:\\\\\")\n    expect_eq(root(\"c:/x\"), \"c:/\")\n    expect_eq(root(\"\\\\\\\\server\\\\share\"), \"\\\\\\\\\")\n    expect_eq(root(\"a/b\"), \"\")\n    expect(is_absolute(\"/x\") and is_absolute(\"C:\\\\x\") and is_absolute(\"C:/x\") and is_absolute(\"\\\\\\\\s\\\\x\"))\n    expect(!is_absolute(\"x/y\") and !is_absolute(\"\") and !is_absolute(\"C:x\"))\n    expect(is_relative(\"x/y\"))\n    let parts = components(\"/usr//local/bin/\")\n    expect_eq(parts.len, 4)\n    expect_eq(parts[0], \"/\")\n    expect_eq(parts[1], \"usr\")\n    expect_eq(parts[3], \"bin\")\n    let rel = components(\"a/./b\")\n    expect_eq(rel.len, 3)\n    expect_eq(rel[1], \".\")\n    expect_eq(components(\"\").len, 0)\n    let drive = components(\"C:\\\\Users\\\\me\")\n    expect_eq(drive[0], \"C:\\\\\")\n    expect_eq(drive[2], \"me\")\n}\n\ntest \"joining\" {\n    expect_eq(join(\"a\", \"b\"), \"a/b\")\n    expect_eq(join(\"a/\", \"b\"), \"a/b\")\n    expect_eq(join(\"\", \"b\"), \"b\")\n    expect_eq(join(\"a\", \"\"), \"a\")\n    expect_eq(join(\"a\", \"/b\"), \"/b\")\n    expect_eq(join(\"C:\\\\x\", \"y\"), \"C:\\\\x\\\\y\")\n    let parts = [\"usr\", \"local\", \"bin\"]\n    expect_eq(join_all(parts[..]), \"usr/local/bin\")\n    let rooted = [\"/\", \"etc\", \"hosts\"]\n    expect_eq(join_all(rooted[..]), \"/etc/hosts\")\n    let none: [0][]u8 = []\n    expect_eq(join_all(none[..]), \"\")\n}\n\ntest \"splitting\" {\n    expect_eq(parent(\"a/b/c.txt\"), \"a/b\")\n    expect_eq(parent(\"c.txt\"), \"\")\n    expect_eq(parent(\"/c.txt\"), \"/\")\n    expect_eq(parent(\"a/b/\"), \"a\")\n    expect_eq(parent(\"C:\\\\x\\\\y.txt\"), \"C:\\\\x\")\n    expect_eq(parent(\"C:\\\\y.txt\"), \"C:\\\\\")\n    expect_eq(base_name(\"a/b/c.txt\"), \"c.txt\")\n    expect_eq(base_name(\"a/b/\"), \"b\")\n    expect_eq(extension(\"a/b.tar.gz\"), \"gz\")\n    expect_eq(extension(\"Makefile\"), \"\")\n    expect_eq(extension(\".bashrc\"), \"\")\n    expect_eq(stem(\"a/b.tar.gz\"), \"b.tar\")\n    expect_eq(stem(\".bashrc\"), \".bashrc\")\n    expect_eq(with_extension(\"a/b.txt\", \"md\"), \"a/b.md\")\n    expect_eq(with_extension(\"a/b\", \"md\"), \"a/b.md\")\n    expect_eq(with_extension(\"a/b.txt\", \"\"), \"a/b\")\n}\n\ntest \"normalizing\" {\n    expect_eq(normalize(\"a/./b/../c//d\"), \"a/c/d\")\n    expect_eq(normalize(\"/a/../..\"), \"/\")\n    expect_eq(normalize(\"../a\"), \"../a\")\n    expect_eq(normalize(\"../../a/..\"), \"../..\")\n    expect_eq(normalize(\"a/..\"), \".\")\n    expect_eq(normalize(\"\"), \".\")\n    expect_eq(normalize(\"C:\\\\a\\\\..\\\\b\"), \"C:\\\\b\")\n    expect_eq(normalize(\"C:/a/../b\"), \"C:/b\")\n    expect_eq(normalize(\"\\\\\\\\server\\\\share\\\\..\\\\x\"), \"\\\\\\\\server\\\\x\")\n}\n\ntest \"prefixes, component by component\" {\n    expect_eq(strip_prefix(\"a/b/c/d\", \"a/b\").?, \"c/d\")\n    expect_eq(strip_prefix(\"a/b/c\", \"a/b/\").?, \"c\")\n    expect_eq(strip_prefix(\"a/b\", \"a/b\").?, \"\")\n    expect_eq(strip_prefix(\"/x/y\", \"/\").?, \"x/y\")\n    expect_eq(strip_prefix(\"C:\\\\x\\\\y\", \"c:/x\").?, \"y\")\n    expect(strip_prefix(\"a/bc\", \"a/b\") == null)\n    expect(strip_prefix(\"a\", \"a/b\") == null)\n    expect(strip_prefix(\"/a/b\", \"a\") == null)\n    expect(strip_prefix(\"a/b\", \"/a\") == null)\n    expect(starts_with(\"src/lib/x.nx\", \"src\"))\n    expect(!starts_with(\"srcs/x.nx\", \"src\"))\n    expect(starts_with(\"x\", \"\"))\n}\n\ntest \"relative paths\" {\n    expect_eq(relative(\"src/app\", \"src/lib/x.nx\").?, \"../lib/x.nx\")\n    expect_eq(relative(\"a/b\", \"a/b\").?, \".\")\n    expect_eq(relative(\"a\", \"a/b/c\").?, \"b/c\")\n    expect_eq(relative(\"a/b/c\", \"a\").?, \"../..\")\n    expect_eq(relative(\".\", \"x\").?, \"x\")\n    expect_eq(relative(\"x\", \"../y\").?, \"../../y\")\n    expect_eq(relative(\"/usr/local\", \"/usr/bin/nx\").?, \"../bin/nx\")\n    expect_eq(relative(\"C:\\\\a\\\\b\", \"c:\\\\a\\\\c\").?, \"..\\\\c\")\n    expect(relative(\"../x\", \"y\") == null)\n    expect(relative(\"/a\", \"b\") == null)\n    expect(relative(\"C:\\\\a\", \"D:\\\\a\") == null)\n}\n\ntest \"spelling\" {\n    expect_eq(to_slash(\"a\\\\b/c\"), \"a/b/c\")\n    let native = to_native(\"a/b\\\\c\")\n    if comptime @target().0 == \"windows\" {\n        expect_eq(native, \"a\\\\b\\\\c\")\n    } else {\n        expect_eq(native, \"a/b/c\")\n    }\n}\n";
static const char nx_str_893[12207] = "// std.env: the environment, and where a program keeps its files, written in\n// Nexium: variables, the home directory, the config, data, cache and state\n// directories each platform expects (XDG on Linux and the BSDs, Library on\n// macOS, AppData on Windows), and `.env` files.\n//\n// `import std.env` then:\n//\n//     let port = env.get_or(\"PORT\", \"8080\")\n//     let dir = env.config_dir(\"myapp\")              // ?String: ~/.config/myapp, ...\n//     let notes = env.expand_home(\"~/notes.txt\")\n//     let n = env.load_dotenv(\".env\", false) catch 0 // sets what is not set yet\n//\n// The directories are where a program should keep its files; nothing here\n// creates them (`fs.make_dirs` does). Each is null when the variables it\n// comes from are not set.\n\nimport std.fs\nimport std.path\n\n/// A variable: its name and value.\npub struct Var {\n    name: String\n    value: String\n}\n\n// ------------------------------------------------------------------ variables\n\n/// The variable's value, or null when it is not set or set to nothing.\npub fn get(name: []u8) -> ?String {\n    let v = os.env(name) orelse return null\n    if v.len == 0 { return null }\n    return String.from(v)\n}\n\n/// The variable's value, or `default` when it is not set or set to nothing.\npub fn get_or(name: []u8, default: []u8) -> String {\n    return get(name) orelse String.from(default)\n}\n\n/// Set a variable for this program and the ones it starts.\npub fn set(name: []u8, value: []u8) {\n    os.set_env(name, value)\n}\n\n/// Remove a variable.\npub fn unset(name: []u8) {\n    os.set_env(name, \"\")\n}\n\n/// Every variable, sorted by name.\npub fn all() -> List(Var) {\n    var out = List(Var).new()\n    for entry in os.environ() {\n        let eq = entry[..].find(\"=\") orelse continue\n        // Windows keeps a few hidden `=C:=C:\\...` entries: no name\n        if eq == 0 { continue }\n        out.append(Var{ .name = String.from(entry[0..eq]), .value = String.from(entry[eq + 1..entry.len]) })\n    }\n    var i: usize = 1\n    while i < out.len {\n        var j = i\n        while j > 0 and out[j].name[..] < out[j - 1].name[..] {\n            out.swap(j, j - 1)\n            j -= 1\n        }\n        i += 1\n    }\n    return out\n}\n\n// ------------------------------------------------------------------ directories\n\n/// The user's home directory: `HOME`, or on Windows `USERPROFILE`.\npub fn home() -> ?String {\n    return home_on(@target().0)\n}\n\n/// `~` or `~/...` at the start of a path, with the home directory in its\n/// place; any other path as it is.\npub fn expand_home(p: []u8) -> String {\n    if p.len == 0 or p[0] != '~' or (p.len > 1 and p[1] != '/' and p[1] != '\\\\') { return String.from(p) }\n    let h = home() orelse return String.from(p)\n    if p.len <= 2 { return h }\n    return path.join(h[..], p[2..p.len])\n}\n\n/// Where a program keeps its settings, in a directory named `app` (none when\n/// `app` is empty): `$XDG_CONFIG_HOME` or `~/.config` on Linux and the BSDs,\n/// `~/Library/Application Support` on macOS, `%APPDATA%` on Windows.\npub fn config_dir(app: []u8) -> ?String {\n    return dir_on(@target().0, KIND_CONFIG, app)\n}\n\n/// Where a program keeps what it makes and needs to keep:\n/// `$XDG_DATA_HOME` or `~/.local/share`, `~/Library/Application Support`,\n/// `%APPDATA%`.\npub fn data_dir(app: []u8) -> ?String {\n    return dir_on(@target().0, KIND_DATA, app)\n}\n\n/// Where a program keeps what it can make again: `$XDG_CACHE_HOME` or\n/// `~/.cache`, `~/Library/Caches`, `%LOCALAPPDATA%`.\npub fn cache_dir(app: []u8) -> ?String {\n    return dir_on(@target().0, KIND_CACHE, app)\n}\n\n/// Where a program keeps its state between runs (logs, history, what was\n/// open): `$XDG_STATE_HOME` or `~/.local/state`,\n/// `~/Library/Application Support`, `%LOCALAPPDATA%`.\npub fn state_dir(app: []u8) -> ?String {\n    return dir_on(@target().0, KIND_STATE, app)\n}\n\nconst KIND_CONFIG: usize = 0\nconst KIND_DATA: usize = 1\nconst KIND_CACHE: usize = 2\nconst KIND_STATE: usize = 3\n\nfn home_on(os_name: []u8) -> ?String {\n    if os_name == \"windows\" {\n        if let p = get(\"USERPROFILE\") { return p }\n    }\n    return get(\"HOME\")\n}\n\n// an XDG variable counts only when it holds an absolute path (the XDG base\n// directory specification ignores a relative one)\nfn xdg(name: []u8) -> ?String {\n    let v = get(name) orelse return null\n    if !path.is_absolute(v[..]) { return null }\n    return v\n}\n\nfn with_app(base: []u8, app: []u8) -> String {\n    if app.len == 0 { return String.from(base) }\n    return path.join(base, app)\n}\n\n// the platform's directory of each kind, by the platform's name, so the\n// tests reach every platform's rule on any machine\nfn dir_on(os_name: []u8, kind: usize, app: []u8) -> ?String {\n    if os_name == \"windows\" {\n        let name = if kind == KIND_CONFIG or kind == KIND_DATA { \"APPDATA\" } else { \"LOCALAPPDATA\" }\n        let base = get(name) orelse return null\n        return with_app(base[..], app)\n    }\n    if os_name == \"macos\" {\n        let h = home_on(os_name) orelse return null\n        let sub = if kind == KIND_CACHE { \"Library/Caches\" } else { \"Library/Application Support\" }\n        let base = path.join(h[..], sub)\n        return with_app(base[..], app)\n    }\n    let names = [\"XDG_CONFIG_HOME\", \"XDG_DATA_HOME\", \"XDG_CACHE_HOME\", \"XDG_STATE_HOME\"]\n    let defaults = [\".config\", \".local/share\", \".cache\", \".local/state\"]\n    if let v = xdg(names[kind]) { return with_app(v[..], app) }\n    let h = home_on(os_name) orelse return null\n    let base = path.join(h[..], defaults[kind])\n    return with_app(base[..], app)\n}\n\n// ------------------------------------------------------------------ .env files\n\n/// The variables a `.env` file sets, in order: `NAME=value` lines, an\n/// optional `export ` before the name, `#` comments and blank lines skipped,\n/// a value in single quotes taken as written, one in double quotes with\n/// `\\n`, `\\t`, `\\\"` and `\\\\` read as escapes, and an unquoted value trimmed\n/// and cut at ` #`. A line that is none of these is an error.\npub fn parse_dotenv(text: []u8) -> !List(Var) {\n    var out = List(Var).new()\n    for raw in text.lines() {\n        var line = raw.trim()\n        if line.len == 0 or line[0] == '#' { continue }\n        if line.starts_with(\"export \") { line = line[7..line.len].trim() }\n        let eq = line.find(\"=\") orelse return error.InvalidInput\n        let name = line[0..eq].trim()\n        if name.len == 0 { return error.InvalidInput }\n        for c in name {\n            let ok = (c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z') or (c >= '0' and c <= '9') or c == '_' or c == '.'\n            if !ok { return error.InvalidInput }\n        }\n        let rest = line[eq + 1..line.len].trim()\n        var value = String.new()\n        if rest.len > 0 and (rest[0] == '\"' or rest[0] == '\\'') {\n            let q = rest[0]\n            var i: usize = 1\n            var closed = false\n            while i < rest.len {\n                let c = rest[i]\n                if c == q {\n                    closed = true\n                    break\n                }\n                if q == '\"' and c == '\\\\' and i + 1 < rest.len {\n                    let e = rest[i + 1]\n                    value.push_byte(if e == 'n' { '\\n' } else if e == 't' { '\\t' } else if e == 'r' { '\\r' } else { e })\n                    i += 2\n                    continue\n                }\n                value.push_byte(c)\n                i += 1\n            }\n            if !closed { return error.InvalidInput }\n            let after = rest[i + 1..rest.len].trim()\n            if after.len > 0 and after[0] != '#' { return error.InvalidInput }\n        } else {\n            var end = rest.len\n            if let hash = rest.find(\" #\") { end = hash }\n            value.append(rest[0..end].trim())\n        }\n        out.append(Var{ .name = String.from(name), .value = value })\n    }\n    return out\n}\n\n/// Read a `.env` file and set its variables: those not set already, or\n/// every one when `override`. How many were set; `error.InvalidInput` when\n/// a line does not parse (nothing is set then).\npub fn load_dotenv(file: []u8, override: bool) -> !usize {\n    let text = try fs.read(file)\n    let vars = try parse_dotenv(text[..])\n    var n: usize = 0\n    for v in vars {\n        if !override and get(v.name[..]) != null { continue }\n        set(v.name[..], v.value[..])\n        n += 1\n    }\n    return n\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"variables\" {\n    set(\"NX_ENV_TEST_A\", \"one\")\n    expect_eq(get(\"NX_ENV_TEST_A\").?, \"one\")\n    expect_eq(get_or(\"NX_ENV_TEST_A\", \"two\"), \"one\")\n    unset(\"NX_ENV_TEST_A\")\n    expect(get(\"NX_ENV_TEST_A\") == null)\n    expect_eq(get_or(\"NX_ENV_TEST_A\", \"two\"), \"two\")\n    set(\"NX_ENV_TEST_B\", \"b\")\n    var found = false\n    var sorted = true\n    let every = all()\n    for v, i in every {\n        if v.name[..] == \"NX_ENV_TEST_B\" and v.value[..] == \"b\" { found = true }\n        if i > 0 and every[i].name[..] < every[i - 1].name[..] { sorted = false }\n    }\n    expect(found and sorted)\n    unset(\"NX_ENV_TEST_B\")\n}\n\ntest \"each platform's directories\" {\n    let keep = [\"HOME\", \"USERPROFILE\", \"APPDATA\", \"LOCALAPPDATA\", \"XDG_CONFIG_HOME\", \"XDG_DATA_HOME\", \"XDG_CACHE_HOME\", \"XDG_STATE_HOME\"]\n    var saved = List(String).new()\n    for name in keep { saved.append(get_or(name, \"\")) }\n\n    set(\"HOME\", \"/home/me\")\n    unset(\"XDG_CONFIG_HOME\")\n    set(\"XDG_CACHE_HOME\", \"relative/is/ignored\")\n    set(\"XDG_DATA_HOME\", \"/data\")\n    expect_eq(dir_on(\"linux\", KIND_CONFIG, \"app\").?, \"/home/me/.config/app\")\n    expect_eq(dir_on(\"linux\", KIND_DATA, \"app\").?, \"/data/app\")\n    expect_eq(dir_on(\"linux\", KIND_CACHE, \"\").?, \"/home/me/.cache\")\n    expect_eq(dir_on(\"bsd\", KIND_STATE, \"app\").?, \"/home/me/.local/state/app\")\n\n    set(\"HOME\", \"/Users/me\")\n    expect_eq(dir_on(\"macos\", KIND_CONFIG, \"app\").?, \"/Users/me/Library/Application Support/app\")\n    expect_eq(dir_on(\"macos\", KIND_CACHE, \"app\").?, \"/Users/me/Library/Caches/app\")\n\n    set(\"USERPROFILE\", \"C:\\\\Users\\\\me\")\n    set(\"APPDATA\", \"C:\\\\Users\\\\me\\\\AppData\\\\Roaming\")\n    set(\"LOCALAPPDATA\", \"C:\\\\Users\\\\me\\\\AppData\\\\Local\")\n    expect_eq(home_on(\"windows\").?, \"C:\\\\Users\\\\me\")\n    expect_eq(dir_on(\"windows\", KIND_CONFIG, \"app\").?, \"C:\\\\Users\\\\me\\\\AppData\\\\Roaming\\\\app\")\n    expect_eq(dir_on(\"windows\", KIND_CACHE, \"app\").?, \"C:\\\\Users\\\\me\\\\AppData\\\\Local\\\\app\")\n    unset(\"LOCALAPPDATA\")\n    expect(dir_on(\"windows\", KIND_STATE, \"app\") == null)\n\n    unset(\"HOME\")\n    expect(dir_on(\"linux\", KIND_CONFIG, \"app\") == null)\n\n    for name, i in keep { set(name, saved[i][..]) }\n}\n\ntest \"the home directory in a path\" {\n    let h = home()\n    expect_eq(expand_home(\"notes.txt\"), \"notes.txt\")\n    expect_eq(expand_home(\"~user/x\"), \"~user/x\")\n    if let hh = h {\n        expect_eq(expand_home(\"~\"), hh)\n        expect_eq(expand_home(\"~/notes.txt\"), path.join(hh[..], \"notes.txt\"))\n    }\n}\n\ntest \".env files\" {\n    let text = \"# settings\\nexport PORT=8080\\nNAME = \\\"a \\\\\\\"quoted\\\\\\\" name\\\"\\nRAW='$not $expanded'\\nPLAIN=value with spaces # a comment\\nEMPTY=\\n\\nURL=http://x.test/#frag\\n\"\n    let vars = try parse_dotenv(text)\n    expect_eq(vars.len, 6)\n    expect_eq(vars[0].name, \"PORT\")\n    expect_eq(vars[0].value, \"8080\")\n    expect_eq(vars[1].value, \"a \\\"quoted\\\" name\")\n    expect_eq(vars[2].value, \"$not $expanded\")\n    expect_eq(vars[3].value, \"value with spaces\")\n    expect_eq(vars[4].value, \"\")\n    expect_eq(vars[5].value, \"http://x.test/#frag\")\n    var bad = false\n    _ = parse_dotenv(\"NO_EQUALS_SIGN\\n\") catch |e| {\n        bad = e == error.InvalidInput\n        List(Var).new()\n    }\n    expect(bad)\n    var unclosed = false\n    _ = parse_dotenv(\"X=\\\"open\\n\") catch |e| {\n        unclosed = e == error.InvalidInput\n        List(Var).new()\n    }\n    expect(unclosed)\n\n    let file = fs.temp_path(\"nx-dotenv-\")\n    try fs.write(file[..], \"NX_DOTENV_A=from-file\\nNX_DOTENV_B=from-file\\n\")\n    set(\"NX_DOTENV_A\", \"already\")\n    expect_eq(try load_dotenv(file[..], false), 1)\n    expect_eq(get(\"NX_DOTENV_A\").?, \"already\")\n    expect_eq(get(\"NX_DOTENV_B\").?, \"from-file\")\n    expect_eq(try load_dotenv(file[..], true), 2)\n    expect_eq(get(\"NX_DOTENV_A\").?, \"from-file\")\n    unset(\"NX_DOTENV_A\")\n    unset(\"NX_DOTENV_B\")\n    try fs.remove(file[..])\n}\n";
static const char nx_str_894[5] = "uuid";
static const char nx_str_895[6391] = "// std.uuid: UUIDs (RFC 9562), written in Nexium: random ones (version 4),\n// ones that sort by the time they were made (version 7), and their text.\n//\n// `import std.uuid` then:\n//\n//     let id = try uuid.v4()                        // 122 random bits\n//     println(\"{}\", .{id.text()})                    // \"9f1c2e7a-4b3d-4e8f-a1b2-c3d4e5f60718\"\n//     let row = try uuid.v7()                       // the time first: sorts by creation\n//     let back = uuid.parse(text) orelse return error.BadId\n//\n// The random bits come from `random.secure`, the operating system's\n// generator, so an id cannot be guessed from the ones before it; `v4` and\n// `v7` fail only where the system has no generator (`IoError`).\n\n/// A UUID: 16 bytes, most significant first.\npub struct Uuid {\n    bytes: [16]u8\n}\n\nconst HEX: []u8 = \"0123456789abcdef\"\n\nimpl Uuid {\n    /// The canonical text: 32 lowercase hex digits in groups of 8, 4, 4, 4\n    /// and 12, joined by hyphens.\n    pub fn text(self: *Self) -> String {\n        var out = String.with_capacity(36)\n        for b, i in self.bytes {\n            if i == 4 or i == 6 or i == 8 or i == 10 { out.push_byte('-') }\n            out.push_byte(HEX[(b >> 4) as usize])\n            out.push_byte(HEX[(b & 15) as usize])\n        }\n        return out\n    }\n\n    /// The version: 4 for random, 7 for time-ordered, 0 for the nil UUID.\n    pub fn version(self: *Self) -> u8 {\n        return self.bytes[6] >> 4\n    }\n\n    /// Is every bit zero?\n    pub fn is_nil(self: *Self) -> bool {\n        for b in self.bytes { if b != 0 { return false } }\n        return true\n    }\n\n    /// When a version 7 UUID was made, in milliseconds since the epoch; null\n    /// for any other version.\n    pub fn time_ms(self: *Self) -> ?i64 {\n        if self.version() != 7 { return null }\n        var ms: i64 = 0\n        for i in 0..6 { ms = (ms << 8) | (self.bytes[i] as i64) }\n        return ms\n    }\n\n    /// Is it the same UUID?\n    pub fn eq(self: *Self, other: *Uuid) -> bool {\n        for i in 0..16 { if self.bytes[i] != other.bytes[i] { return false } }\n        return true\n    }\n}\n\n// the version in the top four bits of byte 6, the RFC 4122 variant (10) in\n// the top two of byte 8\nfn stamp(b: *mut[16]u8, version: u8) {\n    b.*[6] = (b.*[6] & 15) | (version << 4)\n    b.*[8] = (b.*[8] & 63) | 128\n}\n\n/// A random UUID (version 4).\npub fn v4() -> !Uuid {\n    var b: [16]u8 = undefined\n    try random.secure(b[..])\n    stamp(&mut b, 4)\n    return Uuid{ .bytes = b }\n}\n\n/// A UUID that begins with the time it was made (version 7): 48 bits of\n/// milliseconds since the epoch, then 74 random bits, so ids made later sort\n/// after earlier ones, as text and as bytes, to the millisecond.\npub fn v7() -> !Uuid {\n    return v7_at(time.now())\n}\n\nfn v7_at(ms: i64) -> !Uuid {\n    var b: [16]u8 = undefined\n    try random.secure(b[..])\n    var t = ms\n    var i: usize = 6\n    while i > 0 {\n        i -= 1\n        b[i] = @truncate(u8, t & 255)\n        t = t >> 8\n    }\n    stamp(&mut b, 7)\n    return Uuid{ .bytes = b }\n}\n\n/// The nil UUID, every bit zero.\npub fn nil() -> Uuid {\n    var b: [16]u8 = undefined\n    for i in 0..16 { b[i] = 0 }\n    return Uuid{ .bytes = b }\n}\n\n/// The max UUID, every bit one.\npub fn max() -> Uuid {\n    var b: [16]u8 = undefined\n    for i in 0..16 { b[i] = 255 }\n    return Uuid{ .bytes = b }\n}\n\n/// A UUID from its 16 bytes; null for any other length.\npub fn from_bytes(data: []u8) -> ?Uuid {\n    if data.len != 16 { return null }\n    var b: [16]u8 = undefined\n    for i in 0..16 { b[i] = data[i] }\n    return Uuid{ .bytes = b }\n}\n\nfn hex_value(c: u8) -> ?u8 {\n    if c >= '0' and c <= '9' { return c - '0' }\n    if c >= 'a' and c <= 'f' { return c - 'a' + 10 }\n    if c >= 'A' and c <= 'F' { return c - 'A' + 10 }\n    return null\n}\n\n/// A UUID from its text: the canonical form with hyphens, in either case,\n/// or the 32 hex digits alone, either one also in braces or after\n/// `urn:uuid:`. Null for anything else.\npub fn parse(text: []u8) -> ?Uuid {\n    var s = text\n    if s.len > 9 and s[0..9].eq_ignore_case(\"urn:uuid:\") { s = s[9..s.len] }\n    else if s.len >= 2 and s[0] == '{' and s[s.len - 1] == '}' { s = s[1..s.len - 1] }\n    let hyphens = s.len == 36\n    if !hyphens and s.len != 32 { return null }\n    var b: [16]u8 = undefined\n    var n: usize = 0\n    var i: usize = 0\n    while i < s.len {\n        if hyphens and (i == 8 or i == 13 or i == 18 or i == 23) {\n            if s[i] != '-' { return null }\n            i += 1\n            continue\n        }\n        let hi = hex_value(s[i]) orelse return null\n        let lo = hex_value(s[i + 1]) orelse return null\n        b[n] = (hi << 4) | lo\n        n += 1\n        i += 2\n    }\n    return Uuid{ .bytes = b }\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"version 4: random, stamped, and not twice the same\" {\n    let a = try v4()\n    let b = try v4()\n    expect_eq(a.version(), 4)\n    expect_eq(a.bytes[8] >> 6, 2)\n    expect(!a.eq(&b))\n    let text = a.text()\n    expect_eq(text.len, 36)\n    expect_eq(text[14], '4')\n    expect(parse(text[..]).?.eq(&a))\n}\n\ntest \"version 7: the time first, so later ids sort after\" {\n    let early = try v7_at(1700000000000)\n    let late = try v7_at(1700000000001)\n    expect_eq(early.version(), 7)\n    expect_eq(early.time_ms().?, 1700000000000)\n    expect(early.text()[..] < late.text()[..])\n    expect_eq(early.text()[0..13], \"018bcfe5-6800\")\n    let now = try v7()\n    expect(now.time_ms().? > 1700000000000)\n    expect((try v4()).time_ms() == null)\n}\n\ntest \"text in and out\" {\n    let t = \"9F1C2E7A-4B3D-4E8F-A1B2-C3D4E5F60718\"\n    let id = parse(t).?\n    expect_eq(id.text(), \"9f1c2e7a-4b3d-4e8f-a1b2-c3d4e5f60718\")\n    expect(parse(\"{9f1c2e7a-4b3d-4e8f-a1b2-c3d4e5f60718}\").?.eq(&id))\n    expect(parse(\"urn:uuid:9f1c2e7a-4b3d-4e8f-a1b2-c3d4e5f60718\").?.eq(&id))\n    expect(parse(\"9f1c2e7a4b3d4e8fa1b2c3d4e5f60718\").?.eq(&id))\n    expect(parse(\"9f1c2e7a-4b3d-4e8f-a1b2-c3d4e5f6071\") == null)\n    expect(parse(\"9f1c2e7a+4b3d-4e8f-a1b2-c3d4e5f60718\") == null)\n    expect(parse(\"9f1c2e7a-4b3d-4e8f-a1b2-c3d4e5f6071g\") == null)\n    expect(parse(\"\") == null)\n    expect_eq(nil().text(), \"00000000-0000-0000-0000-000000000000\")\n    expect(nil().is_nil())\n    expect_eq(max().text(), \"ffffffff-ffff-ffff-ffff-ffffffffffff\")\n    expect(from_bytes(id.bytes[..]).?.eq(&id))\n    expect(from_bytes(\"short\") == null)\n}\n";
static const char nx_str_896[4] = "log";
static const char nx_str_897[10294] = "// std.log: leveled, structured logging, written in Nexium: a message and\n// named fields, as a line of text a person reads or a line of JSON a\n// machine reads, on stderr.\n//\n// `import std.log` then:\n//\n//     var l = log.Logger.new(log.Level.Info)\n//     l.info(\"listening\", [log.int(\"port\", 8080), log.str(\"host\", host)][..])\n//     l.warn(\"slow answer\", [log.float(\"seconds\", 2.5)][..])\n//     l.debug(\"not shown: below the logger's level\", [])\n//\n//     var j = log.Logger.json(log.Level.Debug)      // one JSON object a line\n//     let level = log.parse_level(env.get_or(\"LOG\", \"info\")) orelse log.Level.Info\n//     var request = l.with([log.str(\"id\", id)][..]) // every line carries the id\n//\n// A text line is `2026-09-25T18:04:05.120Z INFO listening port=8080\n// host=0.0.0.0`, a value with a space, `=` or a quote in quotes; a JSON line\n// is `{\"time\":\"2026-09-25T18:04:05.120Z\",\"level\":\"info\",\"msg\":\"listening\",\n// \"port\":8080,\"host\":\"0.0.0.0\"}`.\n\nimport std.json\nimport std.time\n\n/// How much a line matters; a logger writes its level and those above.\npub enum Level {\n    Debug,\n    Info,\n    Warn,\n    Error,\n}\n\n/// The level named by `debug`, `info`, `warn` (or `warning`) or `error`, in\n/// any case; null for anything else.\npub fn parse_level(text: []u8) -> ?Level {\n    if text.eq_ignore_case(\"debug\") { return Level.Debug }\n    if text.eq_ignore_case(\"info\") { return Level.Info }\n    if text.eq_ignore_case(\"warn\") or text.eq_ignore_case(\"warning\") { return Level.Warn }\n    if text.eq_ignore_case(\"error\") { return Level.Error }\n    return null\n}\n\nfn rank(l: Level) -> u8 {\n    return match l {\n        .Debug => 0,\n        .Info => 1,\n        .Warn => 2,\n        .Error => 3,\n    }\n}\n\nfn level_name(l: Level) -> []u8 {\n    return match l {\n        .Debug => \"debug\",\n        .Info => \"info\",\n        .Warn => \"warn\",\n        .Error => \"error\",\n    }\n}\n\n/// A named value on a line.\npub struct Field {\n    key: String\n    value: String\n    /// written as text (quoted in JSON) rather than a number or a boolean\n    quoted: bool\n}\n\n/// A text field.\npub fn str(key: []u8, value: []u8) -> Field {\n    return Field{ .key = String.from(key), .value = String.from(value), .quoted = true }\n}\n\n/// A whole-number field.\npub fn int(key: []u8, value: i64) -> Field {\n    return Field{ .key = String.from(key), .value = format(\"{}\", .{value}), .quoted = false }\n}\n\n/// A floating-point field; a value JSON cannot hold (NaN, the infinities) is\n/// written as text.\npub fn float(key: []u8, value: f64) -> Field {\n    let finite = value == value and value - value == 0.0\n    return Field{ .key = String.from(key), .value = format(\"{}\", .{value}), .quoted = !finite }\n}\n\n/// A true-or-false field.\npub fn flag(key: []u8, value: bool) -> Field {\n    return Field{ .key = String.from(key), .value = String.from(if value { \"true\" } else { \"false\" }), .quoted = false }\n}\n\n/// Where lines go and what they look like.\npub struct Logger {\n    level: Level\n    json: bool\n    /// whether a line starts with the time (UTC, to the millisecond)\n    timestamps: bool\n    /// the fields every line carries, before its own\n    fields: List(Field)\n    /// whether lines are kept in `kept` instead of written to stderr\n    keep: bool\n    kept: List(String)\n}\n\nimpl Logger {\n    /// Text lines on stderr, from `level` up.\n    pub fn new(level: Level) -> Logger {\n        return Logger{ .level = level, .json = false, .timestamps = true, .fields = List(Field).new(), .keep = false, .kept = List(String).new() }\n    }\n\n    /// JSON lines on stderr, from `level` up.\n    pub fn json(level: Level) -> Logger {\n        var l = Logger.new(level)\n        l.json = true\n        return l\n    }\n\n    /// A logger that keeps its lines in `kept` rather than writing them:\n    /// for tests of what a program logs.\n    pub fn keeping(level: Level, json: bool) -> Logger {\n        var l = Logger.new(level)\n        l.json = json\n        l.timestamps = false\n        l.keep = true\n        return l\n    }\n\n    /// A logger like this one whose lines carry `fields` too.\n    pub fn with(self: *Self, fields: []Field) -> Logger {\n        var l = Logger{ .level = self.level, .json = self.json, .timestamps = self.timestamps, .fields = List(Field).new(), .keep = self.keep, .kept = List(String).new() }\n        for f in self.fields { l.fields.append(Field{ .key = f.key.clone(), .value = f.value.clone(), .quoted = f.quoted }) }\n        for f in fields { l.fields.append(Field{ .key = f.key.clone(), .value = f.value.clone(), .quoted = f.quoted }) }\n        return l\n    }\n\n    /// Does this logger write lines of `level`?\n    pub fn enabled(self: *Self, level: Level) -> bool {\n        return rank(level) >= rank(self.level)\n    }\n\n    /// A line at `level`, if the logger writes that level.\n    pub fn log(self: *mut Self, level: Level, msg: []u8, fields: []Field) {\n        if !self.enabled(level) { return }\n        let line = if self.json { self.json_line(level, msg, fields) } else { self.text_line(level, msg, fields) }\n        if self.keep {\n            self.kept.append(line)\n        } else {\n            eprintln(\"{}\", .{line})\n        }\n    }\n\n    pub fn debug(self: *mut Self, msg: []u8, fields: []Field) { self.log(Level.Debug, msg, fields) }\n    pub fn info(self: *mut Self, msg: []u8, fields: []Field) { self.log(Level.Info, msg, fields) }\n    pub fn warn(self: *mut Self, msg: []u8, fields: []Field) { self.log(Level.Warn, msg, fields) }\n    /// A line at `Level.Error` (`error` itself is a keyword).\n    pub fn err(self: *mut Self, msg: []u8, fields: []Field) { self.log(Level.Error, msg, fields) }\n\n    fn text_line(self: *Self, level: Level, msg: []u8, fields: []Field) -> String {\n        var out = String.new()\n        if self.timestamps {\n            out.append(time.now_utc().iso())\n            out.push_byte(' ')\n        }\n        let name = level_name(level)\n        for c in name { out.push_byte(if c >= 'a' and c <= 'z' { c - 32 } else { c }) }\n        out.push_byte(' ')\n        out.append(msg)\n        for f in self.fields { text_field(&mut out, &f) }\n        for f in fields { text_field(&mut out, &f) }\n        return out\n    }\n\n    fn json_line(self: *Self, level: Level, msg: []u8, fields: []Field) -> String {\n        var out = String.from(\"{\")\n        if self.timestamps {\n            out.append(\"\\\"time\\\":\")\n            out.append(quote(time.now_utc().iso()[..]))\n            out.push_byte(',')\n        }\n        out.append(\"\\\"level\\\":\")\n        out.append(quote(level_name(level)))\n        out.append(\",\\\"msg\\\":\")\n        out.append(quote(msg))\n        for f in self.fields { json_field(&mut out, &f) }\n        for f in fields { json_field(&mut out, &f) }\n        out.push_byte('}')\n        return out\n    }\n}\n\n// a JSON string: `\"` and `\\` escaped, control characters as `\\n`, `\\t`,\n// `\\r` or `\\u00XX`\nfn quote(s: []u8) -> String {\n    var out = String.with_capacity(s.len + 2)\n    out.push_byte('\"')\n    for c in s {\n        if c == '\"' or c == '\\\\' {\n            out.push_byte('\\\\')\n            out.push_byte(c)\n        } else if c == '\\n' {\n            out.append(\"\\\\n\")\n        } else if c == '\\t' {\n            out.append(\"\\\\t\")\n        } else if c == '\\r' {\n            out.append(\"\\\\r\")\n        } else if c < 32 {\n            out.append(\"\\\\u00\")\n            out.push_byte(\"0123456789abcdef\"[(c >> 4) as usize])\n            out.push_byte(\"0123456789abcdef\"[(c & 15) as usize])\n        } else {\n            out.push_byte(c)\n        }\n    }\n    out.push_byte('\"')\n    return out\n}\n\n// `key=value`, the value in quotes when it has a space, `=`, a quote or\n// nothing at all\nfn text_field(out: *mut String, f: *Field) {\n    out.push_byte(' ')\n    out.append(f.key)\n    out.push_byte('=')\n    var plain = f.value.len > 0\n    for c in f.value {\n        if c <= ' ' or c == '=' or c == '\"' { plain = false }\n    }\n    if plain {\n        out.append(f.value)\n        return\n    }\n    out.push_byte('\"')\n    for c in f.value {\n        if c == '\"' or c == '\\\\' { out.push_byte('\\\\') }\n        if c == '\\n' {\n            out.append(\"\\\\n\")\n            continue\n        }\n        out.push_byte(c)\n    }\n    out.push_byte('\"')\n}\n\nfn json_field(out: *mut String, f: *Field) {\n    out.push_byte(',')\n    out.append(quote(f.key[..]))\n    out.push_byte(':')\n    if f.quoted { out.append(quote(f.value[..])) } else { out.append(f.value) }\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"levels\" {\n    expect(parse_level(\"DEBUG\").? == Level.Debug)\n    expect(parse_level(\"warning\").? == Level.Warn)\n    expect(parse_level(\"Error\").? == Level.Error)\n    expect(parse_level(\"loud\") == null)\n    var l = Logger.keeping(Level.Warn, false)\n    l.debug(\"no\", [])\n    l.info(\"no\", [])\n    l.warn(\"yes\", [])\n    l.err(\"yes too\", [])\n    expect_eq(l.kept.len, 2)\n    expect_eq(l.kept[0], \"WARN yes\")\n    expect_eq(l.kept[1], \"ERROR yes too\")\n    expect(l.enabled(Level.Error) and !l.enabled(Level.Info))\n}\n\ntest \"text lines\" {\n    var l = Logger.keeping(Level.Debug, false)\n    l.info(\"listening\", [int(\"port\", 8080), str(\"host\", \"0.0.0.0\"), flag(\"tls\", true)][..])\n    l.info(\"asked\", [str(\"path\", \"/a b\"), str(\"q\", \"x=\\\"1\\\"\"), str(\"empty\", \"\")][..])\n    expect_eq(l.kept[0], \"INFO listening port=8080 host=0.0.0.0 tls=true\")\n    expect_eq(l.kept[1], \"INFO asked path=\\\"/a b\\\" q=\\\"x=\\\\\\\"1\\\\\\\"\\\" empty=\\\"\\\"\")\n}\n\ntest \"JSON lines, and fields every line carries\" {\n    var l = Logger.keeping(Level.Info, true)\n    var r = l.with([str(\"id\", \"r-7\")][..])\n    r.warn(\"slow\", [float(\"seconds\", 2.5), int(\"tries\", -1)][..])\n    expect_eq(r.kept[0], \"{\\\"level\\\":\\\"warn\\\",\\\"msg\\\":\\\"slow\\\",\\\"id\\\":\\\"r-7\\\",\\\"seconds\\\":2.5,\\\"tries\\\":-1}\")\n    let parsed = json.parse(r.kept[0][..]) catch {\n        panic(\"a JSON line did not parse\")\n    }\n    _ = parsed\n    r.info(\"quote \\\"this\\\"\\n\", [float(\"bad\", math.NAN)][..])\n    expect(r.kept[1][..].find(\"\\\"msg\\\":\\\"quote \\\\\\\"this\\\\\\\"\\\\n\\\"\") != null)\n    expect(r.kept[1][..].find(\"\\\"bad\\\":\\\"nan\\\"\") != null or r.kept[1][..].find(\"\\\"bad\\\":\\\"NaN\\\"\") != null)\n}\n\ntest \"timestamps come first, in UTC\" {\n    var l = Logger.keeping(Level.Info, false)\n    l.timestamps = true\n    l.info(\"tick\", [])\n    let line = l.kept[0].clone()\n    expect(line[..].ends_with(\"Z INFO tick\"))\n    expect(time.parse_iso(line[0..line[..].find(\" \").?]) != null)\n}\n";
static const char nx_str_898[4] = "csv";
static const char nx_str_899[7591] = "// std.csv: comma-separated values (RFC 4180), written in Nexium: reading\n// rows, reading rows by their header, and writing rows.\n//\n// `import std.csv` then:\n//\n//     let rows = try csv.parse(text)                      // List(List(String))\n//     for row in try csv.by_header(text) {                // Map(String, String)\n//         let name = row[\"name\"] orelse \"?\"\n//     }\n//     let tsv = try csv.parse_with(text, '\\t')\n//     let out = csv.to_text(&rows)                         // quoted where needed, CRLF\n//\n// A field in double quotes may hold the separator, line breaks and `\"\"` for\n// a quote. A quote inside an unquoted field, anything but the separator or\n// a line end after a closing quote, and a quoted field never closed are\n// `error.InvalidInput`. Lines may end in CRLF or LF, empty lines are\n// skipped, and a leading UTF-8 byte-order mark is dropped.\n\n/// The rows of comma-separated text.\npub fn parse(text: []u8) -> !List(List(String)) {\n    return parse_with(text, ',')\n}\n\n/// The rows of text whose fields are separated by `sep` (`'\\t'` for TSV,\n/// `';'` where the decimal separator is a comma).\npub fn parse_with(text: []u8, sep: u8) -> !List(List(String)) {\n    var rows = List(List(String)).new()\n    var row = List(String).new()\n    var field = String.new()\n    var i: usize = 0\n    if text.len >= 3 and text[0] == 0xEF and text[1] == 0xBB and text[2] == 0xBF { i = 3 }\n    // inside quotes; the field was quoted and has closed; nothing read of\n    // the field yet\n    var quoted = false\n    var closed = false\n    var fresh = true\n    while i < text.len {\n        let c = text[i]\n        if quoted {\n            if c == '\"' {\n                if i + 1 < text.len and text[i + 1] == '\"' {\n                    field.push_byte('\"')\n                    i += 2\n                    continue\n                }\n                quoted = false\n                closed = true\n            } else {\n                field.push_byte(c)\n            }\n            i += 1\n            continue\n        }\n        if c == sep {\n            row.append(field)\n            field = String.new()\n            fresh = true\n            closed = false\n            i += 1\n            continue\n        }\n        if c == '\\r' or c == '\\n' {\n            if c == '\\r' and i + 1 < text.len and text[i + 1] == '\\n' { i += 1 }\n            i += 1\n            if row.len == 0 and fresh and !closed { continue }\n            row.append(field)\n            field = String.new()\n            rows.append(row)\n            row = List(String).new()\n            fresh = true\n            closed = false\n            continue\n        }\n        if closed { return error.InvalidInput }\n        if c == '\"' {\n            if !fresh { return error.InvalidInput }\n            quoted = true\n            fresh = false\n            i += 1\n            continue\n        }\n        field.push_byte(c)\n        fresh = false\n        i += 1\n    }\n    if quoted { return error.InvalidInput }\n    if row.len > 0 or !fresh or closed {\n        row.append(field)\n        rows.append(row)\n    }\n    return rows\n}\n\n/// The rows after the first, each as a map from the first row's names to\n/// its fields. A row shorter than the header leaves the missing names out;\n/// one longer is `error.InvalidInput`.\npub fn by_header(text: []u8) -> !List(Map(String, String)) {\n    let rows = try parse(text)\n    var out = List(Map(String, String)).new()\n    if rows.len == 0 { return out }\n    let names = &rows[0]\n    for r in 1..rows.len {\n        let row = &rows[r]\n        if row.len > names.len { return error.InvalidInput }\n        var m = Map(String, String).new()\n        for i in 0..row.len { m.put(names.*[i].clone(), row.*[i].clone()) }\n        out.append(m)\n    }\n    return out\n}\n\n/// A field as written between separators: in double quotes, with any\n/// quote doubled, when it holds `sep`, a quote or a line break.\npub fn field(value: []u8, sep: u8) -> String {\n    var needs = false\n    for c in value {\n        if c == sep or c == '\"' or c == '\\r' or c == '\\n' { needs = true }\n    }\n    if !needs { return String.from(value) }\n    var out = String.with_capacity(value.len + 2)\n    out.push_byte('\"')\n    for c in value {\n        if c == '\"' { out.push_byte('\"') }\n        out.push_byte(c)\n    }\n    out.push_byte('\"')\n    return out\n}\n\n/// Rows as comma-separated text, each line ending in CRLF.\npub fn to_text(rows: *List(List(String))) -> String {\n    return to_text_with(rows, ',', \"\\r\\n\")\n}\n\n/// Rows as text with `sep` between fields and `line_end` after each row.\npub fn to_text_with(rows: *List(List(String)), sep: u8, line_end: []u8) -> String {\n    var out = String.new()\n    for row in rows.* {\n        for f, i in row {\n            if i > 0 { out.push_byte(sep) }\n            out.append(field(f[..], sep))\n        }\n        out.append(line_end)\n    }\n    return out\n}\n\n// ------------------------------------------------------------------ tests\n\ntest \"plain rows, empty fields and line ends\" {\n    let rows = try parse(\"a,b,c\\r\\n1,,3\\n\\n4,5,\\n\")\n    expect_eq(rows.len, 3)\n    expect_eq(rows[0].len, 3)\n    expect_eq(rows[1][1], \"\")\n    expect_eq(rows[1][2], \"3\")\n    expect_eq(rows[2].len, 3)\n    expect_eq(rows[2][2], \"\")\n    let last = try parse(\"x,y\")\n    expect_eq(last.len, 1)\n    expect_eq(last[0][1], \"y\")\n    expect_eq((try parse(\"\")).len, 0)\n    let bom = try parse(\"\\xEF\\xBB\\xBFname\\nNexium\\n\")\n    expect_eq(bom[0][0], \"name\")\n}\n\ntest \"quoted fields\" {\n    let rows = try parse(\"\\\"a, b\\\",\\\"say \\\"\\\"hi\\\"\\\"\\\",\\\"two\\nlines\\\",\\\"\\\"\\n\")\n    expect_eq(rows.len, 1)\n    expect_eq(rows[0].len, 4)\n    expect_eq(rows[0][0], \"a, b\")\n    expect_eq(rows[0][1], \"say \\\"hi\\\"\")\n    expect_eq(rows[0][2], \"two\\nlines\")\n    expect_eq(rows[0][3], \"\")\n    let lone = try parse(\"\\\"\\\"\\n\")\n    expect_eq(lone.len, 1)\n    expect_eq(lone[0][0], \"\")\n}\n\ntest \"what is not CSV\" {\n    for bad in [\"a\\\"b,c\\n\", \"\\\"open,c\\n\", \"\\\"a\\\"b,c\\n\", \"\\\"a\\\" ,c\\n\"] {\n        var refused = false\n        _ = parse(bad) catch |e| {\n            refused = e == error.InvalidInput\n            List(List(String)).new()\n        }\n        if !refused { println(\"csv: {} was read\", .{bad}) }\n        expect(refused)\n    }\n}\n\ntest \"other separators\" {\n    let rows = try parse_with(\"a\\tb;c\\n1\\t2\\n\", '\\t')\n    expect_eq(rows[0][1], \"b;c\")\n    let semi = try parse_with(\"x;\\\"1;5\\\"\\n\", ';')\n    expect_eq(semi[0][1], \"1;5\")\n}\n\ntest \"rows by their header\" {\n    let rows = try by_header(\"name,year\\nNexium,2026\\nC\\n\")\n    expect_eq(rows.len, 2)\n    expect_eq(rows[0][\"name\"].?, \"Nexium\")\n    expect_eq(rows[0][\"year\"].?, \"2026\")\n    expect(rows[1][\"year\"] == null)\n    var refused = false\n    _ = by_header(\"a\\n1,2\\n\") catch |e| {\n        refused = e == error.InvalidInput\n        List(Map(String, String)).new()\n    }\n    expect(refused)\n}\n\ntest \"writing, and reading back what was written\" {\n    var rows = List(List(String)).new()\n    var r1 = List(String).new()\n    r1.append(String.from(\"plain\"))\n    r1.append(String.from(\"with, comma\"))\n    r1.append(String.from(\"with \\\"quotes\\\"\"))\n    rows.append(r1)\n    var r2 = List(String).new()\n    r2.append(String.from(\"two\\nlines\"))\n    r2.append(String.new())\n    r2.append(String.from(\"end\"))\n    rows.append(r2)\n    let text = to_text(&rows)\n    expect_eq(text, \"plain,\\\"with, comma\\\",\\\"with \\\"\\\"quotes\\\"\\\"\\\"\\r\\n\\\"two\\nlines\\\",,end\\r\\n\")\n    let back = try parse(text[..])\n    expect_eq(back.len, 2)\n    for i in 0..2 {\n        for j in 0..3 { expect_eq(back[i][j], rows[i][j]) }\n    }\n    expect_eq(to_text_with(&rows, '\\t', \"\\n\"), \"plain\\twith, comma\\t\\\"with \\\"\\\"quotes\\\"\\\"\\\"\\n\\\"two\\nlines\\\"\\t\\tend\\n\")\n}\n";
static const char nx_str_900[5] = "toml";
static const char nx_str_901[42542] = "// std.toml: TOML 1.0 (toml.io), written in Nexium: reading a document into\n// values, finding a value by its key, and writing values back as TOML.\n//\n// `import std.toml` then:\n//\n//     let doc = try toml.parse(text)\n//     let name = toml.as_str(toml.lookup(&doc, \"package.name\") orelse return) orelse \"\"\n//     for dep in toml.keys(toml.get(&doc, \"dependencies\") orelse return) { }\n//     if let why = toml.problem(text) { eprintln(\"{}\", .{why}) }   // \"line 3: ...\"\n//     let out = toml.stringify(&doc)\n//\n// Every value TOML has: strings (basic and literal, each also multi-line),\n// 64-bit integers (decimal, hex, octal, binary), floats (with `inf` and\n// `nan`), booleans, dates and times (kept as written: offset date-time,\n// local date-time, local date, local time), arrays, tables, inline tables\n// and arrays of tables, under TOML's rules that a key and a table are\n// defined once. A document that breaks one is `error.InvalidInput`;\n// `problem` says where and why.\n\n/// A TOML value; a document is a `Table`.\npub enum Toml derive(Clone) {\n    Str(String),\n    Int(i64),\n    Float(f64),\n    Bool(bool),\n    Time(Stamp),\n    Arr(List(Toml)),\n    Table(List(Entry)),\n}\n\n/// A key of a table and its value, in the order the document gave them.\npub struct Entry derive(Clone) {\n    key: String\n    value: Toml\n}\n\n/// Which of TOML's four date and time forms a stamp is.\npub enum StampKind {\n    OffsetDateTime,\n    LocalDateTime,\n    LocalDate,\n    LocalTime,\n}\n\n/// A date, a time or both (RFC 3339), as the document wrote it.\npub struct Stamp derive(Clone) {\n    kind: StampKind\n    text: String\n}\n\n// ------------------------------------------------------------------ reading\n\n/// The document's values: a `Table` of its keys.\npub fn parse(text: []u8) -> !Toml {\n    var why = String.new()\n    return parse_doc(text, &mut why) orelse return error.InvalidInput\n}\n\n/// Why `text` is not a TOML document (`line N: ...`), or null when it is.\npub fn problem(text: []u8) -> ?String {\n    var why = String.new()\n    if parse_doc(text, &mut why) != null { return null }\n    return why\n}\n\n// the document as it is read: each table knows how it was defined, which\n// the rules for defining it again need and a `Toml` does not keep\nconst N_TABLE: u8 = 0\nconst N_ARRAY: u8 = 1\nconst N_VALUE: u8 = 2\n\nstruct Node {\n    kind: u8\n    /// a table's keys, and its members in `kids`; an array of tables' tables\n    keys: List(String)\n    kids: List(Node)\n    value: Toml\n    /// a table defined by a `[header]`, or by dotted keys\n    header: bool\n    dotted: bool\n}\n\nfn table_node() -> Node {\n    return Node{ .kind = N_TABLE, .keys = List(String).new(), .kids = List(Node).new(), .value = Toml.Bool(false), .header = false, .dotted = false }\n}\n\nfn value_node(own v: Toml) -> Node {\n    var n = table_node()\n    n.kind = N_VALUE\n    n.value = v\n    return n\n}\n\nfn find(n: *Node, key: []u8) -> ?usize {\n    for k, i in n.keys { if k[..] == key { return i } }\n    return null\n}\n\nfn to_toml(n: *Node) -> Toml {\n    if n.kind == N_VALUE { return n.value.clone() }\n    if n.kind == N_ARRAY {\n        var items = List(Toml).new()\n        for k in n.kids { items.append(to_toml(&k)) }\n        return Toml.Arr(items)\n    }\n    var entries = List(Entry).new()\n    for k, i in n.keys { entries.append(Entry{ .key = k.clone(), .value = to_toml(&n.kids[i]) }) }\n    return Toml.Table(entries)\n}\n\nfn parse_doc(text: []u8, why: *mut String) -> ?Toml {\n    var p = Parser{ .src = text, .at = 0, .line = 1, .why = String.new() }\n    var root = table_node()\n    // the table key/value lines go into, as the steps down to it\n    var current = List(usize).new()\n    while true {\n        if !p.skip_blank() { break }\n        if p.at >= p.src.len { break }\n        if p.src[p.at] == '[' {\n            var path = List(usize).new()\n            if !p.header(&mut root, &mut path) { break }\n            current = path\n        } else if !p.key_value(&mut root, current[..]) {\n            break\n        }\n        if !p.end_of_line() { break }\n    }\n    if p.why.len > 0 {\n        why.* = p.why.clone()\n        return null\n    }\n    return to_toml(&root)\n}\n\nstruct Parser {\n    src: []u8\n    at: usize\n    line: usize\n    why: String\n}\n\nfn is_bare(c: u8) -> bool {\n    return (c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z') or (c >= '0' and c <= '9') or c == '_' or c == '-'\n}\n\nfn is_digit(c: u8) -> bool {\n    return c >= '0' and c <= '9'\n}\n\nfn digit_value(c: u8) -> u32 {\n    if c >= '0' and c <= '9' { return (c - '0') as u32 }\n    if c >= 'a' and c <= 'f' { return ((c - 'a') as u32) + 10 }\n    if c >= 'A' and c <= 'F' { return ((c - 'A') as u32) + 10 }\n    return 99\n}\n\nimpl Parser {\n    fn fail(self: *mut Self, msg: []u8) {\n        if self.why.len == 0 { self.why = format(\"line {}: {}\", .{self.line, msg}) }\n    }\n\n    fn starts(self: *Self, s: []u8) -> bool {\n        return self.at + s.len <= self.src.len and self.src[self.at..self.at + s.len] == s\n    }\n\n    fn peek(self: *Self) -> u8 {\n        return if self.at < self.src.len { self.src[self.at] } else { 0 }\n    }\n\n    fn skip_ws(self: *mut Self) {\n        while self.at < self.src.len and (self.src[self.at] == ' ' or self.src[self.at] == '\\t') { self.at += 1 }\n    }\n\n    // a comment to the end of its line; false at a control character in it\n    fn skip_comment(self: *mut Self) -> bool {\n        if self.peek() != '#' { return true }\n        while self.at < self.src.len and self.src[self.at] != '\\n' {\n            let c = self.src[self.at]\n            if c == '\\r' and self.at + 1 < self.src.len and self.src[self.at + 1] == '\\n' { return true }\n            if (c < 0x20 and c != '\\t') or c == 0x7f {\n                self.fail(\"a control character in a comment\")\n                return false\n            }\n            self.at += 1\n        }\n        return true\n    }\n\n    // a line end, LF or CRLF\n    fn newline(self: *mut Self) -> bool {\n        if self.peek() == '\\n' {\n            self.at += 1\n            self.line += 1\n            return true\n        }\n        if self.starts(\"\\r\\n\") {\n            self.at += 2\n            self.line += 1\n            return true\n        }\n        return false\n    }\n\n    // whitespace, comments and line ends; false after a failure\n    fn skip_blank(self: *mut Self) -> bool {\n        while true {\n            self.skip_ws()\n            if !self.skip_comment() { return false }\n            if !self.newline() { break }\n        }\n        return self.why.len == 0\n    }\n\n    // what may follow a statement on its line: whitespace, a comment\n    fn end_of_line(self: *mut Self) -> bool {\n        self.skip_ws()\n        if !self.skip_comment() { return false }\n        if self.at >= self.src.len or self.newline() { return true }\n        self.fail(\"more on the line after its key and value, or its header\")\n        return false\n    }\n\n    // ---------------------------------------------------------------- keys\n\n    fn simple_key(self: *mut Self) -> ?String {\n        let c = self.peek()\n        if c == '\"' {\n            if self.starts(\"\\\"\\\"\\\"\") {\n                self.fail(\"a multi-line string cannot be a key\")\n                return null\n            }\n            return self.basic_string()\n        }\n        if c == '\\'' {\n            if self.starts(\"'''\") {\n                self.fail(\"a multi-line string cannot be a key\")\n                return null\n            }\n            return self.literal_string()\n        }\n        let start = self.at\n        while self.at < self.src.len and is_bare(self.src[self.at]) { self.at += 1 }\n        if self.at == start {\n            self.fail(\"a key is missing\")\n            return null\n        }\n        return String.from(self.src[start..self.at])\n    }\n\n    // a key, dotted or not: `a`, `a.b`, `\"a b\".c`\n    fn key(self: *mut Self) -> ?List(String) {\n        var parts = List(String).new()\n        while true {\n            self.skip_ws()\n            let k = self.simple_key() orelse return null\n            parts.append(k)\n            self.skip_ws()\n            if self.peek() != '.' { break }\n            self.at += 1\n        }\n        return parts\n    }\n\n    // ---------------------------------------------------------------- tables\n\n    // `[a.b]` or `[[a.b]]`: the steps down to the table it opens go in `path`\n    fn header(self: *mut Self, root: *mut Node, path: *mut List(usize)) -> bool {\n        self.at += 1\n        let array = self.peek() == '['\n        if array { self.at += 1 }\n        let parts = self.key() orelse return false\n        if self.peek() != ']' {\n            self.fail(\"a table's header is not closed with `]`\")\n            return false\n        }\n        self.at += 1\n        if array {\n            if self.peek() != ']' {\n                self.fail(\"an array of tables' header is not closed with `]]`\")\n                return false\n            }\n            self.at += 1\n        }\n        return self.open_table(root, parts[..], array, path)\n    }\n\n    fn open_table(self: *mut Self, n: *mut Node, parts: []String, array: bool, path: *mut List(usize)) -> bool {\n        let name = parts[0][..]\n        let last = parts.len == 1\n        let found = find(n, name)\n        if found == null {\n            var t = table_node()\n            t.header = last\n            if last and array {\n                var arr = table_node()\n                arr.kind = N_ARRAY\n                arr.kids.append(t)\n                n.keys.append(String.from(name))\n                n.kids.append(arr)\n                path.append(n.kids.len - 1)\n                path.append(0)\n                return true\n            }\n            n.keys.append(String.from(name))\n            n.kids.append(t)\n            path.append(n.kids.len - 1)\n            if last { return true }\n            return self.open_table(&mut n.kids[n.kids.len - 1], parts[1..], array, path)\n        }\n        let k = found.?\n        path.append(k)\n        let child = &mut n.kids[k]\n        if child.kind == N_VALUE {\n            self.fail(format(\"`{}` is a value, not a table\", .{name})[..])\n            return false\n        }\n        if last {\n            if array {\n                if child.kind != N_ARRAY {\n                    self.fail(format(\"`{}` is a table, not an array of tables\", .{name})[..])\n                    return false\n                }\n                var t = table_node()\n                t.header = true\n                child.kids.append(t)\n                path.append(child.kids.len - 1)\n                return true\n            }\n            if child.kind == N_ARRAY {\n                self.fail(format(\"`{}` is an array of tables, not a table\", .{name})[..])\n                return false\n            }\n            if child.header or child.dotted {\n                self.fail(format(\"the table `{}` is defined twice\", .{name})[..])\n                return false\n            }\n            child.header = true\n            return true\n        }\n        if child.kind == N_ARRAY {\n            let e = child.kids.len - 1\n            path.append(e)\n            return self.open_table(&mut child.kids[e], parts[1..], array, path)\n        }\n        return self.open_table(child, parts[1..], array, path)\n    }\n\n    // ---------------------------------------------------------------- keys and values\n\n    fn key_value(self: *mut Self, root: *mut Node, path: []usize) -> bool {\n        let parts = self.key() orelse return false\n        if self.peek() != '=' {\n            self.fail(\"`=` is missing after a key\")\n            return false\n        }\n        self.at += 1\n        self.skip_ws()\n        let v = self.value() orelse return false\n        return self.put(root, path, parts[..], v)\n    }\n\n    fn put(self: *mut Self, n: *mut Node, path: []usize, parts: []String, own v: Toml) -> bool {\n        if path.len > 0 { return self.put(&mut n.kids[path[0]], path[1..], parts, v) }\n        return self.put_dotted(n, parts, v)\n    }\n\n    fn put_dotted(self: *mut Self, n: *mut Node, parts: []String, own v: Toml) -> bool {\n        let name = parts[0][..]\n        let found = find(n, name)\n        if parts.len == 1 {\n            if found != null {\n                self.fail(format(\"the key `{}` is defined twice\", .{name})[..])\n                return false\n            }\n            n.keys.append(String.from(name))\n            n.kids.append(value_node(v))\n            return true\n        }\n        if let k = found {\n            let child = &mut n.kids[k]\n            if child.kind != N_TABLE {\n                self.fail(format(\"`{}` is not a table that dotted keys can add to\", .{name})[..])\n                return false\n            }\n            if child.header {\n                self.fail(format(\"the table `{}` has a header, so dotted keys cannot add to it\", .{name})[..])\n                return false\n            }\n            child.dotted = true\n            return self.put_dotted(child, parts[1..], v)\n        }\n        var t = table_node()\n        t.dotted = true\n        n.keys.append(String.from(name))\n        n.kids.append(t)\n        return self.put_dotted(&mut n.kids[n.kids.len - 1], parts[1..], v)\n    }\n\n    fn value(self: *mut Self) -> ?Toml {\n        let c = self.peek()\n        if c == '\"' {\n            if self.starts(\"\\\"\\\"\\\"\") {\n                let s = self.ml_string('\"') orelse return null\n                return Toml.Str(s)\n            }\n            let s = self.basic_string() orelse return null\n            return Toml.Str(s)\n        }\n        if c == '\\'' {\n            if self.starts(\"'''\") {\n                let s = self.ml_string('\\'') orelse return null\n                return Toml.Str(s)\n            }\n            let s = self.literal_string() orelse return null\n            return Toml.Str(s)\n        }\n        if c == '[' { return self.array() }\n        if c == '{' { return self.inline_table() }\n        return self.scalar()\n    }\n\n    // ---------------------------------------------------------------- strings\n\n    fn basic_string(self: *mut Self) -> ?String {\n        self.at += 1\n        var out = String.new()\n        while true {\n            if self.at >= self.src.len or self.src[self.at] == '\\n' or self.src[self.at] == '\\r' {\n                self.fail(\"a string is not closed on its line\")\n                return null\n            }\n            let c = self.src[self.at]\n            if c == '\"' {\n                self.at += 1\n                break\n            }\n            if c == '\\\\' {\n                if !self.escape(&mut out) { return null }\n                continue\n            }\n            if (c < 0x20 and c != '\\t') or c == 0x7f {\n                self.fail(\"a control character in a string\")\n                return null\n            }\n            out.push_byte(c)\n            self.at += 1\n        }\n        return out\n    }\n\n    fn literal_string(self: *mut Self) -> ?String {\n        self.at += 1\n        let start = self.at\n        while true {\n            if self.at >= self.src.len or self.src[self.at] == '\\n' or self.src[self.at] == '\\r' {\n                self.fail(\"a string is not closed on its line\")\n                return null\n            }\n            let c = self.src[self.at]\n            if c == '\\'' { break }\n            if (c < 0x20 and c != '\\t') or c == 0x7f {\n                self.fail(\"a control character in a string\")\n                return null\n            }\n            self.at += 1\n        }\n        let s = String.from(self.src[start..self.at])\n        self.at += 1\n        return s\n    }\n\n    // at a backslash in a basic string\n    fn escape(self: *mut Self, out: *mut String) -> bool {\n        if self.at + 1 >= self.src.len {\n            self.fail(\"a string ends in a backslash\")\n            return false\n        }\n        let e = self.src[self.at + 1]\n        self.at += 2\n        if e == 'b' { out.push_byte(8) }\n        else if e == 't' { out.push_byte('\\t') }\n        else if e == 'n' { out.push_byte('\\n') }\n        else if e == 'f' { out.push_byte(12) }\n        else if e == 'r' { out.push_byte('\\r') }\n        else if e == '\"' { out.push_byte('\"') }\n        else if e == '\\\\' { out.push_byte('\\\\') }\n        else if e == 'u' or e == 'U' {\n            let n: usize = if e == 'u' { 4 } else { 8 }\n            if self.at + n > self.src.len {\n                self.fail(\"a \\\\u escape is cut short\")\n                return false\n            }\n            var cp: u32 = 0\n            for i in 0..n {\n                let d = digit_value(self.src[self.at + i])\n                if d > 15 {\n                    self.fail(\"a \\\\u escape with a character that is not a hex digit\")\n                    return false\n                }\n                cp = cp * 16 + d\n            }\n            self.at += n\n            if (cp >= 0xD800 and cp <= 0xDFFF) or cp > 0x10FFFF {\n                self.fail(\"a \\\\u escape that is not a Unicode scalar value\")\n                return false\n            }\n            out.append_char(cp as char)\n        } else {\n            self.fail(format(\"an escape TOML does not have: \\\\{}\", .{self.src[self.at - 1..self.at]})[..])\n            return false\n        }\n        return true\n    }\n\n    // `\"\"\"` or `'''`: a line end straight after the opening is dropped, a\n    // basic one's backslash at a line's end joins the next line, and up to\n    // two quotes may stand before the closing three\n    fn ml_string(self: *mut Self, q: u8) -> ?String {\n        self.at += 3\n        _ = self.newline()\n        var out = String.new()\n        while true {\n            if self.at >= self.src.len {\n                self.fail(\"a multi-line string is not closed\")\n                return null\n            }\n            let c = self.src[self.at]\n            if c == q and self.at + 2 < self.src.len and self.src[self.at + 1] == q and self.src[self.at + 2] == q {\n                var run: usize = 3\n                while self.at + run < self.src.len and self.src[self.at + run] == q { run += 1 }\n                if run > 5 {\n                    self.fail(\"three quotes in a row inside a multi-line string\")\n                    return null\n                }\n                for _ in 0..run - 3 { out.push_byte(q) }\n                self.at += run\n                return out\n            }\n            if q == '\"' and c == '\\\\' {\n                var j = self.at + 1\n                while j < self.src.len and (self.src[j] == ' ' or self.src[j] == '\\t') { j += 1 }\n                if j < self.src.len and (self.src[j] == '\\n' or (self.src[j] == '\\r' and j + 1 < self.src.len and self.src[j + 1] == '\\n')) {\n                    self.at = j\n                    while self.at < self.src.len {\n                        let d = self.src[self.at]\n                        if d == ' ' or d == '\\t' {\n                            self.at += 1\n                        } else if !self.newline() {\n                            break\n                        }\n                    }\n                    continue\n                }\n                if !self.escape(&mut out) { return null }\n                continue\n            }\n            if self.newline() {\n                out.push_byte('\\n')\n                continue\n            }\n            if (c < 0x20 and c != '\\t') or c == 0x7f {\n                self.fail(\"a control character in a string\")\n                return null\n            }\n            out.push_byte(c)\n            self.at += 1\n        }\n        return out\n    }\n\n    // ---------------------------------------------------------------- arrays and inline tables\n\n    fn array(self: *mut Self) -> ?Toml {\n        self.at += 1\n        var items = List(Toml).new()\n        while true {\n            if !self.skip_blank() { return null }\n            if self.peek() == ']' {\n                self.at += 1\n                break\n            }\n            if self.at >= self.src.len {\n                self.fail(\"an array is not closed\")\n                return null\n            }\n            let v = self.value() orelse return null\n            items.append(v)\n            if !self.skip_blank() { return null }\n            if self.peek() == ',' {\n                self.at += 1\n                continue\n            }\n            if self.peek() == ']' {\n                self.at += 1\n                break\n            }\n            self.fail(\"a comma or `]` is missing in an array\")\n            return null\n        }\n        return Toml.Arr(items)\n    }\n\n    fn inline_table(self: *mut Self) -> ?Toml {\n        self.at += 1\n        var t = table_node()\n        self.skip_ws()\n        if self.peek() == '}' {\n            self.at += 1\n            return to_toml(&t)\n        }\n        while true {\n            let parts = self.key() orelse return null\n            if self.peek() != '=' {\n                self.fail(\"`=` is missing after a key\")\n                return null\n            }\n            self.at += 1\n            self.skip_ws()\n            let v = self.value() orelse return null\n            if !self.put_dotted(&mut t, parts[..], v) { return null }\n            self.skip_ws()\n            if self.peek() == '}' {\n                self.at += 1\n                break\n            }\n            if self.peek() != ',' {\n                self.fail(\"a comma or `}` is missing in an inline table (it must fit on one line)\")\n                return null\n            }\n            self.at += 1\n        }\n        return to_toml(&t)\n    }\n\n    // ---------------------------------------------------------------- numbers, booleans, dates and times\n\n    fn scalar(self: *mut Self) -> ?Toml {\n        let start = self.at\n        while self.at < self.src.len {\n            let c = self.src[self.at]\n            if is_bare(c) or c == '+' or c == '.' or c == ':' {\n                self.at += 1\n                continue\n            }\n            // a date and a time may be joined by a space\n            if c == ' ' and self.at - start == 10 and self.src[start + 4] == '-' and self.at + 1 < self.src.len and is_digit(self.src[self.at + 1]) {\n                self.at += 1\n                continue\n            }\n            break\n        }\n        let tok = self.src[start..self.at]\n        if tok.len == 0 {\n            self.fail(\"a value is missing\")\n            return null\n        }\n        if tok == \"true\" { return Toml.Bool(true) }\n        if tok == \"false\" { return Toml.Bool(false) }\n        if tok == \"inf\" or tok == \"+inf\" { return Toml.Float(math.INF) }\n        if tok == \"-inf\" { return Toml.Float(-math.INF) }\n        if tok == \"nan\" or tok == \"+nan\" or tok == \"-nan\" { return Toml.Float(math.NAN) }\n        if (tok.len >= 10 and is_digit(tok[0]) and tok[4] == '-') or (tok.len >= 8 and is_digit(tok[0]) and tok[2] == ':') {\n            let kind = stamp_kind(tok) orelse {\n                self.fail(format(\"`{}` is not a date or time TOML allows\", .{tok})[..])\n                return null\n            }\n            return Toml.Time(Stamp{ .kind = kind, .text = String.from(tok) })\n        }\n        if let i = int_value(tok) { return Toml.Int(i) }\n        if let f = float_value(tok) { return Toml.Float(f) }\n        self.fail(format(\"`{}` is not a value TOML has\", .{tok})[..])\n        return null\n    }\n}\n\n// the end of a run of digits of `base` from `i`, underscores only between\n// digits; `i` when no digit is there; null for a misplaced underscore\nfn digit_run(s: []u8, i: usize, base: u32) -> ?usize {\n    var j = i\n    var digit = false\n    while j < s.len {\n        let c = s[j]\n        if c == '_' {\n            if !digit { return null }\n            digit = false\n            j += 1\n            continue\n        }\n        if digit_value(c) >= base { break }\n        digit = true\n        j += 1\n    }\n    if j > i and !digit { return null }\n    return j\n}\n\nfn int_value(tok: []u8) -> ?i64 {\n    var base: u32 = 10\n    var i: usize = 0\n    var negative = false\n    if tok.len > 2 and tok[0] == '0' and (tok[1] == 'x' or tok[1] == 'o' or tok[1] == 'b') {\n        base = if tok[1] == 'x' { 16 } else if tok[1] == 'o' { 8 } else { 2 }\n        i = 2\n    } else {\n        if tok.len > 0 and (tok[0] == '+' or tok[0] == '-') {\n            negative = tok[0] == '-'\n            i = 1\n        }\n        // no leading zero: `0` itself only\n        if i + 1 < tok.len and tok[i] == '0' { return null }\n    }\n    let end = digit_run(tok, i, base) orelse return null\n    if end == i or end != tok.len { return null }\n    var v: u64 = 0\n    let limit: u64 = if negative { 9223372036854775808 } else { 9223372036854775807 }\n    for c in tok[i..end] {\n        if c == '_' { continue }\n        let d = digit_value(c) as u64\n        if v > (limit - d) / (base as u64) { return null }\n        v = v * (base as u64) + d\n    }\n    if negative {\n        if v == 9223372036854775808 { return -9223372036854775807 - 1 }\n        return -(v as i64)\n    }\n    return v as i64\n}\n\nfn float_value(tok: []u8) -> ?f64 {\n    var i: usize = 0\n    if tok.len > 0 and (tok[0] == '+' or tok[0] == '-') { i = 1 }\n    let int_end = digit_run(tok, i, 10) orelse return null\n    if int_end == i { return null }\n    if int_end - i > 1 and tok[i] == '0' { return null }\n    var j = int_end\n    var fraction = false\n    if j < tok.len and tok[j] == '.' {\n        let frac_end = digit_run(tok, j + 1, 10) orelse return null\n        if frac_end == j + 1 { return null }\n        j = frac_end\n        fraction = true\n    }\n    var exponent = false\n    if j < tok.len and (tok[j] == 'e' or tok[j] == 'E') {\n        var k = j + 1\n        if k < tok.len and (tok[k] == '+' or tok[k] == '-') { k += 1 }\n        let exp_end = digit_run(tok, k, 10) orelse return null\n        if exp_end == k { return null }\n        j = exp_end\n        exponent = true\n    }\n    if j != tok.len or !(fraction or exponent) { return null }\n    var plain = String.with_capacity(tok.len)\n    for c in tok { if c != '_' { plain.push_byte(c) } }\n    let f = plain[..].parse_float() catch { return null }\n    return f\n}\n\nfn two(s: []u8, at: usize) -> ?u32 {\n    if at + 2 > s.len or !is_digit(s[at]) or !is_digit(s[at + 1]) { return null }\n    return ((s[at] - '0') as u32) * 10 + ((s[at + 1] - '0') as u32)\n}\n\n// `HH:MM:SS` and a fraction from `at`: where it ends, or null\nfn time_end(s: []u8, at: usize) -> ?usize {\n    let h = two(s, at) orelse return null\n    if at + 2 >= s.len or s[at + 2] != ':' { return null }\n    let m = two(s, at + 3) orelse return null\n    if at + 5 >= s.len or s[at + 5] != ':' { return null }\n    let sec = two(s, at + 6) orelse return null\n    if h > 23 or m > 59 or sec > 60 { return null }\n    var end = at + 8\n    if end < s.len and s[end] == '.' {\n        var k = end + 1\n        while k < s.len and is_digit(s[k]) { k += 1 }\n        if k == end + 1 { return null }\n        end = k\n    }\n    return end\n}\n\nfn stamp_kind(s: []u8) -> ?StampKind {\n    if s.len >= 3 and s[2] == ':' {\n        let end = time_end(s, 0) orelse return null\n        return if end == s.len { StampKind.LocalTime } else { null }\n    }\n    if s.len < 10 or s[4] != '-' or s[7] != '-' { return null }\n    var year: u32 = 0\n    for k in 0..4 {\n        if !is_digit(s[k]) { return null }\n        year = year * 10 + ((s[k] - '0') as u32)\n    }\n    let month = two(s, 5) orelse return null\n    let day = two(s, 8) orelse return null\n    if month < 1 or month > 12 or day < 1 { return null }\n    let leap = (year % 4 == 0 and year % 100 != 0) or year % 400 == 0\n    let lengths: [12]u32 = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]\n    var days: u32 = lengths[(month - 1) as usize]\n    if month == 2 and leap { days = 29 }\n    if day > days { return null }\n    if s.len == 10 { return StampKind.LocalDate }\n    if s[10] != 'T' and s[10] != 't' and s[10] != ' ' { return null }\n    let end = time_end(s, 11) orelse return null\n    if end == s.len { return StampKind.LocalDateTime }\n    if s[end] == 'Z' or s[end] == 'z' {\n        return if end + 1 == s.len { StampKind.OffsetDateTime } else { null }\n    }\n    if s[end] != '+' and s[end] != '-' { return null }\n    let oh = two(s, end + 1) orelse return null\n    if end + 3 >= s.len or s[end + 3] != ':' { return null }\n    let om = two(s, end + 4) orelse return null\n    if oh > 23 or om > 59 or end + 6 != s.len { return null }\n    return StampKind.OffsetDateTime\n}\n\n// ------------------------------------------------------------------ finding\n\n/// The value of a table's `key`, or null.\npub fn get(v: *Toml, key: []u8) -> ?*Toml {\n    match v.* {\n        .Table(entries) => {\n            for e, i in entries {\n                if e.key == key { return &entries[i].value }\n            }\n            return null\n        },\n        _ => return null,\n    }\n}\n\n/// The value at a dotted path of bare keys, `package.name`, or null.\npub fn lookup(v: *Toml, dotted: []u8) -> ?*Toml {\n    let dot = dotted.find(\".\") orelse return get(v, dotted)\n    let first = get(v, dotted[0..dot]) orelse return null\n    return lookup(first, dotted[dot + 1..dotted.len])\n}\n\n/// An array's item `i`, or null.\npub fn at(v: *Toml, i: usize) -> ?*Toml {\n    match v.* {\n        .Arr(items) => {\n            if i < items.len { return &items[i] }\n            return null\n        },\n        _ => return null,\n    }\n}\n\n/// How many items an array holds or keys a table has; 0 for anything else.\npub fn len(v: *Toml) -> usize {\n    match v.* {\n        .Arr(items) => return items.len,\n        .Table(entries) => return entries.len,\n        _ => return 0,\n    }\n}\n\n/// Is it a table (a document, a `[header]`'s, or an inline one)?\npub fn is_table(v: *Toml) -> bool {\n    match v.* {\n        .Table(_) => return true,\n        _ => return false,\n    }\n}\n\n/// Is it an array (an array of tables included)?\npub fn is_array(v: *Toml) -> bool {\n    match v.* {\n        .Arr(_) => return true,\n        _ => return false,\n    }\n}\n\n/// A table's keys in the document's order; empty for anything else.\npub fn keys(v: *Toml) -> List([]u8) {\n    var out = List([]u8).new()\n    match v.* {\n        .Table(entries) => { for e in entries { out.append(e.key.as_slice()) } },\n        _ => { },\n    }\n    return out\n}\n\npub fn as_str(v: *Toml) -> ?[]u8 {\n    match v.* {\n        .Str(s) => return s.as_slice(),\n        _ => return null,\n    }\n}\n\npub fn as_int(v: *Toml) -> ?i64 {\n    match v.* {\n        .Int(i) => return i,\n        _ => return null,\n    }\n}\n\n/// A float's value, or an integer's as a float.\npub fn as_float(v: *Toml) -> ?f64 {\n    match v.* {\n        .Float(f) => return f,\n        .Int(i) => return i as f64,\n        _ => return null,\n    }\n}\n\npub fn as_bool(v: *Toml) -> ?bool {\n    match v.* {\n        .Bool(b) => return b,\n        _ => return null,\n    }\n}\n\n/// A date or time as the document wrote it, and which form it is.\npub fn as_time(v: *Toml) -> ?Stamp {\n    match v.* {\n        .Time(s) => return s.clone(),\n        _ => return null,\n    }\n}\n\n// ------------------------------------------------------------------ writing\n\n/// A table as a TOML document: its plain keys first, then each table under\n/// a `[header]` and each array of tables under `[[headers]]`. Anything that\n/// is not a table is written as a value.\npub fn stringify(v: *Toml) -> String {\n    var out = String.new()\n    match v.* {\n        .Table(entries) => write_table(&mut out, entries, \"\"),\n        _ => write_value(&mut out, v),\n    }\n    return out\n}\n\nfn is_section(v: *Toml) -> bool {\n    match v.* {\n        .Table(_) => return true,\n        .Arr(items) => {\n            if items.len == 0 { return false }\n            for item in items {\n                match item {\n                    .Table(_) => { },\n                    _ => return false,\n                }\n            }\n            return true\n        },\n        _ => return false,\n    }\n}\n\nfn write_key(out: *mut String, key: []u8) {\n    var bare = key.len > 0\n    for c in key { if !is_bare(c) { bare = false } }\n    if bare { out.append(key) } else { write_string(out, key) }\n}\n\nfn write_string(out: *mut String, s: []u8) {\n    out.push_byte('\"')\n    for c in s {\n        if c == '\"' { out.append(\"\\\\\\\"\") }\n        else if c == '\\\\' { out.append(\"\\\\\\\\\") }\n        else if c == '\\n' { out.append(\"\\\\n\") }\n        else if c == '\\t' { out.append(\"\\\\t\") }\n        else if c == '\\r' { out.append(\"\\\\r\") }\n        else if c < 0x20 or c == 0x7f {\n            out.append(\"\\\\u00\")\n            out.push_byte(\"0123456789ABCDEF\"[(c >> 4) as usize])\n            out.push_byte(\"0123456789ABCDEF\"[(c & 15) as usize])\n        } else { out.push_byte(c) }\n    }\n    out.push_byte('\"')\n}\n\nfn write_value(out: *mut String, v: *Toml) {\n    match v.* {\n        .Str(s) => write_string(out, s[..]),\n        .Int(i) => out.append(format(\"{}\", .{i})),\n        .Float(f) => {\n            if f != f {\n                out.append(\"nan\")\n            } else if f == math.INF {\n                out.append(\"inf\")\n            } else if f == -math.INF {\n                out.append(\"-inf\")\n            } else {\n                let text = format(\"{}\", .{f})\n                out.append(text)\n                if text[..].find(\".\") == null and text[..].find(\"e\") == null and text[..].find(\"E\") == null { out.append(\".0\") }\n            }\n        },\n        .Bool(b) => out.append(if b { \"true\" } else { \"false\" }),\n        .Time(s) => out.append(s.text),\n        .Arr(items) => {\n            out.push_byte('[')\n            for item, i in items {\n                if i > 0 { out.append(\", \") }\n                write_value(out, &item)\n            }\n            out.push_byte(']')\n        },\n        .Table(entries) => {\n            out.push_byte('{')\n            for e, i in entries {\n                out.append(if i > 0 { \", \" } else { \" \" })\n                write_key(out, e.key[..])\n                out.append(\" = \")\n                write_value(out, &e.value)\n            }\n            out.append(if entries.len > 0 { \" }\" } else { \"}\" })\n        },\n    }\n}\n\nfn write_table(out: *mut String, entries: *List(Entry), prefix: []u8) {\n    for e in entries.* {\n        if is_section(&e.value) { continue }\n        write_key(out, e.key[..])\n        out.append(\" = \")\n        write_value(out, &e.value)\n        out.push_byte('\\n')\n    }\n    for e in entries.* {\n        if !is_section(&e.value) { continue }\n        var name = String.from(prefix)\n        if name.len > 0 { name.push_byte('.') }\n        write_key(&mut name, e.key[..])\n        match e.value {\n            .Table(sub) => {\n                if out.len > 0 { out.push_byte('\\n') }\n                out.push_byte('[')\n                out.append(name)\n                out.append(\"]\\n\")\n                write_table(out, &sub, name[..])\n            },\n            .Arr(items) => {\n                for item in items {\n                    match item {\n                        .Table(sub) => {\n                            if out.len > 0 { out.push_byte('\\n') }\n                            out.append(\"[[\")\n                            out.append(name)\n                            out.append(\"]]\\n\")\n                            write_table(out, &sub, name[..])\n                        },\n                        _ => { },\n                    }\n                }\n            },\n            _ => { },\n        }\n    }\n}\n\n// ------------------------------------------------------------------ tests\n\nfn same(a: *Toml, b: *Toml) -> bool {\n    match a.* {\n        .Str(x) => return as_str(b) != null and as_str(b).? == x[..],\n        .Int(x) => return as_int(b) != null and as_int(b).? == x,\n        .Float(x) => {\n            match b.* {\n                .Float(y) => return x == y or (x != x and y != y),\n                _ => return false,\n            }\n        },\n        .Bool(x) => return as_bool(b) != null and as_bool(b).? == x,\n        .Time(x) => return as_time(b) != null and as_time(b).?.text == x.text,\n        .Arr(xs) => {\n            if len(b) != xs.len { return false }\n            for x, i in xs { if !same(&x, at(b, i) orelse return false) { return false } }\n            return true\n        },\n        .Table(es) => {\n            if len(b) != es.len { return false }\n            for e in es { if !same(&e.value, get(b, e.key[..]) orelse return false) { return false } }\n            return true\n        },\n    }\n}\n\nfn doc(text: []u8) -> Toml {\n    return parse(text) catch {\n        println(\"toml: {}\", .{problem(text) orelse String.from(\"?\")})\n        panic(\"a document did not parse\")\n    }\n}\n\ntest \"keys, values and tables\" {\n    let d = doc(\"# a comment\\ntitle = \\\"TOML\\\" # after a value\\n\\n[owner]\\nname = 'Tom'\\n\\\"quoted key\\\" = 1\\nsite.\\\"google.com\\\" = true\\n\\n[database.connection]\\nports = [ 8000, 8001, ]\\nenabled = false\\n\")\n    expect_eq(as_str(get(&d, \"title\").?).?, \"TOML\")\n    expect_eq(as_str(lookup(&d, \"owner.name\").?).?, \"Tom\")\n    expect_eq(as_int(get(get(&d, \"owner\").?, \"quoted key\").?).?, 1)\n    let site = lookup(&d, \"owner.site\").?\n    expect_eq(as_bool(get(site, \"google.com\").?).?, true)\n    let ports = lookup(&d, \"database.connection.ports\").?\n    expect_eq(len(ports), 2)\n    expect_eq(as_int(at(ports, 1).?).?, 8001)\n    let order = keys(&d)\n    expect_eq(order.len, 3)\n    expect_eq(order[1], \"owner\")\n}\n\ntest \"strings\" {\n    let d = doc(\"a = \\\"tab\\\\there \\\\\\\"q\\\\\\\" \\\\u00e9 \\\\U0001F600\\\"\\nb = 'C:\\\\Users\\\\raw'\\nc = \\\"\\\"\\\"\\nfirst\\n  second\\\"\\\"\\\"\\nd = \\\"\\\"\\\"joined \\\\\\n     together\\\"\\\"\\\"\\ne = '''\\nraw \\\\n here\\n'''\\nf = \\\"\\\"\\\"\\\"quoted\\\" \\\"\\\"\\\"\\\"\\ng = ''''two'''''\\n\")\n    expect_eq(as_str(get(&d, \"a\").?).?, \"tab\\there \\\"q\\\" \\u{e9} \\u{1F600}\")\n    expect_eq(as_str(get(&d, \"b\").?).?, \"C:\\\\Users\\\\raw\")\n    expect_eq(as_str(get(&d, \"c\").?).?, \"first\\n  second\")\n    expect_eq(as_str(get(&d, \"d\").?).?, \"joined together\")\n    expect_eq(as_str(get(&d, \"e\").?).?, \"raw \\\\n here\\n\")\n    expect_eq(as_str(get(&d, \"f\").?).?, \"\\\"quoted\\\" \\\"\")\n    expect_eq(as_str(get(&d, \"g\").?).?, \"'two''\")\n}\n\ntest \"numbers\" {\n    let d = doc(\"a = +99\\nb = -17\\nc = 1_000_000\\nd = 0xDEAD_beef\\ne = 0o755\\nf = 0b1101\\ng = 9223372036854775807\\nh = -9223372036854775808\\ni = 3.1415\\nj = -2E-2\\nk = 6.626e-34\\nl = 224_617.445_991\\nm = inf\\nn = -inf\\no = nan\\np = 0\\nq = -0.0\\n\")\n    expect_eq(as_int(get(&d, \"a\").?).?, 99)\n    expect_eq(as_int(get(&d, \"b\").?).?, -17)\n    expect_eq(as_int(get(&d, \"c\").?).?, 1000000)\n    expect_eq(as_int(get(&d, \"d\").?).?, 3735928559)\n    expect_eq(as_int(get(&d, \"e\").?).?, 493)\n    expect_eq(as_int(get(&d, \"f\").?).?, 13)\n    expect_eq(as_int(get(&d, \"g\").?).?, 9223372036854775807)\n    expect(as_int(get(&d, \"h\").?).? == -9223372036854775807 - 1)\n    expect(as_float(get(&d, \"i\").?).? == 3.1415)\n    expect(as_float(get(&d, \"j\").?).? == -0.02)\n    expect(as_float(get(&d, \"l\").?).? == 224617.445991)\n    expect(as_float(get(&d, \"m\").?).? == math.INF)\n    expect(as_float(get(&d, \"n\").?).? == -math.INF)\n    let nan = as_float(get(&d, \"o\").?).?\n    expect(nan != nan)\n    expect_eq(as_int(get(&d, \"p\").?).?, 0)\n    expect(as_int(get(&d, \"i\").?) == null)\n    for bad in [\"x = 0123\\n\", \"x = 1__0\\n\", \"x = _1\\n\", \"x = 1_\\n\", \"x = .5\\n\", \"x = 5.\\n\", \"x = 3.e2\\n\", \"x = 0x\\n\", \"x = +0x1\\n\", \"x = 9223372036854775808\\n\", \"x = 1e\\n\", \"x = 01.5\\n\"] {\n        if problem(bad) == null { println(\"toml: `{}` was read\", .{bad}) }\n        expect(problem(bad) != null)\n    }\n}\n\ntest \"dates and times\" {\n    let d = doc(\"a = 1979-05-27T07:32:00Z\\nb = 1979-05-27T00:32:00.999999-07:00\\nc = 1979-05-27 07:32:00\\nd = 1979-05-27\\ne = 07:32:00\\nf = 2024-02-29\\n\")\n    expect(as_time(get(&d, \"a\").?).?.kind == StampKind.OffsetDateTime)\n    expect(as_time(get(&d, \"b\").?).?.kind == StampKind.OffsetDateTime)\n    expect(as_time(get(&d, \"c\").?).?.kind == StampKind.LocalDateTime)\n    expect_eq(as_time(get(&d, \"c\").?).?.text, \"1979-05-27 07:32:00\")\n    expect(as_time(get(&d, \"d\").?).?.kind == StampKind.LocalDate)\n    expect(as_time(get(&d, \"e\").?).?.kind == StampKind.LocalTime)\n    for bad in [\"x = 1979-13-27\\n\", \"x = 2023-02-29\\n\", \"x = 1979-05-27T25:00:00\\n\", \"x = 07:32\\n\", \"x = 1979-05-27T07:32:00+7\\n\", \"x = 1979-05-27X07:32:00\\n\"] {\n        if problem(bad) == null { println(\"toml: `{}` was read\", .{bad}) }\n        expect(problem(bad) != null)\n    }\n}\n\ntest \"arrays, inline tables and arrays of tables\" {\n    let d = doc(\"points = [ { x = 1, y = 2 }, { x = 7, y = 8 } ]\\nnested = [ [1, 2], ['a', \\\"b\\\"], [], ]\\nmixed = [\\n  1, # one\\n  2.0,\\n]\\ninline = { name.first = \\\"Tom\\\", last = \\\"P\\\" }\\n\\n[[fruit]]\\nname = \\\"apple\\\"\\n[fruit.physical]\\ncolor = \\\"red\\\"\\n[[fruit.variety]]\\nname = \\\"red delicious\\\"\\n[[fruit]]\\nname = \\\"banana\\\"\\n\")\n    expect_eq(len(get(&d, \"points\").?), 2)\n    expect_eq(as_int(get(at(get(&d, \"points\").?, 1).?, \"x\").?).?, 7)\n    expect_eq(len(at(get(&d, \"nested\").?, 2).?), 0)\n    expect_eq(len(get(&d, \"mixed\").?), 2)\n    expect_eq(as_str(lookup(&d, \"inline.name.first\").?).?, \"Tom\")\n    let fruit = get(&d, \"fruit\").?\n    expect_eq(len(fruit), 2)\n    expect_eq(as_str(lookup(at(fruit, 0).?, \"physical.color\").?).?, \"red\")\n    expect_eq(as_str(get(at(get(at(fruit, 0).?, \"variety\").?, 0).?, \"name\").?).?, \"red delicious\")\n    expect_eq(as_str(get(at(fruit, 1).?, \"name\").?).?, \"banana\")\n}\n\ntest \"a key or a table is defined once\" {\n    let bad = [\n        \"a = 1\\na = 2\\n\",\n        \"[t]\\n[t]\\n\",\n        \"a = {}\\n[a]\\n\",\n        \"a = { b = 1 }\\na.c = 2\\n\",\n        \"[fruit]\\napple.color = 'red'\\n[fruit.apple]\\n\",\n        \"[a.b]\\nc = 1\\n[a]\\nb.d = 2\\n\",\n        \"a = [1]\\n[[a]]\\n\",\n        \"[[a]]\\n[a]\\n\",\n        \"[a]\\n[[a]]\\n\",\n        \"a = 1 b = 2\\n\",\n        \"a = { b = 1, }\\n\",\n        \"a = { b = 1,\\n c = 2 }\\n\",\n        \"= 1\\n\",\n        \"a =\\n\",\n        \"[a\\n\",\n        \"a = \\\"open\\n\",\n        \"a = \\\"\\\"\\\"never closed\\n\",\n        \"a = \\\"bad \\\\q escape\\\"\\n\",\n    ]\n    for b in bad {\n        if problem(b) == null { println(\"toml: `{}` was read\", .{b}) }\n        expect(problem(b) != null)\n    }\n    // what the rules allow\n    let d = doc(\"[x.y.z]\\n[x]\\na = 1\\n[fruit]\\napple.color = 'red'\\n[fruit.apple.texture]\\nsmooth = true\\n\")\n    expect_eq(as_int(lookup(&d, \"x.a\").?).?, 1)\n    expect_eq(as_bool(lookup(&d, \"fruit.apple.texture.smooth\").?).?, true)\n    expect_eq(problem(\"a = 1\\na = 2\\n\").?, \"line 2: the key `a` is defined twice\")\n}\n\ntest \"writing, and reading back what was written\" {\n    let text = \"title = \\\"x \\\\\\\"y\\\\\\\"\\\"\\ncount = 3\\nratio = 2.0\\nwhen = 1979-05-27T07:32:00Z\\nlist = [1, 2, [\\\"a\\\", { k = true }]]\\n\\\"odd key\\\" = true\\n\\n[server]\\nhost = \\\"0.0.0.0\\\"\\n\\n[server.tls]\\non = false\\n\\n[[job]]\\nname = \\\"one\\\"\\n\\n[[job]]\\nname = \\\"two\\\"\\n\"\n    let d = doc(text)\n    let out = stringify(&d)\n    expect_eq(out, text)\n    let back = doc(out[..])\n    expect(same(&d, &back))\n    // an array of inline tables is written as the array of tables it is\n    let inline = doc(\"tables = [{ a = 1 }, { a = 2 }]\\n\")\n    expect_eq(stringify(&inline), \"[[tables]]\\na = 1\\n\\n[[tables]]\\na = 2\\n\")\n    let empty = doc(\"\")\n    expect_eq(len(&empty), 0)\n    expect_eq(stringify(&empty), \"\")\n}\n";
