static const char nx_str_1533[1226] = "// topo: fill in the blank\n// `term` handles `*` and `/`; replace ??? so it handles `%`, the remainder, at the same level.\n// hint: the other two arms of the same `if` show the shape; `%` is Nexium's remainder too\nstruct Cursor {\n    toks: List([]u8)\n    pos: usize\n}\n\nfn number(c: *mut Cursor) -> i64 {\n    let v = c.toks[c.pos].parse_int(i64) catch { 0 }\n    c.pos += 1\n    return v\n}\n\nfn term(c: *mut Cursor) -> i64 {\n    var v = number(c)\n    while c.pos < c.toks.len {\n        let op = c.toks[c.pos]\n        if op == \"*\" {\n            c.pos += 1\n            v = v * number(c)\n        } else if op == \"/\" {\n            c.pos += 1\n            v = v / number(c)\n        } else if op == \"%\" {\n            ???\n        } else {\n            break\n        }\n    }\n    return v\n}\n\nfn expression(c: *mut Cursor) -> i64 {\n    var v = term(c)\n    while c.pos < c.toks.len {\n        let op = c.toks[c.pos]\n        c.pos += 1\n        if op == \"+\" { v = v + term(c) } else { v = v - term(c) }\n    }\n    return v\n}\n\nfn calc(text: []u8) -> i64 {\n    var c = Cursor{ .toks = text.split(\" \"), .pos = 0 }\n    return expression(&mut c)\n}\n\nfn main() {\n    println(\"{} {} {}\", .{calc(\"7 + 10 % 4 * 2\"), calc(\"100 % 7\"), calc(\"20 - 9 % 5\")})\n}\n";
