static const char nx_str_1541[609] = "// topo: predict the output\n// Write what this prints into predict_power.guess before you run it.\n// hint: `power` calls itself for everything to the right of the first number, as the chapter's parser does\nfn power(xs: []i64, i: *mut usize) -> i64 {\n    let base = xs[i.*]\n    i.* += 1\n    if i.* == xs.len { return base }\n    let exp = power(xs, i)\n    var r: i64 = 1\n    for _ in 0..exp { r *= base }\n    return r\n}\n\nfn main() {\n    // 2 ^ 3 ^ 2, and 4 ^ 1 ^ 2\n    var i: usize = 0\n    let a = power([2, 3, 2][..], &mut i)\n    i = 0\n    let b = power([4, 1, 2][..], &mut i)\n    println(\"{} {}\", .{a, b})\n}\n";
