static const char nx_str_1550[950] = "import std.json\n\nstruct Item {\n    text: String\n    done: bool\n}\n\nfn item_json(item: *Item) -> String {\n    var doc = json.object()\n    json.set(&mut doc, \"text\", json.string(item.text[..]))\n    json.set(&mut doc, \"done\", json.boolean(item.done))\n    return json.stringify(&doc)\n}\n\nfn main() {\n    let item = Item{ .text = String.from(\"buy rope\"), .done = false }\n    println(\"{}\", .{item_json(&item)})\n}\n\ntest \"an open item\" {\n    let item = Item{ .text = String.from(\"buy rope\"), .done = false }\n    expect_eq(item_json(&item)[..], \"{\\\"text\\\":\\\"buy rope\\\",\\\"done\\\":false}\")\n}\n\ntest \"a finished item\" {\n    let item = Item{ .text = String.from(\"pack the tent\"), .done = true }\n    expect_eq(item_json(&item)[..], \"{\\\"text\\\":\\\"pack the tent\\\",\\\"done\\\":true}\")\n}\n\ntest \"quotes are escaped\" {\n    let item = Item{ .text = String.from(\"say \\\"hi\\\"\"), .done = false }\n    expect_eq(item_json(&item)[..], \"{\\\"text\\\":\\\"say \\\\\\\"hi\\\\\\\"\\\",\\\"done\\\":false}\")\n}\n";
