static const char nx_str_1585[1234] = "// topo: fill in the blank\n// Replace ??? so `/greet` greets the `name` query parameter, or \"stranger\" when there is none.\n// hint: `req.param(name)` is an optional; one keyword gives it a default (chapter 6)\n// hint: a router needs no socket: `router.handle(&req)` is a plain call, which is how a handler is tested\nimport std.http\n\nfn greet(req: *http.Request) -> http.Response {\n    var body = String.from(\"hello, \")\n    body.append(req.param(\"name\") ??? \"stranger\")\n    return http.text(200, body[..])\n}\n\nfn health(req: *http.Request) -> http.Response {\n    _ = req\n    return http.text(200, \"ok\")\n}\n\nfn get(path: []u8, query: []u8) -> http.Request {\n    return http.Request{\n        .method = String.from(\"GET\"), .path = String.from(path), .query = String.from(query),\n        .headers = List(http.Header).new(), .body = String.new(), .peer = String.from(\"test\"),\n    }\n}\n\nfn main() {\n    var router = http.Router.new()\n    router.get(\"/greet\", greet)\n    router.get(\"/health\", health)\n    let a = get(\"/greet\", \"name=Maurice\")\n    let b = get(\"/greet\", \"\")\n    let c = get(\"/nowhere\", \"\")\n    for req in [a, b, c] {\n        let resp = router.handle(&req)\n        println(\"{} {} {}\", .{req.path, resp.status, resp.body})\n    }\n}\n";
