static const char nx_str_1591[873] = "fn param(query: []u8, name: []u8) -> ?[]u8 {\n    if query.len == 0 { return null }\n    for pair in query.split(\"&\") {\n        if let eq = pair.find(\"=\") {\n            if pair[0..eq] == name { return pair[eq + 1..pair.len] }\n        } else if pair == name {\n            return pair[0..0]\n        }\n    }\n    return null\n}\n\nfn main() {\n    println(\"{}\", .{param(\"q=nexium&page=2\", \"page\") orelse \"none\"})\n}\n\ntest \"the value of a key\" { expect_eq(param(\"q=nexium&page=2\", \"q\") orelse \"none\", \"nexium\") }\ntest \"a later key\" { expect_eq(param(\"q=nexium&page=2\", \"page\") orelse \"none\", \"2\") }\ntest \"a key without a value\" { expect_eq(param(\"debug&q=1\", \"debug\") orelse \"none\", \"\") }\ntest \"a missing key\" { expect(param(\"q=1\", \"page\") == null) }\ntest \"a prefix is not the key\" { expect(param(\"pages=3\", \"page\") == null) }\ntest \"an empty query\" { expect(param(\"\", \"q\") == null) }\n";
