static const char nx_str_1593[989] = "// topo: fill in the blank\n// A canvas is one list of pixels, row after row. Replace ??? with the index of the pixel at\n// column `x + i`, row `y + j`, so `fill_rect` paints the rectangle the picture shows.\n// hint: every row before row `r` holds `self.w` pixels, so row `r` starts at `r * self.w`\nstruct Canvas {\n    w: usize\n    h: usize\n    px: List(u8)\n}\n\nimpl Canvas {\n    fn new(w: usize, h: usize) -> Canvas {\n        var px = List(u8).new()\n        for _ in 0..w * h { px.append('.') }\n        return Canvas{ .w = w, .h = h, .px = px }\n    }\n\n    fn fill_rect(self: *mut Self, x: usize, y: usize, w: usize, h: usize, c: u8) {\n        for j in 0..h {\n            for i in 0..w { self.px[???] = c }\n        }\n    }\n\n    fn show(self: *Self) {\n        for r in 0..self.h { println(\"{}\", .{self.px[r * self.w..(r + 1) * self.w]}) }\n    }\n}\n\nfn main() {\n    var canvas = Canvas.new(12, 5)\n    canvas.fill_rect(1, 1, 4, 3, '#')\n    canvas.fill_rect(7, 0, 3, 2, '+')\n    canvas.show()\n}\n";
