static const char nx_str_1597[942] = "// topo: predict the output\n// Write what this prints into predict_frames.guess before you run it.\n// hint: `button` draws and answers in the same call: it is true only in the frame its click lands in\n// hint: a widget exists in a frame only if the code calls it in that frame\nstruct Ui {\n    frame: u32\n}\n\nimpl Ui {\n    /// The mouse, scripted: `+` is clicked in frame 1, `reset` in frame 3.\n    fn clicked(self: *Self, label: []u8) -> bool {\n        return (self.frame == 1 and label == \"+\") or (self.frame == 3 and label == \"reset\")\n    }\n\n    fn button(self: *Self, label: []u8) -> bool {\n        print(\"[{}] \", .{label})\n        return self.clicked(label)\n    }\n}\n\nfn main() {\n    var ui = Ui{ .frame = 0 }\n    var count: u32 = 0\n    while ui.frame < 5 {\n        if ui.button(\"+\") { count += 1 }\n        if count > 0 and ui.button(\"reset\") { count = 0 }\n        println(\"frame {}: {}\", .{ui.frame, count})\n        ui.frame += 1\n    }\n}\n";
