static const char nx_str_1600[1062] = "// topo: write it\n// A package is published by tagging it. Fill in `newer` so the tests pass: whether tag `a`\n// is a later version than tag `b`, comparing major, minor and patch as numbers.\n// hint: `strings.strip_prefix(tag, \"v\")` drops the `v`; `split(\".\")` gives the three parts\n// hint: compare as numbers: \"1.10.0\" is newer than \"1.9.3\", though \"1\" < \"9\" as text\nimport std.strings\n\nfn parts(tag: []u8) -> List(u32) {\n    let t = strings.strip_prefix(tag, \"v\") orelse tag\n    var out = List(u32).new()\n    for p in t.split(\".\") { out.append(p.parse_int(u32) catch { 0 }) }\n    return out\n}\n\nfn newer(a: []u8, b: []u8) -> bool {\n    ???\n}\n\nfn main() {\n    println(\"{} {}\", .{newer(\"v1.10.0\", \"v1.9.3\"), newer(\"v1.2.0\", \"v1.2.1\")})\n}\n\ntest \"a later minor\" { expect(newer(\"v1.10.0\", \"v1.9.3\")) }\ntest \"an earlier patch\" { expect(!newer(\"v1.2.0\", \"v1.2.1\")) }\ntest \"the same version\" { expect(!newer(\"v1.2.1\", \"v1.2.1\")) }\ntest \"a later major beats everything\" { expect(newer(\"v2.0.0\", \"v1.99.99\")) }\ntest \"without the v\" { expect(newer(\"0.10.1\", \"0.9.0\")) }\n";
