static const char nx_str_1608[696] = "// topo: fix the error\n// A slice cannot be returned across the C boundary: nothing on the other side would know when\n// to free it. Make `upper` write into the caller's buffer instead and return how many bytes\n// it wrote, so the program prints the recorded output.\n// hint: a `[]mut u8` parameter is the caller's memory; the result can be a `usize`\n// hint: `main` shows how the caller will use it\nfn upper(text: []u8) -> []u8 export(c) {\n    var out = String.new()\n    for b in text { out.push_byte(if b >= 'a' and b <= 'z' { b - 32 } else { b }) }\n    return out[..]\n}\n\nfn main() {\n    var buf: [16]u8 = undefined\n    let n = upper(\"nexium\", buf[..])\n    println(\"{} {}\", .{buf[0..n], n})\n}\n";
