static const char nx_str_1612[796] = "// topo: fill in the blank\n// One neuron learns: each epoch runs it forward, measures how far it is from the target, and\n// moves its weight against the gradient. Replace ??? with the sigmoid's derivative, written in\n// terms of its output `y`, so the output climbs toward the target.\n// hint: for y = sigmoid(z), dy/dz = y * (1 - y); the chapter's `backward` folds in the same factor\nfn sigmoid(z: f64) -> f64 {\n    return 1.0 / (1.0 + math.exp(-z))\n}\n\nfn main() {\n    var w = 0.5\n    let x = 1.0\n    let target = 1.0\n    for epoch in 0..4 {\n        let y = sigmoid(w * x)\n        // the loss is (y - target)^2 / 2, so d(loss)/dy is y - target\n        let dy = y - target\n        let dz = dy * ???\n        w -= 2.0 * dz * x\n        println(\"epoch {}: y {:.4}, w {:.4}\", .{epoch, y, w})\n    }\n}\n";
