static const char nx_str_1614[421] = "fn sigmoid(z: f64) -> f64 {\n    return 1.0 / (1.0 + math.exp(-z))\n}\n\nfn main() {\n    var w = 0.5\n    let x = 1.0\n    let target = 1.0\n    for epoch in 0..4 {\n        let y = sigmoid(w * x)\n        // the loss is (y - target)^2 / 2, so d(loss)/dy is y - target\n        let dy = y - target\n        let dz = dy * y * (1.0 - y)\n        w -= 2.0 * dz * x\n        println(\"epoch {}: y {:.4}, w {:.4}\", .{epoch, y, w})\n    }\n}\n";
